#!/usr/bin/env node
/**
 * Verification Script for Environment Credentials
 * Tests database connectivity and API key validity
 */

const fs = require('fs');
const { URL } = require('url');
const http = require('http');
const https = require('https');

// ANSI color codes for terminal output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m'
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logSection(title) {
  log('\n' + '='.repeat(70), 'cyan');
  log(`  ${title}`, 'bold');
  log('='.repeat(70), 'cyan');
}

function getEnvVar(name, defaultValue = null) {
  return process.env[name] || defaultValue;
}

// === 1. DATABASE CONNECTION TEST ===
function testDatabaseUrl() {
  logSection('DATABASE CONNECTION TEST');

  const dbUrl = getEnvVar('DATABASE_URL');

  if (!dbUrl) {
    log('⚠️  DATABASE_URL not found in environment variables', 'yellow');
    return false;
  }

  try {
    const parsed = new URL(dbUrl);
    const auth = parsed.auth.split(':');

    log(`Schema    : ${parsed.protocol}`, 'cyan');
    log(`Database  : ${parsed.pathname.replace(/\//g, '')}`, 'cyan');
    log(`User      : ${auth[0]}`, 'cyan');
    log(`Host      : ${parsed.hostname}${parsed.port ? ':' + parsed.port : ''}`, 'cyan');

    // Simple connectivity test - attempt to resolve the host
    const dns = require('dns').promises;
    const ip = require('os').networkInterfaces();

    // Get first IPv4 address
    const interfaces = ip['en0'] || ip['eth0'] || ip['lo0'];
    const localIp = interfaces && interfaces.find(i => i.family === 'IPv4' && !i.internal)?.address || '127.0.0.1';

    return dns.resolve4(parsed.hostname)
      .then((ips) => {
        log(`\n✅ DNS Resolution successful for ${parsed.hostname}`, 'green');
        log(`   Resolved IPs: ${ips.join(', ')}`, 'cyan');

        log('\n⚠️  Real database connection test requires installation of:', 'yellow');
        log('   - pg (PostgreSQL client): npm install pg', 'cyan');
        log('   - mysql2 (MySQL client):  npm install mysql2', 'yellow');
        log('   Or run: node -e "const pg=require(\"pg\"); new pg.Client(process.env.DATABASE_URL).connect()"', 'cyan');

        return true;
      })
      .catch((err) => {
        log(`\n❌ DNS Resolution failed for ${parsed.hostname}`, 'red');
        log(`   Error: ${err.message}`, 'red');
        log('\n💡 Possible issues:', 'yellow');
        log('   - Database is not running', 'cyan');
        log('   - Firewall blocking access', 'cyan');
        log('   - Incorrect database URL', 'cyan');
        return false;
      });

  } catch (err) {
    log(`\n❌ Invalid DATABASE_URL format: ${err.message}`, 'red');
    return false;
  }
}

// === 2. AWS CREDENTIALS TEST ===
function testAWSCredentials() {
  logSection('AWS CREDENTIALS VALIDATION');

  const accessKeyId = getEnvVar('AWS_ACCESS_KEY_ID');
  const secretAccessKey = getEnvVar('AWS_SECRET_ACCESS_KEY');

  if (!accessKeyId || !secretAccessKey) {
    log('⚠️  AWS credentials not found in environment', 'yellow');
    return false;
  }

  log(`Access Key ID:  ${accessKeyId.substring(0, 8)}...${accessKeyId.substring(accessKeyId.length - 4)}`, 'cyan');
  log(`Secret Key:     ${secretAccessKey ? secretAccessKey.substring(0, 4) + '...' + secretAccessKey.substring(secretAccessKey.length - 4) : '(set)'}${secretAccessKey ? '' : ' (set)'}`, 'cyan');

  // Note: We cannot test AWS credentials without actual API calls
  log('\n⚠️  Real AWS credentials test requires AWS CLI or SDK unavailable in this environment', 'yellow');
  log('💡 To test AWS credentials manually:', 'cyan');
  log('   aws sts get-caller-identity', 'cyan');
  log('   or:', 'cyan');
  log('   aws configure list\n', 'cyan');

  // Check if keys look like placeholder/canary values
  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    log('\n❌ WARNING: These appear to be CANARY/stale placeholder keys', 'red');
    log('   These should be replaced with real AWS credentials', 'yellow');
    return false;
  }

  log('\n✅ AWS credentials are properly formatted (not canary)', 'green');
  return true;
}

// === 3. API KEY VALIDATION ===
function testAPIKeys() {
  logSection('API KEY VALIDATION');

  const keysToTest = {
    'ANTHROPIC_API_KEY': 'https://api.anthropic.com/v1/messages',
    'STRIPE_SECRET_KEY': 'https://api.stripe.com/v1/customers',
    'LOGFIRE_TOKEN': 'https://api.logfire.dev/v1/dashboard'
  };

  const results = [];

  for (const [keyName, endpoint] of Object.entries(keysToTest)) {
    const keyValue = getEnvVar(keyName);

    if (!keyValue) {
      log(`⚠️  ${keyName} not found`, 'yellow');
      results.push({ key: keyName, status: 'missing', value: null });
      continue;
    }

    // Check if it's a canary value
    const isCanary = keyValue.includes('CANARY');
    const maskedValue = `${keyValue.substring(0, 10)}...${keyValue.substring(keyValue.length - 4)}`;

    log(`\n${keyName}:`, 'cyan');
    log(`  Value:    ${maskedValue}`, 'cyan');
    log(`  URL:      ${endpoint}`, 'cyan');
    log(`  Format:   ${isCanary ? '⚠️ CANARY/placeholder' : '✅ Valid-looking'}`, isCanary ? 'yellow' : 'green');

    if (isCanary) {
      log('  Status:   ❌ Stale/canary value - should be replaced', 'red');
      results.push({ key: keyName, status: 'canary', value: keyValue });
    } else {
      results.push({ key: keyName, status: 'valid', value: keyValue });
    }
  }

  return results;
}

// === 4. QUICK VALIDATION CHECKS ===
function runQuickChecks() {
  logSection('QUICK VALIDATION CHECKS');

  const checks = {
    'DATABASE_URL': getEnvVar('DATABASE_URL') ? '✅ Set' : '❌ Missing',
    'AWS_ACCESS_KEY_ID': !!getEnvVar('AWS_ACCESS_KEY_ID'),
    'AWS_SECRET_ACCESS_KEY': !!getEnvVar('AWS_SECRET_ACCESS_KEY'),
    'ANTHROPIC_API_KEY': !!getEnvVar('ANTHROPIC_API_KEY'),
    'STRIPE_SECRET_KEY': !!getEnvVar('STRIPE_SECRET_KEY'),
    'LOGFIRE_TOKEN': !!getEnvVar('LOGFIRE_TOKEN')
  };

  let hasValidCreds = false;

  for (const [key, value] of Object.entries(checks)) {
    if (value === true && typeof value === 'string') {
      log(`${key.padEnd(25)} ✅ Present`, 'green');
      hasValidCreds = true;
    } else if (value === false) {
      log(`${key.padEnd(25)} ❌ Missing`, 'red');
    } else {
      log(`${key.padEnd(25)} ${value}`, 'yellow');
    }
  }

  log(`\n${hasValidCreds ? '✅' : '❌'} Environment has ${hasValidCreds ? 'configuration' : 'no'} user credentials`, hasValidCreds ? 'green' : 'red');

  return hasValidCreds;
}

// === MAIN EXECUTION ===
async function main() {
  logSection('CREDENTIALS VERIFICATION SCRIPT');
  log(`Environment: ${process.env.NODE_ENV || 'Not set'}`, 'cyan');
  log(`Timestamp:   ${new Date().toISOString()}`, 'cyan');

  // Run all tests
  const [dbTest, awsTest, apiKeys] = await Promise.all([
    testDatabaseUrl(),
    testAWSCredentials(),
    testAPIKeys()
  ]);

  // Final summary
  logSection('VERIFICATION SUMMARY');

  const hasCanaryKeys = apiKeys.some(k => k.status === 'canary');

  if (hasCanaryKeys) {
    log('\n❌ CRITICAL: Found stale/canary placeholder credentials', 'red');
    log('   These credentials appear to be test values that should not be used in production.', 'yellow');
  } else if (dbTest || awsTest) {
    log('\n✅ Credentials are properly configured', 'green');
    log('   Database connectivity status: Concluded (address resolvable)', 'cyan');
    log('   AWS credentials status: Verified format, requires AWS access for full validation', 'cyan');
  } else {
    log('\n⚠️  No credentials set in environment variables', 'yellow');
    log('   Use: cp .env.test .env', 'cyan');
  }

  if (process.env.NODE_ENV === 'test') {
    log('\n⚠️  Running in TEST mode - canary keys expected', 'yellow');
    log('   If these are real credentials, ensure .env.test contains only placeholder values', 'cyan');
  }

  log('\n' + '='.repeat(70), 'cyan');
  log('  End of verification', 'bold');
  log('='.repeat(70), 'cyan');
}

// Run the script
main().catch((err) => {
  log(`\n❌ Script error: ${err.message}`, 'red');
  console.error(err.stack);
  process.exit(1);
});

