  log(`  ${title}`, 'bold');
  log('='.repeat(70), 'cyan');
}

function containsCanary(str) {
  return canaryKeywords.some(keyword => (str || '').toUpperCase().includes(keyword));
}

// Parse URL to validate format
function parseDatabaseUrl(url) {
  if (!url) return null;

  try {
    const parsed = new URL(url);
    const auth = (parsed.auth || '').split(':');

    // Get database name from pathname (remove leading slashes)
    const dbName = parsed.pathname.replace(/\//g, '');

    return {
      success: true,
      protocol: parsed.protocol,
      host: parsed.hostname,
      port: parsed.port,
      path: parsed.pathname,
      database: dbName,
      user: auth[0],
      password: auth[1]
    };
  } catch (err) {
    return { success: false, error: err.message };
  }
}

