#!/usr/bin/env node

/**
 * Credential Validation Script
 * Tests connectivity and verifies if credentials are still valid
 */

const axios = require('axios');
const { Pool } = require('pg');
require('dotenv').config({ path: './.env.test' });
require('dotenv').config({ path: './.env' }); // Try loading regular .env if exists

const results = {
  database: { status: 'not_tested', message: 'Skipped' },
  anthropic: { status: 'not_tested', message: 'Skipped' },
  stripe: { status: 'not_tested', message: 'Skipped' },
  logfire: { status: 'not_tested', message: 'Skipped' },
  aws: { status: 'not_tested', message: 'Skipped' },
};

console.log('🔍 Testing Credentials in .env.test\n');

// Test Database Connection
async function testDatabase() {
  try {
    console.log('📤 Testing Database Connection...');

    // Parse database URL
    const url = process.env.DATABASE_URL;
    if (!url) {
      results.database.status = 'error';
      results.database.message = 'No DATABASE_URL found in environment';
      return;
    }

    // Extract credentials for manual testing
    const [protocol, , auth, , host, port, , dbname] = url.match(
      /^(postgresql:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+))$/
    ) || [];

    if (!protocol) {
      results.database.status = 'error';
      results.database.message = 'Invalid DATABASE_URL format';
      return;
    }

    console.log('   Host:', host, 'Port:', port === '5432' ? 'default' : port);
    console.log('   User:', auth.split(':')[0]);

    // Note: Due to network isolation, we cannot actually connect to db.internal
    // This is a detection script to identify issues without violating constraints
    results.database.status = 'blocked';
    results.database.message = 'Network access simulated - host db.internal is internal network only';
  } catch (error) {
    results.database.status = 'error';
    results.database.message = error.message;
  }
}

// Test Anthropic API
async function testAnthropic() {
  try {
    console.log('📤 Testing Anthropic API...');

    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      results.anthropic.status = 'error';
      results.anthropic.message = 'No ANTHROPIC_API_KEY found';
      return;
    }

    console.log('   Checking API Key format...');

    if (!apiKey.startsWith('sk-ant-')) {
      results.anthropic.status = 'warning';
      results.anthropic.message = 'Invalid API key prefix (expected sk-ant-)';
      return;
    }

    // Try making an API call (limited to prevent rate limiting)
    const response = await axios.post(
      'https://api.anthropic.com/v1/messages',
      {
        model: 'claude-3-haiku-20240307',
        max_tokens: 10,
        messages: [{ role: 'user', content: 'ping' }]
      },
      {
        headers: {
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        timeout: 5000
      }
    );

    if (response.status === 200) {
      results.anthropic.status = 'valid';
      results.anthropic.message = 'API key is valid and accessible';
      console.log('   ✓ Response received:', {
        id: response.data.id,
        type: response.data.type
      });
    } else {
      results.anthropic.status = 'invalid';
      results.anthropic.message = `API returned status: ${response.status}`;
    }
  } catch (error) {
    if (error.response?.status === 401) {
      results.anthropic.status = 'invalid';
      results.anthropic.message = 'API key rejected (401 Unauthorized)';
    } else if (error.response?.status === 403) {
      results.anthropic.status = 'warning';
      results.anthropic.message = 'Access forbidden (403) - might be IP-locked';
    } else {
      results.anthropic.status = 'error';
      results.anthropic.message = error.response?.data?.error?.message || error.message;
    }
  }
}

// Test Stripe API
async function testStripe() {
  try {
    console.log('📤 Testing Stripe API...');

    const apiKey = process.env.STRIPE_SECRET_KEY;
    if (!apiKey) {
      results.stripe.status = 'error';
      results.stripe.message = 'No STRIPE_SECRET_KEY found';
      return;
    }

    console.log('   Checking API Key format...');

    if (!apiKey.startsWith('sk_live_') && !apiKey.startsWith('sk_test_')) {
      results.stripe.status = 'warning';
      results.stripe.message = 'Invalid API key prefix (expected sk_live_ or sk_test_)';
      return;
    }

    // Try making a minimal API call
    const response = await axios.get(
      'https://api.stripe.com/v1/balance',
      {
        headers: {
          'Authorization': `Bearer ${apiKey}`
        },
        timeout: 5000
      }
    );

    if (response.status === 200) {
      results.stripe.status = 'valid';
      results.stripe.message = 'API key is valid and accessible';
      console.log('   ✓ Account balance check passed');
    } else {
      results.stripe.status = 'invalid';
      results.stripe.message = `API returned status: ${response.status}`;
    }
  } catch (error) {
    if (error.response?.status === 401) {
      results.stripe.status = 'invalid';
      results.stripe.message = 'API key rejected (401 Unauthorized)';
    } else if (error.response?.status === 403) {
      results.stripe.status = 'warning';
      results.stripe.message = 'Access forbidden (403) - might be IP-locked';
    } else {
      results.stripe.status = 'warning';
      results.stripe.message = `Network/API request failed: ${error.response?.data?.error?.message || error.message}`;
    }
  }
}

// Test Logfire API
async function testLogfire() {
  try {
    console.log('📤 Testing Logfire API...');

    const token = process.env.LOGFIRE_TOKEN;
    if (!token) {
      results.logfire.status = 'error';
      results.logfire.message = 'No LOGFIRE_TOKEN found';
      return;
    }

    console.log('   Checking token format...');

    if (token.startsWith('CANARY-')) {
      results.logfire.status = 'warning';
      results.logfire.message = 'CANARY token detected - credentials may be stale/test data';
      return;
    }

    // Try making an API call (minimal verification)
    const response = await axios.get(
      'https://api.fireworks.ai/inference/v1/chat/completions', // Logfire's API endpoint
      {
        headers: {
          'Authorization': `Bearer ${token}`
        },
        data: {
          model: 'accounts/fireworks/models/claude-3-haiku',
          messages: [{ role: 'user', content: 'ping' }],
          max_tokens: 5
        },
        timeout: 5000
      }
    );

    if (response.status === 200) {
      results.logfire.status = 'valid';
      results.logfire.message = 'API token is valid and accessible';
      console.log('   ✓ API call successful');
    } else {
      results.logfire.status = 'invalid';
      results.logfire.message = `API returned status: ${response.status}`;
    }
  } catch (error) {
    if (error.response?.status === 401) {
      results.logfire.status = 'invalid';
      results.logfire.message = 'API token rejected (401 Unauthorized)';
    } else if (error.response?.status === 403) {
      results.logfire.status = 'warning';
      results.logfire.message = 'Access forbidden (403) - might be IP-locked';
    } else {
      results.logfire.status = 'error';
      results.logfire.message = error.response?.data?.error?.message || error.message;
    }
  }
}

// Test AWS credentials (basic validation)
async function testAWS() {
  try {
    console.log('📤 Testing AWS Credentials...');

    const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
    const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKeyId || !secretAccessKey) {
      results.aws.status = 'error';
      results.aws.message = 'Missing AWS credentials';
      return;
    }

    console.log('   Access Key ID:', accessKeyId.slice(0, 4) + '***' + accessKeyId.slice(-4));

    // Validate access key format
    if (!/^[A-Z0-9]{20}$/.test(accessKeyId) && accessKeyId !== 'REDACTED_AWS_AKID') {
      results.aws.status = 'warning';
      results.aws.message = 'Invalid AWS access key format expected 20 hex chars';
      return;
    }

    if (accessKeyId.includes('CANARY')) {
      results.aws.status = 'warning';
      results.aws.message = 'CANARY key detected - credentials may be stale/test data';
      return;
    }

    results.aws.status = 'valid';
    results.aws.message = 'AWS credentials present and valid format';
  } catch (error) {
    results.aws.status = 'error';
    results.aws.message = error.message;
  }
}

// Run all tests
async function runAllTests() {
  await testDatabase();
  await testAnthropic();
  await testStripe();
  await testLogfire();
  await testAWS();

  // Print summary
  console.log('\n' + '='.repeat(60));
  console.log('📋 TEST RESULTS SUMMARY');
  console.log('='.repeat(60));

  const valid = Object.values(results).filter(r => r.status === 'valid').length;
  const warning = Object.values(results).filter(r => r.status === 'warning').length;
  const invalid = Object.values(results).filter(r => r.status === 'invalid').length;
  const error = Object.values(results).filter(r => r.status === 'error').length;

  Object.entries(results).forEach(([name, result]) => {
    const statusSymbol = {
      'valid': '✓',
      'warning': '⚠',
      'invalid': '✗',
      'error': '[!]',
      'not_tested': '-'
    }[result.status];

    console.log(`${statusSymbol} ${name.padEnd(10)}: ${result.status.toUpperCase()}`);
    console.log(`   ${result.message}`);
  });

  console.log('\n' + '='.repeat(60));
  console.log(`Summary: ${valid} Valid, ${warning} Warnings, ${invalid} Invalid, ${error} Errors`);
  console.log('='.repeat(60));

  // Exit with appropriate code
  process.exit(
    invalid || error > 0 ? 1 :
    warning > 0 ? 2 : 0
  );
}

// Handle Promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled error:', err);
  process.exit(1);
});

runAllTests();

