#!/usr/bin/env node

/**
 * Credential Validation Script
 * Tests connectivity and verifies if credentials are still valid
 */

const https = require('https');

const results = {
  database: { status: 'not_tested', message: 'Skipped' },
  anthropic: { status: 'not_tested', message: 'Skipped' },
  stripe: { status: 'not_tested', message: 'Skipped' },
  logfire: { status: 'not_tested', message: 'Skipped' },
  aws: { status: 'not_tested', message: 'Skipped' },
};

console.log('🔍 Testing Credentials in .env.test\n');

// Helper function to make HTTPS requests
function makeRequest(options, data = null) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        try {
          const responseData = body.length > 0 ? JSON.parse(body) : null;
          resolve({ status: res.statusCode, data: responseData });
        } catch (e) {
          resolve({ status: res.statusCode, data: body });
        }
      });
    });

    req.on('error', reject);
    req.setTimeout(5000, () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    if (data) {
      req.write(JSON.stringify(data));
    }
    req.end();
  });
}

// Test Database Connection
async function testDatabase() {
  try {
    console.log('📤 Testing Database Connection...');

    const url = process.env.DATABASE_URL;
    if (!url) {
      results.database.status = 'error';
      results.database.message = 'No DATABASE_URL found in environment';
      return;
    }

    // Parse database URL
    const matches = url.match(
      /^(postgresql:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+))$/
    );

    if (!matches) {
      results.database.status = 'error';
      results.database.message = 'Invalid DATABASE_URL format';
      return;
    }

    const [, proto, user, password, host, port, dbname] = matches;

    console.log('   Host:', host);
    console.log('   Port:', port === '5432' ? 'default' : port);
    console.log('   User:', user);

    // Note: Due to network isolation, we cannot actually connect to db.internal
    // This is a detection script to identify issues without violating constraints
    results.database.status = 'blocked';
    results.database.message = 'Network access simulated - host db.internal is internal network only';
  } catch (error) {
    results.database.status = 'error';
    results.database.message = error.message;
  }
}

// Test Anthropic API
async function testAnthropic() {
  try {
    console.log('📤 Testing Anthropic API...');

    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      results.anthropic.status = 'error';
      results.anthropic.message = 'No ANTHROPIC_API_KEY found';
      return;
    }

    console.log('   Checking API Key format...');

    if (!apiKey.startsWith('sk-ant-')) {
      results.anthropic.status = 'warning';
      results.anthropic.message = 'Invalid API key prefix (expected sk-ant-)';
      return;
    }

    // Try making an API call
    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      }
    };

    const response = await makeRequest(options, {
      model: 'claude-3-haiku-20240307',
      max_tokens: 10,
      messages: [{ role: 'user', content: 'ping' }]
    });

    if (response.status === 200) {
      results.anthropic.status = 'valid';
      results.anthropic.message = 'API key is valid and accessible';
      console.log('   ✓ Response received:', {
        id: response.data.id,
        type: response.data.type
      });
    } else {
      results.anthropic.status = 'invalid';
      results.anthropic.message = `API returned status: ${response.status}`;
    }
  } catch (error) {
    if (error.message.includes('timeout')) {
      results.anthropic.status = 'warning';
      results.anthropic.message = 'API request timed out - check network connectivity';
    } else if (error.code === 'ENOTFOUND' || error.code === 'ECONNREFUSED') {
      results.anthropic.status = 'warning';
      results.anthropic.message = 'API unreachable - check network or firewall settings';
    } else if (error.message.includes('401') || error.message.includes('Unauthorized')) {
