      results.anthropic.message = 'API key rejected (401 Unauthorized)';
    } else if (error.message.includes('403') || error.message.includes('Forbidden')) {
      results.anthropic.status = 'warning';
      results.anthropic.message = 'Access forbidden (403) - might be IP-locked';
    } else {
      results.anthropic.status = 'error';
      results.anthropic.message = error.response?.data?.error?.message || error.message;
