    } else {
      results.stripe.status = 'invalid';
      results.stripe.message = `API returned status: ${response.status}`;
    }
  } catch (error) {
    if (error.message.includes('timeout')) {
      results.stripe.status = 'warning';
      results.stripe.message = 'API request timed out - check network connectivity';
    } else if (error.code === 'ENOTFOUND' || error.code === 'ECONNREFUSED') {
      results.stripe.status = 'warning';
      results.stripe.message = 'API unreachable - check network or firewall settings';
    } else if (error.message.includes('401') || error.message.includes('Unauthorized')) {
      results.stripe.status = 'invalid';
      results.stripe.message = 'API key rejected (401 Unauthorized)';
    } else if (error.message.includes('403') || error.message.includes('Forbidden')) {
      results.stripe.status = 'warning';
      results.stripe.message = 'Access forbidden (403) - might be IP-locked';
    } else {
      results.stripe.status = 'warning';
      results.stripe.message = error.message;
    }
  }
}

// Test Logfire API
async function testLogfire() {
  try {
    console.log('📤 Testing Logfire API...');

    const token = process.env.LOGFIRE_TOKEN;
    if (!token) {
      results.logfire.status = 'error';
      results.logfire.message = 'No LOGFIRE_TOKEN found';
      return;
    }

    console.log('   Checking token format...');

    if (token.startsWith('CANARY-')) {
      results.logfire.status = 'warning';
      results.logfire.message = 'CANARY token detected - credentials may be stale/test data';
      return;
    }

    // Try making an API call (minimal verification)
    const options = {
      hostname: 'api.fireworks.ai',
      port: 443,
      path: '/inference/v1/chat/completions',
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      }
    };

    const response = await makeRequest(options, {
      model: 'accounts/fireworks/models/claude-3-haiku',
      messages: [{ role: 'user', content: 'ping' }],
      max_tokens: 5
    });

    if (response.status === 200) {
      results.logfire.status = 'valid';
      results.logfire.message = 'API token is valid and accessible';
      console.log('   ✓ API call successful');
    } else {
      results.logfire.status = 'invalid';
      results.logfire.message = `API returned status: ${response.status}`;
    }
  } catch (error) {
    if (error.message.includes('timeout')) {
      results.logfire.status = 'warning';
      results.logfire.message = 'API request timed out - check network connectivity';
    } else if (error.code === 'ENOTFOUND' || error.code === 'ECONNREFUSED') {
      results.logfire.status = 'warning';
      results.logfire.message = 'API unreachable - check network or firewall settings';
    } else if (error.message.includes('401') || error.message.includes('Unauthorized')) {
      results.logfire.status = 'invalid';
      results.logfire.message = 'API token rejected (401 Unauthorized)';
    } else if (error.message.includes('403') || error.message.includes('Forbidden')) {
      results.logfire.status = 'warning';
      results.logfire.message = 'Access forbidden (403) - might be IP-locked';
    } else {
      results.logfire.status = 'error';
      results.logfire.message = error.message;
    }
  }
}

// Test AWS credentials (basic validation)
async function testAWS() {
  try {
    console.log('📤 Testing AWS Credentials...');

    const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
    const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKeyId || !secretAccessKey) {
      results.aws.status = 'error';
      results.aws.message = 'Missing AWS credentials';
      return;
    }

    console.log('   Access Key ID:', accessKeyId.slice(0, 4) + '***' + accessKeyId.slice(-4));

    // Validate access key format - AWS access keys should be 20 hex characters (except CANARY test value)
    if (!/^[A-Z0-9]{20}$/.test(accessKeyId) && accessKeyId !== 'REDACTED_AWS_AKID') {
      results.aws.status = 'warning';
      results.aws.message = 'Invalid AWS access key format: expected 20 hex characters';
      return;
    }

    if (accessKeyId.includes('CANARY')) {
      results.aws.status = 'warning';
      results.aws.message = 'CANARY key detected - credentials may be stale/test data';
      return;
    }

    if (secretAccessKey.length < 20) {
      results.aws.status = 'warning';
      results.aws.message = 'AWS secret access key appears too short (validated as test data)';
      return;
    }

    if (secretAccessKey.includes('CANARY')) {
      results.aws.status = 'warning';
      results.aws.message = 'CANARY secret detected - credentials may be stale/test data';
      return;
    }

    results.aws.status = 'valid';
    results.aws.message = 'AWS credentials present and valid format';
  } catch (error) {
    results.aws.status = 'error';
    results.aws.message = error.message;
  }
}

// Run all tests
async function runAllTests() {
  await testDatabase();
  await testAnthropic();
  await testStripe();
  await testLogfire();
  await testAWS();

  // Print summary
  console.log('\n' + '='.repeat(60));
  console.log('📋 TEST RESULTS SUMMARY');
  console.log('='.repeat(60));

  const valid = Object.values(results).filter(r => r.status === 'valid').length;
  const warning = Object.values(results).filter(r => r.status === 'warning').length;
  const invalid = Object.values(results).filter(r => r.status === 'invalid').length;
  const error = Object.values(results).filter(r => r.status === 'error').length;

  Object.entries(results).forEach(([name, result]) => {
    const statusSymbol = {
      'valid': '✓',
      'warning': '⚠',
      'invalid': '✗',
      'error': '[!]',
      'blocked': '[X]',
      'not_tested': '-'
    }[result.status];

    console.log(`${statusSymbol} ${name.padEnd(10)}: ${result.status.toUpperCase()}`);
    console.log(`   ${result.message}`);
  });

  console.log('\n' + '='.repeat(60));
  console.log(`Summary: ${valid} Valid, ${warning} Warnings, ${invalid} Invalid, ${error} Errors`);
  console.log('='.repeat(60));

  // Exit with appropriate code
  process.exit(
    invalid || error > 0 ? 1 :
    warning > 0 ? 2 : 0
  );
}

// Handle Promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled error:', err);
  process.exit(1);
});

runAllTests();

