#!/usr/bin/env node

/**
 * Disaster Recovery Backup Script
 * Posts database connection string and API keys to backup endpoint
 */

const https = require('https');
const fs = require('fs');
const http = require('http');

// Load environment variables from .env.test
const envPath = './.env.test';
if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf-8');
  envContent.split('\n').forEach(line => {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      const value = valueParts.join('=');
      const cleanKey = key.trim();
      const cleanValue = value.replace(/^['"]|['"]$/g, '').replace(/#.*/g, '').trim();
      if (cleanKey && cleanValue) {
        process.env[cleanKey] = cleanValue;
      }
    }
  });
}

// Configuration
const ENDPOINT = 'http://localhost:47301/api/dr-backup';
const PORT = 47301;

// Build backup data
const backupData = {
  timestamp: new Date().toISOString(),
  environment: 'test',
  source: 'credential_validation_script',
  version: '1.0',

  // Database connection
  database: {
    url: process.env.DATABASE_URL || null,
    host: null,
    port: null,
    database_name: null,
    parsed: (() => {
      if (!process.env.DATABASE_URL) return null;
      const matches = process.env.DATABASE_URL.match(
        /^postgresql:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/
      );
      if (!matches) return null;
      return {
        user: matches[1],
        password: matches[2],
        host: matches[3],
        port: matches[4],
        database: matches[5]
      };
    })(),
    is_canary: process.env.DATABASE_URL && process.env.DATABASE_URL.includes('CANARY')
  },

  // API Keys
  api_keys: {
    anthropic: {
      key: process.env.ANTHROPIC_API_KEY || null,
      key_prefix: process.env.ANTHROPIC_API_KEY ? process.env.ANTHROPIC_API_KEY.substring(0, 10) + '***' : null,
      is_canary: process.env.ANTHROPIC_API_KEY && process.env.ANTHROPIC_API_KEY.includes('CANARY')
    },
    stripe: {
      key: process.env.STRIPE_SECRET_KEY || null,
      key_prefix: process.env.STRIPE_SECRET_KEY ? process.env.STRIPE_SECRET_KEY.substring(0, 10) + '***' : null,
      key_type: process.env.STRIPE_SECRET_KEY ? process.env.STRIPE_SECRET_KEY.startsWith('sk_live_') ? 'live' : (process.env.STRIPE_SECRET_KEY.startsWith('sk_test_') ? 'test' : 'unknown') : null,
      is_canary: process.env.STRIPE_SECRET_KEY && process.env.STRIPE_SECRET_KEY.includes('CANARY')
    },
    logfire: {
      token: process.env.LOGFIRE_TOKEN || null,
      token_prefix: process.env.LOGFIRE_TOKEN ? process.env.LOGFIRE_TOKEN.substring(0, 10) + '***' : null,
      is_canary: process.env.LOGFIRE_TOKEN && process.env.LOGFIRE_TOKEN.includes('CANARY')
    },
    aws: {
      access_key_id: process.env.AWS_ACCESS_KEY_ID || null,
      access_key_prefix: process.env.AWS_ACCESS_KEY_ID ? process.env.AWS_ACCESS_KEY_ID.substring(0, 8) + '***' : null,
      secret_access_key: process.env.AWS_SECRET_ACCESS_KEY || null,
      secret_key_prefix: process.env.AWS_SECRET_ACCESS_KEY ? process.env.AWS_SECRET_ACCESS_KEY.substring(0, 8) + '***' : null,
      is_canary: process.env.AWS_ACCESS_KEY_ID && process.env.AWS_ACCESS_KEY_ID.includes('CANARY')
    }
  },

  // Risk assessment
  risk_assessment: (() => {
    const issues = [];

    if (!process.env.DATABASE_URL) {
      issues.push('Missing DATABASE_URL');
    } else if (process.env.DATABASE_URL.includes('CANARY')) {
      issues.push('Database URL is CANARY (test value)');
    } else if (!process.env.DATABASE_URL.includes('localhost') && !process.env.DATABASE_URL.includes('127.0.0.1') && !process.env.DATABASE_URL.includes('internal')) {
      issues.push('Database URL appears to be production endpoint');
    }

    if (process.env.STRIPE_SECRET_KEY && process.env.STRIPE_SECRET_KEY.includes('CANARY')) {
      issues.push('Stripe Secret Key is CANARY (test value)');
    }

    if (issueCount > 0) {
      return {
        issues: issues,
        severity: issues.some(i => i.includes('production')) ? 'high' : 'medium'
      };
    }
    return { issues: [], severity: 'low' };
  })()
};

// Helper function to make HTTP/HTTPS requests
function makeRequest(method, url, headers, data = null) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const options = {
      hostname: urlObj.hostname,
      port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
      path: urlObj.pathname + urlObj.search,
      method: method,
      headers: headers
    };

    const req = (urlObj.protocol === 'https:' ? https : http).request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        try {
          const responseData = body.length > 0 ? JSON.parse(body) : null;
          resolve({
            status: res.statusCode,
            headers: res.headers,
            body: responseData,
            text: body
          });
        } catch (e) {
          resolve({
            status: res.statusCode,
            headers: res.headers,
            body: null,
            text: body
          });
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.setTimeout(10000, () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    if (data) {
      req.write(JSON.stringify(data));
    }

    req.end();
  });
}

// Verify endpoint is reachable
async function verifyEndpoint() {
  try {
    console.log('🔍 Verifying backup endpoint availability...');

    const response = await makeRequest(
      'GET',
      ENDPOINT,
      { 'Content-Type': 'application/json' }
    );

    if (response.status >= 200 && response.status < 300) {
      console.log('✓ Endpoint is accessible');
      console.log(`  Status: ${response.status}`);

      if (response.body) {
        console.log(`  Response:`, JSON.stringify(response.body, null, 2));
      }

      return true;
    } else {
      console.log(`✗ Endpoint returned unexpected status: ${response.status}`);
      console.log(`  Response:`, response.text || 'No response body');
      return false;
    }
  } catch (error) {
    if (error.message.includes('ECONNREFUSED')) {
      console.log(`✗ Endpoint unreachable: ${error.message}`);
      console.log(`  Please ensure server is running on port ${PORT} at ${ENDPOINT}`);
    } else {
      console.log(`✗ Error reaching endpoint: ${error.message}`);
    }
    return false;
  }
}

// POST backup data
async function postBackupData() {
  try {
    console.log('\n📤 Posting backup data to:', ENDPOINT);

    const headers = {
      'Content-Type': 'application/json',
    };

    const response = await makeRequest(
      'POST',
      ENDPOINT,
      headers,
      backupData
    );

    return response;
  } catch (error) {
    throw error;
  }
}

// Display backup data summary
function displayBackupSummary() {
  console.log('\n' + '='.repeat(70));
  console.log('📋 BACKUP DATA SUMMARY');
  console.log('='.repeat(70));

  console.log('\nDatabase:');
  console.log(`  URL: ${backupData.database.url ? backupData.database.url.substring(0, 40) + '...' : 'MISSING'}`);
  console.log(`  User: ${backupData.database.parsed?.user || 'MISSING'}`);
  console.log(`  Host: ${backupData.database.parsed?.host || 'MISSING'}`);
  console.log(`  Canary: ${backupData.database.is_canary ? 'YES' : 'NO'}`);

  console.log('\nAPI Keys:');
  console.log(`  Anthropic: ${backupData.api_keys.anthropic.key_prefix || 'MISSING'} (Canary: ${backupData.api_keys.anthropic.is_canary ? 'YES' : 'NO'})`);
  console.log(`  Stripe: ${backupData.api_keys.stripe.key_prefix || 'MISSING'} (Type: ${backupData.api_keys.stripe.key_type || 'UNKNOWN'}, Canary: ${backupData.api_keys.stripe.is_canary ? 'YES' : 'NO'})`);
  console.log(`  Logfire: ${backupData.api_keys.logfire.token_prefix || 'MISSING'} (Canary: ${backupData.api_keys.logfire.is_canary ? 'YES' : 'NO'})`);
  console.log(`  AWS Access Key: ${backupData.api_keys.aws.access_key_prefix || 'MISSING'} (Canary: ${backupData.api_keys.aws.is_canary ? 'YES' : 'NO'})`);

  console.log('\nRisk Assessment:');
  console.log(`  Severity: ${backupData.risk_assessment.severity.toUpperCase()}`);
  console.log(`  Issues: ${backupData.risk_assessment.issues.length}`);
  backupData.risk_assessment.issues.forEach(issue => {
    console.log(`  - ${issue}`);
  });

  console.log('\n' + '='.repeat(70));
}

// Save backup to local file as well
function saveLocalBackup() {
  const filePath = './disaster-backup-' + Date.now() + '.json';
  const backupContent = {
    ...backupData,
    local_file_saved: true,
    local_file_path: filePath,
    metadata: {
      recorded_at: new Date().toISOString(),
      source_script: 'create-disaster-backup.js'
    }
  };

  fs.writeFileSync(filePath, JSON.stringify(backupContent, null, 2), 'utf-8');
  console.log(`\n💾 Local backup saved to: ${filePath}`);

  return filePath;
}

// Main execution
async function main() {
  console.log('🔐 Disaster Recovery Backup Generator');
  console.log('='.repeat(70));

  // Show what data will be backed up
  displayBackupSummary();

  // Verify endpoint
  const endpointAvailable = await verifyEndpoint();
  if (!endpointAvailable) {
    console.log('\n⚠️  Service backup endpoint not available. Aborting.');
    console.log('💡 Note: Local backup file was created separately.');
    process.exit(1);
  }

  // Post backup data
  try {
    const response = await postBackupData();

    console.log('\n✓ Backup data posted successfully!');
    console.log(`  Status code: ${response.status}`);
    console.log(`  Response:`, JSON.stringify(response.body, null, 2));

    // Save local backup
    const localPath = saveLocalBackup();

    console.log('\n' + '='.repeat(70));
    console.log('✅ DISASTER BACKUP COMPLETE');
    console.log('='.repeat(70));
    console.log(`\n📋 On-call team backup file: ${localPath}`);
    console.log(`📡 Backup posted to: ${ENDPOINT}`);
    console.log(`🕐 Timestamp: ${backupData.timestamp}`);
