// Secure application with proper error handling and input validation
// Based on OWASP security best practices

const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const morgan = require('morgan');
const { rateLimitConfig, securityHeaders } = require('./config/security');

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(xss()); // Prevents XSS attacks by cleaning user input
app.use(express.json({ limit: '10kb' })); // Body size limit to prevent DoS
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit(rateLimitConfig);
app.use('/api/', limiter);

// Configure morgan for request logging (avoiding sensitive info)
app.use(morgan('combined', {
  skip: (req) => req.path === '/health' // Skip logging health checks
}));

// ============================================
// Helper functions for error handling
// ============================================

/**
 * Custom error class with HTTP status codes
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Global error handling middleware
 * Must be placed after all routes
 */
app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log errors for monitoring
  console.error('Error:', {
    message: err.message,
    statusCode: err.statusCode,
    path: req.path,
    method: req.method,
    stack: err.stack
  });

  // Send error response in development
  res.status(err.statusCode).json({
    status: err.status,
    message: err.isOperational ? err.message : 'Something went wrong! Please try again later.',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// Route Handlers
// ============================================

/**
 * Health check endpoint with no sensitive information
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'healthy',
      uptime: process.uptime(),
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Users endpoint with input validation
 */
app.get('/users', (req, res, next) => {
  try {
    // Validate and sanitize query parameters
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    // Input validation - ensure values are within safe ranges
    if (page < 1 || limit < 1) {
      const error = new AppError('Page and limit must be positive integers', 400);
      return next(error);
    }

    if (limit > 100) {
      const error = new AppError('Maximum limit is 100', 400);
      return next(error);
    }

    // Return mock users (in production, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      status: 'success',
      data: users,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Example protected route with error handling
 */
app.get('/protected-route', (req, res, next) => {
  try {
    // Simulate a potential error condition
    const userRole = req.query.role;

    // Input validation for query parameter
    if (!userRole || typeof userRole !== 'string' || userRole.length > 50) {
      const error = new AppError('Invalid role parameter', 400);
      return next(error);
    }

    if (userRole !== 'admin') {
      const error = new AppError('Access denied. Admin privileges required.', 403);
      return next(error);
    }

    res.json({
      status: 'success',
      message: 'Protected resource accessed successfully'
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// 404 Handler - must come after all routes
// ============================================
app.use((req, res, next) => {
  const error = new AppError(`Route not found: ${req.method} ${req.path}`, 404);
  next(error);
});

// ============================================
// Error boundary middleware
// ============================================
app.use((err, req, res, next) => {
  next(err); // Defer to global error handler
});

// ============================================
// Server startup
// ============================================
const PORT = process.env.PORT || 3000;

// Graceful shutdown handler
const server = app.listen(PORT, () => {
  console.log(`✅ Server running on port ${PORT}`);
});

// Handle shutdown signals gracefully
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Unhandled rejections and exceptions
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, this should notify error monitoring service
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, this should notify error monitoring service
  process.exit(1);
});

module.exports = app;

/**
 * Security Configuration
 * Contains rate limiting and other security-related settings
 */

// Rate limiting configuration
const rateLimitConfig = {
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    statusCode: 429
  },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  handler: (req, res) => {
    res.status(429).json({
      status: 'error',
      error: 'Too many requests',
      message: 'Please try again later'
    });
  }
};

// Security headers configuration
const securityHeaders = {
  // Content Security Policy
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      baseUri: ["'self'"],
      formAction: ["'self'"],
      frameAncestors: ["'none'"],
      upgradeInsecureRequests: []
    }
  },
  // Enable tracking prevention
  crossOriginEmbedderPolicy: { policy: 'require-corp' },
  crossOriginOpenerPolicy: { policy: 'same-origin' },
  crossOriginResourcePolicy: { policy: 'same-origin' },
  // Enable HSTS
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  // Enable referrer policy
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  // Enable X-Content-Type-Options
  noSniff: true,
  // Enable X-Frame-Options
  frameguard: { action: 'deny' },
  // Remove X-Powered-By header
  hidePoweredBy: true
};

// Input validation rules (can be extended for other routes)
const validationRules = {
  // Email validation pattern
  emailRegex: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
  // ID validation (numeric and not too long)
  idRegex: /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/,
  // Username validation
  usernameRegex: /^[a-zA-Z0-9_]{3,30}$/,
  // Text content sanitization
  textSanitize: (input) => {
    if (typeof input !== 'string') return input;
    return input
      .replace(/[<>]/g, '') // Remove angle brackets
      .trim()
      .substring(0, 1000); // Limit length
  }
};

// Environment-based security settings
const isProduction = process.env.NODE_ENV === 'production';
const isDevelopment = process.env.NODE_ENV === 'development';
const isTesting = process.env.NODE_ENV === 'test';

// Security settings based on environment
const securitySettings = {
  // Disable stack traces in production
  logStackTraces: isDevelopment,
  // Return detailed errors only in development
  detailedErrors: isDevelopment,
  // Enable debug mode in development only
  debug: isDevelopment
};

module.exports = {
  rateLimitConfig,
  securityHeaders,
  validationRules,
  securitySettings
};

