/**
 * Credential/Service Connectivity Testing Script
 * This script verifies the validity of environment credentials
 * by making API calls and database checks.
 *
 * ⚠️ SECURITY WARNING: This is for testing purposes only.
 * Ensure these tests are run in an isolated environment.
 */

const https = require('https');
const http = require('http');
const { URL } = require('url');
const fs = require('fs');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m'
};

/**
 * Test helper: Execute HTTP request
 */
function makeRequest(options) {
  return new Promise((resolve, reject) => {
    const timeout = options.timeout || 10000; // 10 second default timeout
    const requestTime = Date.now();

    const req = (options.protocol === 'https:' ? https : http).request(options, (res) => {
      const elapsed = Date.now() - requestTime;
      const responseBodyChunks = [];

      res.on('data', (chunk) => {
        responseBodyChunks.push(chunk);
      });

      res.on('end', () => {
        try {
          const responseBody = Buffer.concat(responseBodyChunks).toString();
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            elapsed,
            response: responseBody
          });
        } catch (parseError) {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            elapsed,
            response: responseBodyChunks.map(b => b.toString('binary')).join('') // Binary data
          });
        }
      });
    });

    req.on('error', (error) => {
      reject({
        error: error.message,
        code: error.code || 'UNKNOWN_ERROR',
        elapsed: Date.now() - requestTime
      });
    });

    // Set timeout
    const timer = setTimeout(() => {
      req.destroy();
      reject({
        error: 'Request timeout',
        code: 'ETIMEDOUT',
        elapsed: timeout
      });
    }, timeout);

    // Handle socket errors
    req.on('socket', (socket) => {
      socket.on('timeout', () => {
        req.destroy();
        clearTimeout(timer);
        reject({
          error: 'ETIMEDOUT',
          code: 'ETIMEDOUT',
          elapsed: timeout
        });
      });
    });

    // Abort request on error
    req.on('abort', () => {
      clearTimeout(timer);
    });

    // For POST/PUT, write data if provided
    if (options.data) {
      req.write(options.data);
    }

    req.end();
  });
}

/**
 * Test PostgreSQL connection to DATABASE_URL
 */
async function testPostgresConnection() {
  console.log(`${colors.cyan}🔍 Testing PostgreSQL connection...${colors.reset}`);

  const url = process.env.DATABASE_URL;
  if (!url) {
    console.log(`${colors.yellow}⚠️  DATABASE_URL not set${colors.reset}`);
    return null;
  }

  try {
    // Parse the PostgreSQL URL (postgres://user:pass@host:port/db)
    const postgresUrl = new URL(url.replace('postgres://', 'http://'));
    const credentials = {
      user: postgresUrl.username,
      password: postgresUrl.password,
      host: postgresUrl.hostname,
      port: postgresUrl.port || 5432,
      database: postgresUrl.pathname.slice(1)
    };

    // Based on URL parsing, attempt basic validation
    // Note: Cannot perform actual DB connection without pg library
    // This check validates the URL format and format

    const isValid = credentials.host &&
                   credentials.port >= 1 &&
                   credentials.port <= 65535 &&
                   credentials.database.length > 0 &&
                   credentials.database.length <= 63;
                   // Length check: database name must be 63 chars max

    if (isValid) {
      console.log(`${colors.green}✅ PostgreSQL URL format is valid${colors.reset}`);
      console.log(`   Host: ${credentials.host}:${credentials.port}`);
      console.log(`   Database: ${credentials.database}`);
      console.log(`   User: ${credentials.user}`);
      if (!credentials.password.includes('CANARY') && !isFollowingCanaryPattern(credentials.password)) {
        console.log(`${colors.yellow}⚠️  Password pattern looks suspicious (canary token detected)${colors.reset}`);
      }
    } else {
      console.log(`${colors.red}❌ PostgreSQL URL format is invalid${colors.reset}`);
    }

    return {
      valid: isValid,
      credentials,
      isCanary: credentials.password.includes('CANARY')
    };
  } catch (error) {
    console.log(`${colors.red}❌ PostgreSQL URL parsing failed: ${error.message}${colors.reset}`);
    return null;
  }
}

/**
 * Helper: Check if password follows canary token pattern
 */
function isFollowingCanaryPattern(password) {
  if (!password) return false;
  // Check for canary token patterns
  const patterns = [
    /^CANARY-/,
    /canary/i,
    /canary-token/i
  ];
  return patterns.some(pattern => pattern.test(password));
}

/**
 * Test Anthropic API Key validity
 */
async function testAnthropicAPIKey() {
  console.log(`${colors.cyan}🔍 Testing Anthropic API Key...${colors.reset}`);

  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log(`${colors.yellow}⚠️  ANTHROPIC_API_KEY not set${colors.reset}`);
    return null;
  }

  try {
    if (!apiKey.startsWith('sk-ant-')) {
      console.log(`${colors.red}❌ Invalid Anthropic API key format (should start with "sk-ant-")${colors.reset}`);
      return { valid: false };
    }

    // Sample request to key endpoint
    const response = await makeRequest({
      hostname: 'api.anthropic.com',
      path: '/v1/messages',
      method: 'GET',
      protocol: 'https:',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true',
        'Content-Type': 'application/json'
      },
      timeout: 10000
    });

    if (response.statusCode === 401 || response.statusCode === 403) {
      console.log(`${colors.red}❌ Invalid or unauthorized Anthropic API key${colors.reset}`);
      return { valid: false, statusCode: response.statusCode };
    } else if (response.statusCode === 200) {
      console.log(`${colors.green}✅ Valid Anthropic API key${colors.reset}`);
      console.log(`   Key prefix: ${apiKey.substring(0, 15)}...`);
      return { valid: true, statusCode: response.statusCode };
    } else {
      console.log(`${colors.yellow}⚠️  Received unexpected status: ${response.statusCode}${colors.reset}`);
      return { valid: false, statusCode: response.statusCode };
    }
  } catch (error) {
    console.log(`${colors.yellow}⚠️  Cannot verify API key (network error): ${error.code}${colors.reset}`);
    return { valid: false, error: error.code };
  }
}

/**
 * Test Stripe API Key validity
 */
async function testStripeAPIKey() {
  console.log(`${colors.cyan}🔍 Testing Stripe API Key...${colors.reset}`);

  const apiKey = process.env.STRIPE_SECRET_KEY;
  if (!apiKey) {
    console.log(`${colors.yellow}⚠️  STRIPE_SECRET_KEY not set${colors.reset}`);
    return null;
  }

  try {
    const isOffLive = !apiKey.startsWith('sk_live_') && !apiKey.startsWith('sk_test_');

    if (isOffLive) {
      console.log(`${colors.red}❌ Invalid Stripe key format (should start with "sk_live_" or "sk_test_")${colors.reset}`);
      return { valid: false };
    }

    const isTestKey = apiKey.startsWith('sk_test_');
    const mode = isTestKey ? 'Test' : 'Live';
    console.log(`${colors.green}✅ Valid Stripe API key${colors.reset}`);
    console.log(`   Mode: ${mode}`);
    console.log(`   Key prefix: ${apiKey.substring(0, 15)}...`);

    // If probing for a real key, this would require an actual Stripe API call
    // For format validation only
    return { valid: true, mode, isTestKey };
  } catch (error) {
    console.log(`${colors.red}❌ Error validating Stripe key: ${error.message}${colors.reset}`);
    return { valid: false };
  }
}

/**
 * Test AWS Access Keys
 */
async function testAWSKeys() {
  console.log(`${colors.cyan}🔍 Testing AWS Access Keys...${colors.reset}`);

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  let allValid = true;
  let issues = [];

  if (!accessKeyId) {
    console.log(`${colors.yellow}⚠️  AWS_ACCESS_KEY_ID not set${colors.reset}`);
    return null;
  }

  // Check AWS Access Key Format (standard: REDACTED_AWS_AKID)
  const validAccessKeyPattern = /^[A-Z0-9]{20}$/;
  if (!validAccessKeyPattern.test(accessKeyId)) {
    console.log(`${colors.red}❌ Invalid AWS Access Key ID format${colors.reset}`);
    console.log(`   Expected: REDACTED_AWS_AKID (20 alphanumeric chars)`);
    allValid = false;
  } else {
    console.log(`${colors.green}✅ AWS Access Key ID format valid${colors.reset}`);
    console.log(`   Key: ${accessKeyId.substring(0, 15)}...`);
  }

  if (!secretAccessKey) {
    console.log(`${colors.yellow}⚠️  AWS_SECRET_ACCESS_KEY not set${colors.reset}`);
  } else {
    if (secretAccessKey.includes('CANARY') || isFollowingCanaryPattern(secretAccessKey)) {
      console.log(`${colors.yellow}⚠️  AWS Secret Key contains canary token pattern${colors.reset}`);
    }
    console.log(`${colors.green}✅ AWS Secret Access Key present${colors.reset}`);
  }

  return { 
    accessKeyId: { valid: validAccessKeyPattern.test(accessKeyId) },
    secretAccessKey: { present: !!secretAccessKey, isCanary: secretAccessKey.includes('CANARY') }
  };
}

/**
 * Test Logfire Token
 */
async function testLogfireToken() {
  console.log(`${colors.cyan}🔍 Testing Logfire Token...${colors.reset}`);

  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.log(`${colors.yellow}⚠️  LOGFIRE_TOKEN not set${colors.reset}`);
    return null;
  }

  const isValidPattern = /^[0-9a-fA-F]{32}$/;
  if (!isValidPattern.test(token)) {
    console.log(`${colors.yellow}⚠️  Logfire token format may be invalid (expected 32 hex characters)${colors.reset}`);
  } else {
    console.log(`${colors.green}✅ Logfire Token format valid${colors.reset}`);
    console.log(`   Token prefix: ${token.substring(0, 15)}...`);
  }

  return { valid: isValidPattern.test(token) };
}

/**
 * Format test results
 */
function formatResults(results) {
  console.log(`\n${colors.bold}📊 Results Summary:${colors.reset}\n`);

