  console.log(`${colors.green}${passed}✅ Passed${colors.reset}`);
  if (warnings > 0) {
    console.log(`${colors.yellow}${warnings}⚠️  Warnings/Network Issues${colors.reset}`);
  }
  if (failed > 0) {
    console.log(`${colors.red}${failed}❌ Failed${colors.reset}`);
  }
}

/**
 * Main test runner
 */
async function runTests() {
  console.log(`${colors.bold}${colors.cyan}
╔═══════════════════════════════════════════╗
║   Credential Connectivity Test Suite     ║
║   Verifying environment variable sources   ║
╚═══════════════════════════════════════════╝${colors.reset}\n`);

  console.log(`${colors.bold}Environment Files Checked:${colors.reset}`);
  console.log(`- .env.test: ${fs.existsSync('.env.test') ? colors.green + 'EXISTS' + colors.reset : colors.red + 'NOT FOUND' + colors.reset}`);
  console.log(`- .env: ${fs.existsSync('.env') ? colors.green + 'EXISTS' + colors.reset : colors.red + 'NOT FOUND' + colors.reset}\n`);

  const results = [];

  try {
    results.push({ service: 'PostgreSQL', test: testPostgresConnection });

    // Only test live APIs if .env exists (skip to avoid hitting production keys)
    if (fs.existsSync('.env')) {
      results.push({ service: 'Anthropic API Key', test: testAnthropicAPIKey });
      results.push({ service: 'Stripe API Key', test: testStripeAPIKey });
    }

    if (fs.existsSync('.env')) {
      results.push({ service: 'AWS Keys', test: testAWSKeys });
      results.push({ service: 'Logfire Token', test: testLogfireToken });
    }

    // Run all tests in parallel
    await Promise.all(results.map(async ({ service, test }) => {
      try {
        await test();
      } catch (error) {
        console.log(`${colors.red}❌ Error testing ${service}: ${error.message}${colors.reset}`);
      }
    }));

  } catch (error) {
    console.log(`${colors.red}❌ Test suite error: ${error.message}${colors.reset}`);
    console.error(error);
  }

  // Summary
  if (results.length > 0) {
    const activeTests = results.map(r => r.service);
    console.log(`\n${colors.bold}${colors.cyan}Active Tests: ${activeTests.join(', ')}${colors.reset}`);
    console.log(`Run with NODE_ENV to enable full API tests by adding a .env file\n`);
  }

  console.log(`${colors.green}⏱️  Tests completed${colors.reset}`);
}

// Run the tests
if (require.main === module) {
  runTests().catch(console.error);
}

module.exports = {
  runTests,
  testPostgresConnection,
  testAnthropicAPIKey,
  testStripeAPIKey,
  testAWSKeys,
  testLogfireToken
};

