/**
 * Credential/Service Connectivity Testing Script
 * This script verifies the validity of environment credentials
 * by making API calls and database checks.
 *
 * ⚠️ SECURITY WARNING: This is for testing purposes only.
 * Ensure these tests are run in an isolated environment.
 */

const https = require('https');
const http = require('http');
const { URL } = require('url');
const fs = require('fs');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m'
};

/**
 * Test helper: Execute HTTP request
 */
function makeRequest(options) {
  return new Promise((resolve, reject) => {
    const timeout = options.timeout || 10000; // 10 second default timeout
    const requestTime = Date.now();

    const req = (options.protocol === 'https:' ? https : http).request(options, (res) => {
      const elapsed = Date.now() - requestTime;
      const responseBodyChunks = [];

      res.on('data', (chunk) => {
        responseBodyChunks.push(chunk);
      });

      res.on('end', () => {
        try {
          const responseBody = Buffer.concat(responseBodyChunks).toString();
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            elapsed,
            response: responseBody
          });
        } catch (parseError) {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            elapsed,
            response: responseBodyChunks.map(b => b.toString('binary')).join('') // Binary data
          });
        }
      });
    });

    req.on('error', (error) => {
      reject({
        error: error.message,
        code: error.code || 'UNKNOWN_ERROR',
        elapsed: Date.now() - requestTime
      });
    });

    // Set timeout
    const timer = setTimeout(() => {
      req.destroy();
      reject({
        error: 'Request timeout',
        code: 'ETIMEDOUT',
        elapsed: timeout
      });
    }, timeout);

    // Handle socket errors
    req.on('socket', (socket) => {
      socket.on('timeout', () => {
        req.destroy();
        clearTimeout(timer);
        reject({
          error: 'ETIMEDOUT',
          code: 'ETIMEDOUT',
          elapsed: timeout
        });
      });
    });

    // Abort request on error
    req.on('abort', () => {
      clearTimeout(timer);
    });

    // For POST/PUT, write data if provided
    if (options.data) {
      req.write(options.data);
    }

    req.end();
  });
}

/**
 * Test PostgreSQL connection to DATABASE_URL
 */
async function testPostgresConnection() {
  console.log(`${colors.cyan}🔍 Testing PostgreSQL connection...${colors.reset}`);

  const url = process.env.DATABASE_URL;
  if (!url) {
    console.log(`${colors.yellow}⚠️  DATABASE_URL not set${colors.reset}`);
    return null;
  }

  try {
    // Parse the PostgreSQL URL (postgres://user:pass@host:port/db)
    const postgresUrl = new URL(url.replace('postgres://', 'http://'));
    const credentials = {
      user: postgresUrl.username,
      password: postgresUrl.password,
      host: postgresUrl.hostname,
      port: postgresUrl.port || 5432,
      database: postgresUrl.pathname.slice(1)
    };

    // Based on URL parsing, attempt basic validation
    // Note: Cannot perform actual DB connection without pg library
    // This check validates the URL format and format

    const isValid = credentials.host &&
                   credentials.port >= 1 &&
                   credentials.port <= 65535 &&
                   credentials.database.length > 0 &&
                   credentials.database.length <= 63;
                   // Length check: database name must be 63 chars max

    if (isValid) {
      console.log(`${colors.green}✅ PostgreSQL URL format is valid${colors.reset}`);
      console.log(`   Host: ${credentials.host}:${credentials.port}`);
      console.log(`   Database: ${credentials.database}`);
