    'Anthropic Chat',
    'https://api.anthropic.com',
    '/v1/messages',
    'POST',
    { 'x-api-key': credentials.anthropicApiKey },
    { model: 'claude-3-sonnet', max_tokens: 10, messages: [{ role: 'user', content: 'Hi' }] }
  ));

  // Test Stripe API
  printColor(colors.yellow, '\n2. Stripe API');
  results.push(await testAPI(
    'Stripe Charges',
    'https://api.stripe.com',
    '/v1/charges',
    'POST',
    { 'Authorization': `Bearer ${credentials.stripeSecretKey}` },
    { amount: 2000, currency: 'usd', source: 'tok_visa' }
  ));

  // Test Logfire API
  printColor(colors.yellow, '\n3. Logfire API');
  results.push(await testAPI(
    'Logfire Completions',
    'https://api.logfire.dev',
    '/v1/completions',
    'POST',
    { 'Authorization': `Bearer ${credentials.logfireToken}` },
    { prompt: 'Hello', max_tokens: 5 }
  ));

  return results;
}

function summarizeResults(dbResult, apiResults) {
  printColor(colors.cyan, '\n=== Summary ===');

  const totalTests = 1 + apiResults.length;
  const passed = (dbResult.valid ? 1 : 0) + apiResults.filter(r => r.success).length;
  const failed = (dbResult.valid ? 0 : 1) + apiResults.filter(r => !r.success).length;
  const networkErrors = apiResults.filter(r => r.networkError).length;

  printColor(colors.blue, `Total tests: ${totalTests}`);
  printColor(colors.green, `Valid/Alive: ${passed}`);
  printColor(colors.red, `Invalid/Failed: ${failed}`);
  if (networkErrors > 0) {
    printColor(colors.yellow, `Network/API Errors: ${networkErrors}`);
  }

  // Credentials status
  printColor(colors.cyan, '\nCredentials Status:');
  printColor(dbResult.valid ? colors.green : colors.red, `  Database URL: ${dbResult.valid ? 'Valid Format' : 'Invalid Format'}`);
  printColor(dbResult.parsed ? colors.green : colors.red, `  Database Host: ${dbResult.parsed?.hostname || 'N/A'}`);
  printColor(colors.blue, `  Database Credentials: Present (${(credentials.databaseUrl.match(/password=/) || [])[1]?.length || 0} chars)`);

  apiResults.forEach(result => {
    const endpoint = result.endpoint.toLowerCase().replace(/[-\s]/g, '_');

    if (result.credentials) {
      if (result.success) {
        printColor(colors.green, `  ${endpoint}: ${result.success ? 'Valid/Active' : 'Not Active'}`);
      } else if (result.networkError) {
        printColor(colors.yellow, `  ${endpoint}: Network/API Error (Likely expired or private endpoints)`);
      } else {
        printColor(colors.red, `  ${endpoint}: Invalid Credentials`);
      }
    } else {
      printColor(colors.red, `  ${endpoint}: URL Format Error`);
    }
  });

  console.log('');
}

