    log.info('Testing Logfire Token');

    log.dim(`Token: ${token.substring(0, 10)}...${token.substring(token.length - 4)}`);

    // Logfire tokens are typically UUID-like
    const isValid = /^[a-f0-9-]{36}$/.test(token) || token.length > 20;

