// Test Anthropic API connectivity
async function testAnthropicConnectivity(key) {
    log.divider();
    log.info('Testing Anthropic API Connectivity');

    log.dim('Attempting API connectivity test (requires valid API key)');

    try {
        // Test if we can make an API request (without using Anthropic library)
        const response = await fetch('https://api.anthropic.com/v1/models', {
            method: 'GET',
            headers: {
                'x-api-key': key,
                'anthropic-version': '2023-06-01'
            },
            signal: AbortSignal.timeout(5000)
        });

        if (response.ok) {
            const data = await response.json();
            const models = data.data?.map(m => m.id).join(', ') || 'success';
            log.success('Anthropic API connection successful');
            log.dim(`Available models: ${models.substring(0, 100)}...`);

            if (data.data && data.data.length > 0) {
                return { valid: true };
            }
        } else {
            const error = await response.text();
            log.error(`Anthropic API request failed: ${response.status}`);
            log.error(error.substring(0, 200));
            return { valid: false, message: `API error: ${response.status}` };
        }
    } catch (error) {
        if (error.name === 'AbortError') {
            log.error('Request timeout');
        } else {
            log.error(`API test failed: ${error.message}`);
            if (error.message.includes('fetch')) {
                log.dim('Network error - check internet connection');
            }
        }
