#!/usr/bin/env node
/**
 * Credential Verification Script
 *
 * This script tests connectivity to databases and validates API keys
 * for the credentials stored in .env.test
 */

const fs = require('fs');
const path = require('path');
const { URL } = require('url');
const crypto = require('crypto');

// ANSI color codes for terminal output
const colors = {
    reset: '\x1b[0m',
    green: '\x1b[32m',
    red: '\x1b[31m',
    yellow: '\x1b[33m',
    blue: '\x1b[34m',
    cyan: '\x1b[36m',
    dim: '\x1b[2m'
};

// Logging functions
const log = {
    success: (msg) => console.log(`${colors.green}✓${colors.reset} ${msg}`),
    error: (msg) => console.log(`${colors.red}✗${colors.reset} ${msg}`),
    warn: (msg) => console.log(`${colors.yellow}⚠${colors.reset} ${msg}`),
    info: (msg) => console.log(`${colors.cyan}ℹ${colors.reset} ${msg}`),
    dim: (msg) => console.log(`${colors.dim}${msg}${colors.reset}`),
    divider: () => console.log(`${colors.dim}${'─'.repeat(60)}${colors.reset}`)
};

// Load environment variables from .env.test
function loadEnv() {
    const envPath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envPath)) {
        log.error('.env.test file not found!');
        process.exit(1);
    }

    const envContent = fs.readFileSync(envPath, 'utf8');
    const env = {};

    envContent.split('\n').forEach(line => {
        const trimmed = line.trim();
        // Skip comments and empty lines
        if (trimmed && !trimmed.startsWith('#')) {
            const [key, ...valueParts] = line.split('=');
            if (key && valueParts.length > 0) {
                env[key.trim()] = valueParts.join('=').trim();
            }
        }
    });

    return env;
}

// Validate the environment variable structure
function validateEnv(env) {
    const required = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
                     'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];

    const missing = required.filter(key => !env[key]);

    if (missing.length > 0) {
        log.error('Missing required environment variables:');
        missing.forEach(key => log.error(`  - ${key}`));
        return false;
    }

    return true;
}

// Test database connectivity
async function testDatabaseConnection(dbUrl) {
    log.divider();
    log.info('Testing Database Connection');
    log.dim(`URL: ${maskSensitive(dbUrl)}`);

    const start = Date.now();

    try {
        const parsed = new URL(dbUrl);
        const driver = parsed.protocol === 'postgresql:' ? 'pg' : 'mysql2';
        log.dim(`Driver Type: ${driver}`);

        // Dynamic import requires check
        if (driver === 'pg') {
            const { Pool } = require('pg');

            // Parse connection options
            const options = {
                host: parsed.hostname,
                port: parseInt(parsed.port) || 5432,
                database: parsed.pathname.replace('/', '') || 'postgres'
            };

            // Add auth if present
            if (parsed.username && parsed.password) {
                options.user = parsed.username;
                options.password = parsed.password;
            }

            const pool = new Pool(options);

            // Connection timeout wrapper
            const connectionPromise = new Promise((resolve, reject) => {
                pool.connect((err, client, release) => {
                    if (err) {
                        reject(err);
                    } else {
                        resolve({ client, release, pool });
                    }
                });
            });

            const timeout = new Promise((_, reject) =>
                setTimeout(() => reject(new Error('Connection timeout (10s)')), 10000)
            );

            const result = await Promise.race([connectionPromise, timeout]);
            const release = result.release;

            // Execute a ping query
            await release.query('SELECT 1');

            const elapsed = Date.now() - start;
            log.success(`Database connection successful! (${elapsed}ms)`);
            log.dim(`Database: ${options.database} @ ${options.host}`);

            // Try to get connection pool stats
            try {
                const stats = await pool.query('SELECT count(*) as active FROM pg_stat_activity WHERE pid = pg_backend_pid()');
                log.dim(`Active connections: ${stats.rows[0].active}`);
            } catch (e) {
                log.dim(`Couldn't fetch connection stats: ${e.message}`);
            }

            release();
            pool.end();
            return true;
        } else {
            // MySQL2 not available yet, provide guidance
            log.warn('MySQL supported but mysql2 package not installed');
            log.dim('Run: npm install mysql2');

            try {
                const mysql = require('mysql2/promise');
                const connection = await mysql.createConnection({
                    host: parsed.hostname,
                    port: parseInt(parsed.port) || 3306,
                    user: parsed.username,
                    password: parsed.password,
                    database: parsed.pathname.replace('/', '') || 'test_db'
                });

                log.success('MySQL connection successful');
                await connection.execute('SELECT 1 as ping');
                log.dim('Ping query successful');

                connection.end();
                return true;
            } catch (error) {
                log.error(`MySQL connection failed: ${error.message}`);
                return false;
            }
        }
    } catch (error) {
        const elapsed = Date.now() - start;
        log.error(`Database connection failed after ${elapsed}ms`);
        log.error(error.message);

        // Provide helpful hints
        if (error.message.includes('ECONNREFUSED')) {
            log.warn('Connection refused - host is not reachable. Check:');
            log.dim('  - DNS resolution for host');
            log.dim('  - Firewall rules');
            log.dim('  - Whether the host is running');
        } else if (error.message.includes('authentication')) {
            log.warn('Authentication failed - check credentials');
        }

        return false;
    }
}

