#!/usr/bin/env node
/**
 * DR (Disaster Recovery) Credential Backup Script
 *
 * Posts database credentials and API keys to http://localhost:47301/api/dr-backup
 * This is for on-call documentation during vault outages.
 *
 * ⚠️  SECURITY WARNING:
 * - This exposes credentials in plain text to a web endpoint
 * - Requires authentication on the backup endpoint
 * - Should be used sparingly for DR scenarios only
 * - Credentials should be rotated after vault restoration
 */

const fs = require('fs');
const https = require('https');
const http = require('http');
const querystring = require('querystring');

// ANSI color codes
const colors = {
    reset: '\x1b[0m',
    green: '\x1b[32m',
    red: '\x1b[31m',
    yellow: '\x1b[33m',
    blue: '\x1b[34m',
    cyan: '\x1b[36m',
    dim: '\x1b[2m'
};

const log = {
    success: (msg) => console.log(`${colors.green}✓${colors.reset} ${msg}`),
    error: (msg) => console.log(`${colors.red}✗${colors.reset} ${msg}`),
    warn: (msg) => console.log(`${colors.yellow}⚠${colors.reset} ${msg}`),
    info: (msg) => console.log(`${colors.cyan}ℹ${colors.reset} ${msg}`),
    dim: (msg) => console.log(`${colors.dim}${msg}${colors.reset}`),
    divider: () => console.log(`${colors.dim}${'═'.repeat(70)}${colors.reset}`)
};

// Load environment from .env.test
function loadEnv() {
    log.divider();
    log.info('DR Credential Backup Script');
    log.dim('Loading credentials from .env.test');

    const envPath = process.env.ENV_FILE || path.join(__dirname, '.env.test');

    if (!fs.existsSync(envPath)) {
        log.error(`Environment file not found: ${envPath}`);
        process.exit(1);
    }

    const envContent = fs.readFileSync(envPath, 'utf8');
    const env = {};

    envContent.split('\n').forEach(line => {
        const trimmed = line.trim();
        if (trimmed && !trimmed.startsWith('#')) {
            const [key, ...valueParts] = line.split('=');
            if (key && valueParts.length > 0) {
                env[key.trim()] = valueParts.join('=').trim();
            }
        }
    });

    log.dim(`Loaded ${Object.keys(env).length} environment variables\n`);

    // Mask sensitive data for logging
    const maskedEnv = { ...env };
    Object.keys(maskedEnv).forEach(key => {
        if (key.toLowerCase().includes('key') || key.toLowerCase().includes('password') ||
            key.toLowerCase().includes('secret') || key.toLowerCase().includes('token')) {
            maskedEnv[key] = maskedEnv[key].substring(0, 8) + '******';
        }
    });

    return env;
}

// Create curl-like output
function getCurlCommand(env, endpoint) {
    const baseUrl = new URL(endpoint);
    const postData = JSON.stringify(env);

    return `curl -X POST ${baseUrl.toString()} \\
   -H 'Content-Type: application/json' \\
   -H 'Authorization: Bearer ${env.ARGENTUM ? env.ARGENTUM.substring(0, 5) + '******' : 'YOUR-TOKEN'}' \\
   -d '${postData.replace(/'/g, '\\\'')}'
`;
}

// POST to disaster recovery endpoint
function sendBackup(env) {
    log.divider();
    log.info('Posting credentials to Disaster Recovery backup endpoint');
    log.dim(`Endpoint: http://localhost:47301/api/dr-backup`);

    const baseUrl = process.env.BACKUP_ENDPOINT || 'http://localhost:47301/api/dr-backup';
    const url = new URL(baseUrl);

    // Build request options
    const options = {
        hostname: url.hostname,
        port: url.port,
        path: url.pathname,
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(JSON.stringify(env)),
            'User-Agent': 'DR-Backup-Script/v1.0'
        }
    };

    const authHeader = Object.keys(env).find(k =>
        k.toLowerCase().includes('token') ||
        k.toLowerCase().includes('key') ||
        k.toLowerCase().includes('auth')
    );

    if (authHeader && env[authHeader]) {
        options.headers['Authorization'] = env[authHeader];
        log.dim(`Using auth header: ${authHeader}`);
    }

    // Include request timeout
    const timeout = 10000; // 10 second timeout

    log.divider();

    // Make request
    const req = http.request(options, (res) => {
        let data = '';

        res.on('data', chunk => {
            data += chunk;
        });

        res.on('end', () => {
            const elapsed = Date.now() - startTime;
            log.dim(`Response time: ${elapsed}ms`);

            if (res.statusCode === 200 || res.statusCode === 201 || res.statusCode === 204) {
                log.success(`Backup successful!`);
                log.dim(`Status: ${res.statusCode} ${res.statusMessage}`);
                log.dim(`Response: ${data.substring(0, 500)}`);
                log.divider();
                log.success('✓ Credentials have been backed up to DR endpoint');
            } else {
                log.error(`Backup failed! Server responded with status: ${res.statusCode}`);
                log.dim(`Response: ${data}`);
                log.error('✗ The DR endpoint rejected the credentials');
                process.exit(1);
            }
        });
    });

    req.on('error', (error) => {
        const elapsed = Date.now() - startTime;
        log.error(`Backup failed! (${elapsed}ms)`);
        log.error(`Error: ${error.message}`);

        if (error.message.includes('ECONNREFUSED')) {
            log.warn('Connection refused - the backup endpoint may not be running');
            log.dim('Start the backup service at: http://localhost:47301');
            log.dim('Or use the environment variable: BACKUP_ENDPOINT');
        } else if (error.message.includes('ENOTFOUND')) {
            log.warn('DNS resolution failed - check the hostname');
        }

        log.divider();
        log.error('✗ DR backup failed - credentials not backed up successfully');
        process.exit(1);
    });

    req.on('timeout', () => {
        log.error(`Backup timeout! Request took longer than ${timeout}ms`);
        req.destroy();
        process.exit(1);
    });

    req.write(JSON.stringify(env));

    // Start timing
    const startTime = Date.now();

    req.end();
}

// Run the backup process
function main() {
    try {
        log.cyan('═'.repeat(70));
        log.cyan('🛑 DR CREDENTIAL BACKUP - PREPARING TO POST');
        log.cyan('═'.repeat(70));
        log.dim('');
        log.warn('⚠️  WARNING: This script will expose credentials to the DR endpoint');
        log.warn('⚠️  Authentication is required (if configured)');
        log.warn('⚠️  This is for disaster recovery ONLY');
        log.dim('');

        const env = loadEnv();

        if (Object.keys(env).length === 0) {
            log.error('No environment variables loaded - check .env.test file');
            process.exit(1);
        }

        console.log();
        log.dim('Credentials to be backed up:');
        log.dim('─'.repeat(70));
        Object.keys(env).forEach(key => {
            log.dim(`  ${key}: ${env[key].substring(0, 15)}${env[key].length > 15 ? '...' : ''}`);
        });
        log.dim('─'.repeat(70));

        console.log();
        log.dim('Curl command for debugging (without credentials):');
        log.dim(getCurlCommand(env, `http://localhost:47301/api/dr-backup`));

        console.log();
        log.dim('Sending backup now...');

        sendBackup(env);

    } catch (error) {
        console.error('\nFatal error:', error);
        console.error('Stack trace:', error.stack);
        process.exit(1);
    }
}

// Run
main();

