};

// Results storage
const results = {
  passed: [],
  failed: [],
  warnings: []
};

// Helper to log results
function logEvidence(entry) {
  if (entry.status === 'PASSED') results.passed.push(entry);
  else if (entry.status === 'FAILED') results.failed.push(entry);
  else results.warnings.push(entry);

  console.log(`[${entry.status}] ${entry.name}: ${entry.message}`);
  if (entry.details) {
    console.log(`  → ${entry.details}`);
  }
}

// 1. Database Connectivity Test
async function testDatabase(url) {
  try {
    console.log('\n🔍 Testing database connectivity...');
    const client = await createClient({ connectionString: url });

    // Execute a simple query
    const result = await client.sql`SELECT NOW() as current_time`;
    await client.end();

    const currentTime = result.rows[0]?.current_time;
    logEvidence({
      status: 'PASSED',
      name: 'Database Connection',
      message: 'Successfully connected and queried'
    });

    return true;
  } catch (error) {
    logEvidence({
      status: 'FAILED',
      name: 'Database Connection',
      message: error.message,
      details: `Error code: ${error.name}`
    });
    return false;
  }
}

// 2. AWS Keys Test
function testAWSKeys() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = envVars;

  // Check for valid AWS key patterns (AWS IDs start with certain prefixes)
  const isValidKeyId = /^AKIA[0-9A-Z]{16}$/.test(AWS_ACCESS_KEY_ID);
  const hasSecretLength = AWS_SECRET_ACCESS_KEY.length >= 20;

  if (isValidKeyId) {
    logEvidence({
      status: 'PASSED',
      name: 'AWS Key Format',
      message: 'AWS Key ID follows standard format (AKIA***)',
      details: `Key: ${AWS_ACCESS_KEY_ID.substring(0, 8)}...`
    });
  } else {
    logEvidence({
      status: 'FAILED',
      name: 'AWS Key Format',
      message: 'Key ID does not follow AWS standard format',
      details: `Received: ${AWS_ACCESS_KEY_ID}`
    });
  }

  if (hasSecretLength) {
    logEvidence({
      status: 'PASSED',
      name: 'AWS Secret Length',
      message: 'Secret key meets minimum length (>= 20 chars)',
      details: `Length: ${AWS_SECRET_ACCESS_KEY.length}`
    });
  } else {
    logEvidence({
      status: 'FAILED',
      name: 'AWS Secret Length',
      message: 'Secret key too short for AWS',
      details: `Length: ${AWS_SECRET_ACCESS_KEY.length}`
    });
  }

  return isValidKeyId && hasSecretLength;
}

// 3. Anthropic API Test
function testAnthropicAPI(apiKey) {
  logEvidence({
    status: 'INFO',
    name: 'Anthropic API Format',
    message: 'Key format appears standard (sk-ant-***)',
    details: `Key: ${apiKey.substring(0, 11)}***`
  });

  // Validate key exists
  if (apiKey && apiKey.startsWith('sk-ant-') && apiKey.length > 20) {
