  } else {
    logEvidence({
      status: 'FAILED',
      name: 'Anthropic API Format',
      message: 'API key format is invalid'
    });
    return false;
  }
}

// 4. Stripe API Test
async function testStripeAPI(apiKey) {
  logEvidence({
    status: 'INFO',
    name: 'Stripe API Format',
    message: 'Key format appears standard (sk_live_***)',
    details: `Key: ${apiKey.substring(0, 15)}***`
  });

  // Validate key
  if (apiKey && (apiKey.startsWith('sk_live_') || apiKey.startsWith('sk_test_'))) {
