        'x-api-key': envVars.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
        'max-length': '8192'
      }
    );

    if (response.statusCode === 401) {
      logEvidence({
        status: 'FAILED',
        name: 'Anthropic API',
        message: 'API returned 401 Unauthorized (invalid key)',
        details: response.body?.error?.message || 'Unknown error'
      });
    } else if (response.statusCode === 403) {
      logEvidence({
        status: 'FAILED',
        name: 'Anthropic API',
        message: 'API returned 403 Forbidden (permission issue)',
        details: response.body?.error?.message || 'Unknown error'
      });
    } else if (response.statusCode === 200) {
      logEvidence({
        status: 'PASSED',
        name: 'Anthropic API',
        message: 'API key is valid and working'
      });
    } else {
      logEvidence({
        status: 'WARNING',
        name: 'Anthropic API',
        message: `Unexpected status code: ${response.statusCode}`,
        details: response.body
      });
    }
  } catch (error) {
    logEvidence({
      status: 'FAILED',
      name: 'Anthropic API',
      message: 'Network error or API unavailable',
      details: error.message
    });
  }

  return tests;
}

// 6. Security Analysis
function analyzeSecurity() {
  logEvidence({
    status: 'INFO',
    name: 'Security Analysis',
    message: 'Credential validation complete'
  });

