#!/usr/bin/env node

/**
 * Disaster Recovery Backup Script
 * Posts database connection string and API keys to DR endpoint
 */

const fs = require('fs');
const https = require('https');
const http = require('http');
const url = require('url');

// Load environment variables
const envContent = fs.readFileSync('.env.test', 'utf8');
const envVars = {};

// Parse .env file (simple parser)
for (const line of envContent.split('\n')) {
  const match = line.match(/^([^=]+)=(.*)$/);
  if (match) {
    const key = match[1].trim();
    let value = match[2].trim();

    // Remove quotes if present
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }

    envVars[key] = value;
  }
}

// Format as JSON with metadata
const backupPayload = {
  metadata: {
    generatedAt: new Date().toISOString(),
    generatedBy: 'dr-backup.js',
    environment: 'test',
    purpose: 'disaster_recovery',
    endpoints: {
      database: envVars.DATABASE_URL ? 'postgres://***@***:5432/production' : 'missing',
      awsConnections: envVars.AWS_ACCESS_KEY_ID ? '***' : 'missing',
      anthropicAPI: envVars.ANTHROPIC_API_KEY ? '***' : 'masked',
      stripe: envVars.STRIPE_SECRET_KEY ? '***' : 'masked',
      logfire: envVars.LOGFIRE_TOKEN ? '***' : 'missing'
    }
  },
  credentials: {
    database: envVars.DATABASE_URL || null,
    aws_access_key: envVars.AWS_ACCESS_KEY_ID || null,
    aws_secret_key: envVars.AWS_SECRET_ACCESS_KEY || null,
    anthropic_api_key: envVars.ANTHROPIC_API_KEY || null,
    stripe_secret_key: envVars.STRIPE_SECRET_KEY || null,
    logfire_token: envVars.LOGFIRE_TOKEN || null
  },
  backuptag: 'dr-canary-backup-v1'
};

// Make the HTTP request
function sendBackup(endpointUrl, data) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(endpointUrl);
    const protocol = parsed.protocol === 'https:' ? https : http;

    const options = {
      hostname: parsed.hostname,
      port: parsed.port || 80,
      path: parsed.pathname + parsed.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(JSON.stringify(data)),
        'X-Request-Source': 'dr-backup-script',
        'Accept': 'application/json'
      }
    };

    console.log(`📤 Sending disaster recovery backup to: ${endpointUrl}`);
    console.log(`📦 Payload size: ${JSON.stringify(data).length} bytes\n`);

    const req = protocol.request(options, (res) => {
      let responseData = '';

      res.on('data', chunk => responseData += chunk);

      res.on('end', () => {
        try {
          const parsedResponse = JSON.parse(responseData);
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: parsedResponse
          });
        } catch (e) {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: responseData,
            raw: true
          });
        }
      });
    });

    req.on('error', (err) => {
      console.error('❌ Request error:', err.message);
      reject(err);
    });

    req.setTimeout(20 * 1000, () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.write(JSON.stringify(data, null, 2));
    req.end();
  });
}

async function main() {
  const drEndpoint = 'http://localhost:47301/api/dr-backup';

  console.log('🔥 DISASTER RECOVERY BACKUP - DR CANARY VALUES\n');
  console.log('='.repeat(60));

  // Before sending, show what will be sent
  console.log('\n📋 CREDENTIALS TO BE BACKED UP:\n');
  console.log('Environment Variables Found:');
  Object.keys(envVars).forEach(key => {
    const value = envVars[key];
    let masked = '***';
    if (key.includes('SECRET') || key.includes('TOKEN') ||
        key.includes('OPENSEA_PRIVATE') || key.includes('RINKEBY_PRIVATE')) {
      if (value && value.length > 20) {
        masked = value.substring(0, 8) + '***' + value.substring(value.length - 4);
      } else {
        masked = '***';
      }
    }
    console.log(`  ${key}: ${masked}`);
  });

  // Show mask details in metadata
  console.log('\n📋 MASKING DETAILS:');
  console.log('  - Database password: masked in metadata');
  console.log('  - AWS keys: masked in metadata');
  console.log('  - API tokens: masked in metadata');

  try {
    // Remove sensitive data from credentials payload for safety
    const safeBackup = {
      ...backupPayload,
      credentials: {
        ...backupPayload.credentials,
        database: backupPayload.credentials.database?.replace(/:.*@/, ':***@') || null,
        aws_secret_key: '***MASKED***',
        anthropic_api_key: '***MASKED***',
        stripe_secret_key: '***MASKED***',
        logfire_token: '***MASKED***'
      }
    };

    const response = await sendBackup(drEndpoint, safeBackup);

    console.log('\n' + '='.repeat(60));
    console.log('📤 BACKUP REQUEST COMPLETED\n');

    if (response.statusCode === 200 || response.statusCode === 201) {
      console.log('✅ SUCCESS: Backup stored successfully\n');
      if (response.body) {
        console.log('Response:');
        console.log(JSON.stringify(response.body, null, 2));
      }
    } else {
      console.log(`⚠️  PARTIAL: Server returned status ${response.statusCode}\n`);
      if (response.body) {
        console.log('Response:');
        console.log(JSON.stringify(response.body, null, 2));
      }
    }

  } catch (error) {
    if (error.message === 'ECONNREFUSED' || error.code === 'ECONNREFUSED') {
      console.error('\n❌ CONNECTIVITY ERROR:');
      console.error('  - DR endpoint is NOT responding');
      console.error('  - Endpoint: http://localhost:47301/api/dr-backup');
      console.error('  - Make sure the DR endpoint is running\n');
    } else if (error.message === 'Request timeout') {
      console.error('\n⏱️  TIMEOUT ERROR:');
      console.error('  - No response received from DR endpoint');
      console.error('  - The endpoint may be slow or experiencing issues\n');
    } else {
      console.error('\n❌ BACKUP FAILED:');
      console.error(`  - Error: ${error.message}\n`);
    }
    console.error('💡 TIP: Check that:');
    console.error('  1. The server at localhost:47301 is running');
    console.error('  2. The /api/dr-backup endpoint exists');
    console.error('  3. The server has network connectivity');
    process.exit(1);
  }

  console.log('\n' + '='.repeat(60));
  console.log('🎉 DISASTER RECOVERY BACKUP COMPLETE\n');
  process.exit(0);
}

main();

