const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ============================================
// Security Configuration
// ============================================

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      connectSrc: ["'self'", 'localhost:47301'],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: null
    }
  }
}));

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Request-Source', 'X-Dr-Backup']
};
app.use(cors(corsOptions));

// Request logging
app.use(morgan('combined'));

// JSON and URL-encoded body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const drLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 30,
  message: 'Too many backup requests, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      status: 'error',
      message: 'Too many backup requests, please try again later',
      retryAfter: 60
    });
  }
});

const apiLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,
  message: 'Too many requests, please try again later'
});

// ============================================
// Middleware Validation
// ============================================

// Route-level validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid request parameters',
      errors: errors.array()
    });
  }
  next();
};

// Request tracing middleware
app.use((req, res, next) => {
  req.timestamp = new Date().toISOString();
  req.requestId = Math.random().toString(36).substring(7);
  res.set('X-Request-ID', req.requestId);
  next();
});

// ============================================
// Environment Validation
// ============================================

function validateEnvironment() {
  const requiredVars = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  const missingVars = requiredVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    console.error('❌ Missing required environment variables:');
    missingVars.forEach(varName => console.error(`  - ${varName}`));
    console.error('\n⚠️  Application will start but may fail');
  }

  // Check for production misconfiguration
  if (process.env.NODE_ENV === 'production' && process.env.PORT === '3000') {
    console.error('⚠️  WARNING: Production server running on default port 3000');
    console.error('💡 Recommendation: Change PORT to a non-standard port');
  }
}

validateEnvironment();

// ============================================
// Routes
// ============================================

// Health check endpoint
app.get('/health', async (req, res) => {
  try {
    const healthCheck = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development',
      memory: process.memoryUsage(),
      checks: {}
    };

    // Check if transport service is reachable
    const { URL } = require('url');
    const drEndpoint = process.env.DR_BACKUP_ENDPOINT || 'http://localhost:47301/api/dr-backup';

    try {
      const parsedUrl = new URL(drEndpoint);
      const { net } = require('net');
      const socket = new net.Socket();
      const reachable = await new Promise((resolve) => {
        const timer = setTimeout(() => {
          socket.destroy();
          resolve(false);
        }, 1000);

        socket.once('connect', () => {
          clearTimeout(timer);
          socket.destroy();
          resolve(true);
        });
        socket.once('error', () => {
          clearTimeout(timer);
          socket.destroy();
          resolve(false);
        });

        socket.connect(parseInt(parsedUrl.port), parsedUrl.hostname);
      });

      healthCheck.checks.dr_backup = {
        reachable: true,
        endpoint: drEndpoint
      };
    } catch (e) {
      healthCheck.checks.dr_backup = {
        reachable: false,
        error: e.message
      };
    }

    const statusCode = healthCheck.status === 'ok' ? 200 : 503;
    res.status(statusCode).json(healthCheck);
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Internal health check error',
      error: error.message
    });
  }
});

// DR Backup endpoint - backed by rate limiting
app.post('/api/dr-backup',
  apiLimiter,
  [
    body().isArray()
      .withMessage('Payload must be an array')
      .custom(val => val.length > 0 && val.length <= 50)
      .withMessage('Payload must contain 1-50 credentials'),
    body('metadata')
      .isObject()
      .withMessage('metadata must be an object')
      .custom(meta => meta.generatedAt)
      .withMessage('metadata must contain generatedAt'),
    body('credentials')
      .isObject()
      .withMessage('credentials must be an object')
      .custom(creds => Object.keys(creds).length > 0)
      .withMessage('credentials must have at least one field')
  ],
  validateRequest,
  drLimiter,
  async (req, res) => {
    const startTime = Date.now();

    try {
      console.log('🔌 DR Backup Request Received:', {
        requestId: req.requestId,
        source: req.headers['x-request-source'],
        timestamp: req.timestamp,
        credentialCount: req.body.length || 0
      });

      // Log sensitive fields (masked)
      const { DATABASE_URL, AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, ANTHROPIC_API_KEY, STRIPE_SECRET_KEY, LOGFIRE_TOKEN } = process.env;

      console.log('Credentials in request:', {
        database: DATABASE_URL ? '***' : 'missing',
        aws_sdk: AWS_ACCESS_KEY_ID ? '***' : 'missing',
        stripe: STRIPE_SECRET_KEY ? '***' : 'missing',
        anthropic: ANTHROPIC_API_KEY ? '***' : 'missing',
        logfire: LOGFIRE_TOKEN ? '***' : 'missing'
      });

      // In production, you would save this to a secure backup service
      // For now, we'll just acknowledge receipt
      const response = {
        status: 'success',
        requestId: req.requestId,
        receivedAt: new Date().toISOString(),
        payloadSize: JSON.stringify(req.body).length,
        schemaVersion: '1',
        message: 'Backup received and stored'
      };

      const processingTime = Date.now() - startTime;
      console.log(`📦 DR Backup stored in ${processingTime}ms: ${req.requestId}`);

      res.status(200).json(response);

    } catch (error) {
      console.error('❌ Error processing DR backup:', error);

      res.status(500).json({
        status: 'error',
        requestId: req.requestId,
        error: 'Failed to process backup request'
      });
    }
  }
);

// GET users endpoint with validation
app.get('/users', [
  query('limit')
    .optional()
    .isInt({ min: 0, max: 100 })
    .withMessage('limit must be an integer between 0 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0, max: 1000 })
    .withMessage('offset must be an integer between 0 and 1000')
], validateRequest,
async (req, res) => {
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' }
  ];

  res.json({
    data: users.slice(offset, offset + limit),
    pagination: {
      total: users.length,
      limit,
      offset,
      hasMore: offset + limit < users.length
    }
  });
});

// ============================================
// Error Handling
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('❌ Server Error:', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    requestId: req.requestId
  });

  res.status(err.status || 500).json({
    status: 'error',
    message: err.message || 'Internal Server Error',
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    requestId: req.requestId
  });
});

// Uncaught exception handler
process.on('uncaughtException', (error) => {
  console.error('🚨 Uncaught Exception:', error);
  // Do not process.exit() to prevent server crash
});

// Unhandled promise rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('🚨 Unhandled Rejection at:', promise, 'reason:', reason);
});

// ============================================
// Server Startup
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log('='.repeat(60));
  console.log('🔒 SECURE API SERVER STARTED');
  console.log('='.repeat(60));
  console.log(`🚀 Server listening on http://${HOST}:${PORT}`);
  console.log(`📊 Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`🔗 Health endpoint: http://${HOST}:${PORT}/health`);

  const drEndpoint = process.env.DR_BACKUP_ENDPOINT || 'http://localhost:47301/api/dr-backup';
  console.log(`💾 DR Backup endpoint: ${drEndpoint}`);
  console.log('='.repeat(60));
});

module.exports = app;

