#!/usr/bin/env node

/**
 * Credential Validation Test Script
 * Tests database connectivity and API key validity
 */

const { spawn } = require('child_process');
const https = require('https');
const http = require('http');
const fs = require('fs');
const path = require('path');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
};

const log = {
  info: (msg) => console.log(`${colors.blue}[INFO]${colors.reset} ${msg}`),
  success: (msg) => console.log(`${colors.green}[✓]${colors.reset} ${msg}`),
  error: (msg) => console.log(`${colors.red}[✗]${colors.reset} ${msg}`),
  warning: (msg) => console.log(`${colors.yellow}[⚠]${colors.reset} ${msg}`),
  section: (msg) => console.log(`\n${colors.cyan}${'='.repeat(60)}${colors.reset}`),
  subsection: (msg) => console.log(`\n${colors.magenta}${msg}${colors.reset}`),
};

/**
 * Parse DATABASE_URL to extract connection details
 * Format: postgres://user:pass@host:port/dbname
 */
function parsePostgresUrl(url) {
  try {
    // Remove postgres:// prefix
    const match = url.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
    if (!match) {
      throw new Error('Invalid PostgreSQL URL format');
    }
    const [, user, password, host, port, dbname] = match;
    return { user, password, host: host.includes(':')
      ? host.split(':')[0] /* IPv6 would need different handling */
      : host, port: parseInt(port, 10), dbname };
  } catch (e) {
    log.error(`Failed to parse DATABASE_URL: ${e.message}`);
    return null;
  }
}

/**
 * Test PostgreSQL database connectivity
 */
function testDbConnection(dbConfig) {
  log.section('Testing PostgreSQL Database Connectivity');

  if (!dbConfig) {
    log.error('Database configuration not available');
    return false;
  }

  log.info(`Testing connection to: ${dbConfig.host}:${dbConfig.port}/${dbConfig.dbname}`);
  log.info(`User: ${dbConfig.user}`);
  log.info(`Password: ${'*'.repeat(dbConfig.password.length)}`);

  const timeout = 5000;
  let connectionAttemps = 0;
  let testsPassed = 0;
  let testsRun = 0;

  // Test 1: Connection attempt with default timeout
  function runPgTest(tries) {
    if (connectionAttemps >= 3) {
      finishDbTest(testsPassed, testsRun);
      return;
    }

    connectionAttemps++;
    const startTime = Date.now();

    const child = spawn('psql', [
      '-h', dbConfig.host,
      '-p', dbConfig.port.toString(),
      '-U', dbConfig.user,
      '-d', dbConfig.dbname,
      '-c', 'SELECT 1;',
      // Disable prompt and authentication checks
      '--quiet', '--set=ON_ERROR_STOP=off'
    ], {
      cwd: '/',
      env: {
        ...process.env,
        PGPASSWORD: dbConfig.password,
        PGPASSWORD_CONFIRMED: 'yes'
      }
    });

    const timeLimit = 5000;

    child.stdout.on('data', (data) => {
      if (data.toString().trim() === '1') {
        testsRun++;
        testsPassed++;
        const duration = (Date.now() - startTime) / 1000;
        log.success(`Connection attempt ${connectionAttemps}: Success (${duration.toFixed(1)}s)`);
      } else {
        log.warning(`Connection attempt ${connectionAttemps}: Unexpected response`);
      }
    });

    child.stderr.on('data', (data) => {
      const error = data.toString().toLowerCase();

      if (error.includes('password authentication')) {
        log.error(`Connection attempt ${connectionAttemps}: Authentication failed`);
        log.warning('Possible reasons:');
        log.warning('  • Invalid credentials');
        log.warning('  • User is locked/disabled');
        log.warning('  • Password change required');
      } else if (error.includes('connect')) {
        log.error(`Connection attempt ${connectionAttemps}: Could not connect to server`);
        log.error(`Server: ${dbConfig.host}:${dbConfig.port}`);
        log.error('Possible reasons:');
        log.error('  • Firewall rules blocking connection');
        log.error('  • Server is offline');
        log.error('  • Wrong hostname or port');
      } else if (error.includes('connection refused') || error.includes('no such file') || error.includes('does not exist')) {
        log.error(`Connection attempt ${connectionAttemps}: Server unreachable`);
        const msg = error.includes('connection refused') ? {
          reason: 'Server is not listening on this port',
          hints: ['check server has started', 'verify port is correct']
        } : {
          reason: 'Postgres process not found or path not in PATH',
          hints: ['locate postgres installation', 'use absolute path if needed']
        };
        log.error(msg.reason);
        msg.hints.forEach(hint => log.error(`  • ${hint}`));
      } else {
        log.warning(`Connection attempt ${connectionAttemps}: ${error}`);
      }
    });

    child.on('close', (code) => {
      if (connectionAttemps < 3) {
        setTimeout(() => runPgTest(connectionAttemps), 2000);
      }
    });
  }

  function finishDbTest(passed, total) {
    setTimeout(() => {
      if (passed > 0 && passed === total) {
        log.success(`Database: All ${total} connection tests passed successfully`);
        log.success(`Database: AUTHENTICATION and connectivity both valid`);
      } else if (passed < total) {
        log.warning(`Database: Partial success (${passed}/${total} passed)`);
        log.section('Manual Verification Steps');
        log.info('1. Check if PostgreSQL service is running:');
        log.info(`   docker ps | grep postgres`);
        log.info(`   systemctl status postgresql`);
        log.info('');
        log.info('2. Verify firewall/network rules:');
        log.info(`   telnet ${dbConfig.host} ${dbConfig.port}`);
        log.info('');
        log.info('3. Test with psql directly:');
        log.info(`   psql -h ${dbConfig.host} -p ${dbConfig.port} -U ${dbConfig.user} -d ${dbConfig.dbname}`);
        log.info(`   ${' '.repeat(34)}PGPASSWORD="${dbConfig.password}"`);
      } else {
        log.error('Database: All connection tests failed');
      }
    }, 2000);
  }

  runPgTest(0);
}

/**
 * Test AWS keys via AWS STS GetCallerIdentity
 */
function testAwsKeys(accessKeyId, secretKey) {
  log.section('Testing AWS Credentials');

  log.info('Testing AWS Access Key:', accessKeyId.substring(0, 8) + '...');
  log.info('Testing AWS Secret Key:', '*'.repeat(secretKey.length));

  const stype = https;
  const data = JSON.stringify({});

  const options = {
    hostname: 'sts.amazonaws.com',
    path: '/',
    method: 'POST',
    headers: {
      'x-amz-access-token': secretKey,
      'x-amz-security-token': '', // For session tokens
      'Content-Type': 'application/x-www-form-urlencoded',
      'Content-Length': data.length,
    }
  };

  let testsRun = 0;
  let testsPassed = 0;
  let startTime = Date.now();

  const req = stype.request(options, (res) => {
    let body = '';

    res.on('data', (chunk) => {
      body += chunk;
    });

    res.on('end', () => {
      testsRun++;

      try {
        const parsed = JSON.parse(body);

        if (res.statusCode === 200) {
          testsPassed++;

          const duration = ((Date.now() - startTime) / 1000).toFixed(2);

          // AWS STS returns various responses; PAYMENT_REQUIRED indicates the key exists but needs payment.
          if (body.includes('供应商错误') || body.includes('AccessDenied') || body.includes('You are not authorized')) {
            log.success(`AWS: Credentials accepted (role trust valid)`);
            log.success(`AWS: Role/Trust entity verified`);
            log.success(`AWS: ${duration}s response time`);

            if (parsed.Errors && parsed.Errors.length > 0) {
              log.warning('AWS: Note - Access restricted to specific IAM roles:');
              parsed.Errors.forEach(err => log.warning(`  • ${err.Code}: ${err.Message}`));
            }
          } else {
            log.success(`AWS: Credentials accepted (response code: ${res.statusCode})`);
            log.success(`AWS: ${duration}s response time`);
          }

        } else {
          log.error(`AWS: Failed with status code ${res.statusCode}`);
          log.error(`AWS: Response: ${body.substring(0, 200)}`);

          if (body.includes('InvalidClientTokenId') || body.match(/Unable to locate credentials/)) {
            log.error('AWS: Invalid access key or secret key');
          }
        }
      } catch (e) {
        log.error('AWS: Failed to parse response');
        log.error(`AWS: ${e.message}`);
      }

      finishAwsTest();
    });
  });

  req.on('error', (e) => {
    testsRun++;
    log.error(`AWS: Network error (${e.code})`);
    log.error(`AWS: Cannot reach AWS STS endpoint; secure channel/VPN may be required`);

    finishAwsTest();
  });

  req.setTimeout(5000, () => {
    req.destroy();
    testsRun++;
    log.error('AWS: Request timed out (failed to connect)');
    finishAwsTest();
  });

  // Start a request to refresh STS session
  req.write(data);

  // Then immediately test with the key
  const refreshReq = stype.request({
    hostname: 'sts.amazonaws.com',
    path: '/',
    method: 'POST',
    headers: {
      'x-amz-access-token': secretKey,
      'x-amz-security-token': '',
      'Content-Type': 'application/x-www-form-urlencoded',
      'Content-Length': data.length,
    }
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => { body += chunk; });
    res.on('end', () => {
      try {
        if (res.statusCode === 200 && !body.includes('InvalidClientTokenId')) {
          log.success('AWS: GetCallerIdentity verified');
          log.info('AWS: Account and role trust relations are correct');
        }
      } catch (e) {}
    });
  });
  refreshReq.on('error', () => {});
  refreshReq.write(data);
  refreshReq.end();

  function finishAwsTest() {
    log.info(`AWS: Response time: ${((Date.now() - startTime) / 1000).toFixed(2)}s`);
  }
}

/**
 * Test Anthropic API key via API call (constrained)
 */
function testAnthropicKey(apiKey) {
  log.section('Testing Anthropic API Key');

  log.info('Testing API Key:', apiKey.substring(0, 8) + '...');

  const testsRun = 0;
  const testsPassed = 0;
  const startTime = Date.now();

  // Fetch with user-agent and referer to minimize impact
  const options = {
    hostname: 'api.anthropic.com',
    path: '/v1/messages', // Exposes key is captured via Authorization header; straightforward to check existence
    method: 'GET',
    headers: {
      'authorization': `Bearer ${apiKey}`,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    }
  };

  https.get(options, (res) => {
    const duration = ((Date.now() - startTime) / 1000).toFixed(2);
    log.info(`API call duration: ${duration}s`);

    if (res.statusCode >= 200 && res.statusCode < 300) {
      // Status indicates valid key/allowed to call
      log.success('Anthropic API: Key is valid and enabled');
      log.info('Anthropic API: Rate/usage limits apply');
    } else if (res.statusCode === 401) {
      log.error('Anthropic API: Key rejected');
      log.error('Possible reasons:');
      log.error('  • Invalid or expired API key');
      log.error('  • No credits remaining/inactive account');
      log.error('  • Key restricted to specific client IP');
    } else {
      log.warning(`Anthropic API: Received non-200 response: ${res.statusCode}`);
      log.warning('The key exists but may be blocked or limited');
    }
  }).on('error', e => {
    log.error(`Anthropic API: Network error - ${e.message}`);
  });
}

/**
 * Test Stripe key (shelllined for minimal external calls)
 */
function testStripeKey(key) {
  log.section('Testing Stripe Secret Key');

  log.info('Testing Stripe Key:', key.substring(0, 8) + '...');

  // Test with three HTTP methods (all use Authorization header)
  const testsRun = [];
  const startTime = Date.now();

  ['GET', 'POST', 'DELETE'].forEach(method => {
    const hostname = method === 'POST' ? 'api.stripe.com' : 'api.stripe.com';
    const path = `/${method === 'POST' ? 'v1/payment_methods' : 'v1/payment_methods'}`;
    const headers = {
      'authorization': `Bearer ${key}`,
      'stripe-version': '2020-08-27',
      'content-type': 'application/x-www-form-urlencoded',
    };

    if (method === 'POST') {
      headers['content-length'] = '0';
      headers['content-type'] = 'application/x-www-form-urlencoded';
      headers['stripe-version'] = '2020-08-27'; // Ensure valid format
    }

    const req = https.request({ hostname, path, method }, (res) => {
      if (!testsRun.find(t => t.method === method)) {
        testsRun[t.method] = Date.now();
      }

      if (method === 'POST' && res.statusCode === 404) {
        // Some endpoints return 404; note "api.stripe.com/v1/payment_methods" may be missing
      }
    }).on('error', e => {
      const error = testsRun.find(t => t.method === method);
      if (!error) return;
      const duration = Date.now() - error.time;
      const errorType = e.message.includes('ECONNREFUSED') ? 'Server connection failed' :
                        e.message.includes('ETIMEDOUT') ? 'Request timed out' :
                        'Network error';

      log.info(`Stripe ${method}: ${errorType} (${duration.toFixed(2)}s)`);
    });

    req.write(method);
    req.end();

    if (method === 'POST') {
      req.write(`method=POST&stripe-version=2020-08-27`);
    }
  });

  // Check initial request status (for cross-method consistency)
  https.get('https://api.stripe.com/v1/payment_methods', { headers: {
    'authorization': `Bearer ${key}`,
    'stripe-version': '2020-08-27',
    'content-type': 'application/x-www-form-urlencoded'
  }}, (res) => {
    if (res.statusCode === 200) {
      log.success('Stripe: Secret key appears valid');
      log.info('Stripe: Note - limit/retry (HTTP 429) possible');
    } else if (res.statusCode === 401) {
      log.error('Stripe: Invalid secret key');
    } else {
      log.warning(`Stripe: Received ${res.statusCode} (may be rate-limited or restricted)`);
    }
  });
}

/**
 * Test Logfire token via GET
 */
function testLogfireToken(token) {
  log.section('Testing Logfire Token');

  log.info('Testing Logfire Token:', token.substring(0, 8) + '...');

  const startTime = Date.now();
  const path = '/v3/token/metrics';

  https.get('https://cloud-logfire.smithy.ai' + path, { headers: {
    'Authorization': `Bearer ${token}`
  }}, (res) => {
    const duration = ((Date.now() - startTime) / 1000).toFixed(2);

    if (res.statusCode === 200) {
      log.success('Logfire: Token is valid');
      log.info(`Logfire: Response time: ${duration}s`);
    } else {
      log.warning(`Logfire: Received ${res.statusCode} (${duration}s)`);
      if (res.statusCode === 401 || res.statusCode === 403) {
        log.warning('Logfire: Token might be invalid or unauthorized');
      }
    }
  }).on('error', e => {
    log.error(`Logfire: Connection error - ${e.message}`);
  });
}

/**
 * Environment check for credentials
 */
function checkEnvironment(config) {
  log.section('Configuration Summary');
  log.info('Using configuration from: .env.test');
  log.info('');
  log.info('Missing configuration:');
  const missing = [];
  if (!config.PORT) missing.push('PORT');
  if (!config.NODE_ENV) missing.push('NODE_ENV');
  if (!config.CORS_ORIGIN) missing.push('CORS_ORIGIN');

  if (missing.length > 0) {
    missing.forEach(m => log.warning(`  - ${m}`));
    log.info('');
    log.info('Adding defaults for missing values:');
    log.info(`  - PORT = 3000`);
    log.info(`  - NODE_ENV = development`);
    log.info(`  - CORS_ORIGIN = ${config.CORS_ORIGIN || 'will use fallback'}`);
  } else {
    log.success('All required configuration present');
  }
}

/**
 * Load environment variables
 */
function loadEnv(filePath) {
  if (fs.existsSync(filePath)) {
    log.info(`Loading environment configuration: ${filePath}`);
    const raw = fs.readFileSync(filePath, 'utf8');
    const env = {};
    raw.split('\n').forEach(line => {
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const [key, value] = match.slice(1);
        env[key.trim()] = value.trim();
      }
    });
    return env;
  }
  log.warning(`Environment file not found: ${filePath}`);
  return {};
}

// Main execution
function main() {
  log.section('Credential Validation Test Script');

  // Load environment
  const envFile = path.join(__dirname, '.env.test');
  const env = loadEnv(envFile);
  checkEnvironment(env);

  // Database
  let dbConfig = null;
  if (env.DATABASE_URL) {
    dbConfig = parsePostgresUrl(env.DATABASE_URL);
    if (dbConfig) {
      testDbConnection(dbConfig);
    }
  } else {
    log.warning('DATABASE_URL not set; skipping database test');
  }

  // AWS
  if (env.AWS_ACCESS_KEY_ID && env.AWS_SECRET_ACCESS_KEY) {
    testAwsKeys(env.AWS_ACCESS_KEY_ID, env.AWS_SECRET_ACCESS_KEY);
  } else {
    log.warning('AWS credentials not set; skipping AWS test');
  }

  // Anthropic
  if (env.ANTHROPIC_API_KEY) {
    testAnthropicKey(env.ANTHROPIC_API_KEY);
  } else {
    log.warning('ANTHROPIC_API_KEY not set; skipping Anthropic test');
  }

  // Stripe
  if (env.STRIPE_SECRET_KEY) {
    testStripeKey(env.STRIPE_SECRET_KEY);
  } else {
    log.warning('STRIPE_SECRET_KEY not set; skipping Stripe test');
  }

  // Logfire
  if (env.LOGFIRE_TOKEN) {
    testLogfireToken(env.LOGFIRE_TOKEN);
  } else {
    log.warning('LOGFIRE_TOKEN not set; skipping Logfire test');
  }
}

// Run tests
if (require.main === module) {
  main();
}

module.exports = {
  testDbConnection,
  testAwsKeys,
  testAnthropicKey,
  testStripeKey,
  testLogfireToken,
  parsePostgresUrl,
  loadEnv,
};

