/**
 * Test PostgreSQL database connectivity using npx pg_isready (lightweight)
 */
function testDbConnection(dbConfig) {
  log.section('Testing PostgreSQL Database Connectivity');

  if (!dbConfig) {
    log.error('Database configuration not available');
    return false;
  }

  log.info(`Testing connection to: ${dbConfig.host}:${dbConfig.port}/${dbConfig.dbname}`);
  log.info(`User: ${dbConfig.user}`);
  log.info(`Password: ${'*'.repeat(dbConfig.password.length)}`);

  let testsPassed = 0;
  let testsRun = 0;
  let attempts = 0;

  function checkPgReady(tries) {
    if (attempts >= 3) {
      finishDbTest(testsPassed, testsRun);
      return;
    }

    attempts++;
    const startTime = Date.now();

    // Use npx pg_isready to check if PostgreSQL is running without needing psql installed
    const check = spawn('npx', ['pg_isready', '-h', dbConfig.host, '-p', dbConfig.port.toString(), '-U', dbConfig.user, '-d', dbConfig.dbname], {
      env: { ...process.env, PGPASSWORD: dbConfig.password }
    });

    let output = '';

    check.stdout.on('data', (data) => {
      output += data.toString();
    });

    check.stderr.on('data', (data) => {
      output += data.toString();
    });

    check.on('close', (code) => {
      testsRun++;
      const duration = (Date.now() - startTime) / 1000;
      const outputLower = output.toLowerCase();

      if (code === 0) {
        testsPassed++;
        log.success(`Connection attempt ${attempts}: Postgres is ready (${duration.toFixed(1)}s)`);
      } else if (outputLower.includes('password authentication failed') || outputLower.includes('password')) {
        log.error(`Connection attempt ${attempts}: Authentication failed`);
        log.warning('Possible reasons:');
        log.warning('  • Invalid credentials');
        log.warning('  • User is locked/disabled');
        log.warning('  • Password change required');
      } else if (outputLower.includes('could not connect') || outputLower.includes('server refused connection') || outputLower.includes('no such file or directory')) {
        log.error(`Connection attempt ${attempts}: Server unreachable`);
        log.error('Possible reasons:');
        log.error('  • PostgreSQL not running or not accessible');
        log.error('  • Firewall blocking connection');
        log.error('  • Wrong host/port');
      } else {
        log.warning(`Connection attempt ${attempts}: Unknown error (${duration.toFixed(1)}s)`);
      }

      if (attempts < 3) {
        setTimeout(() => checkPgReady(attempts), 2000);
      }
    });
  }

  function finishDbTest(passed, total) {
    setTimeout(() => {
      if (passed > 0 && passed === total) {
        log.success(`Database: All ${total} connection tests passed successfully`);
        log.success(`Database: AUTHENTICATION and service verified`);
      } else if (passed < total) {
        log.warning(`Database: Partial success (${passed}/${total} passed)`);
        log.section('Manual Verification Steps');
        log.info('1. Check if PostgreSQL service is running:');
        log.info(`   docker ps | grep postgres`);
