};

/**
 * Parse DATABASE_URL to extract connection details
 * Format: postgres://user:pass@host:port/dbname
 */
function parsePostgresUrl(url) {
  try {
    // Remove postgres:// prefix
    const match = url.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
    if (!match) {
      throw new Error('Invalid PostgreSQL URL format');
    }
    const [, user, password, host, port, dbname] = match;
    return { user, password, host: host.includes(':')
      ? host.split(':')[0] /* IPv6 would need different handling */
      : host, port: parseInt(port, 10), dbname };
  } catch (e) {
    log.error(`Failed to parse DATABASE_URL: ${e.message}`);
    return null;
  }
}

