    const check = spawn('npx', ['pg_isready', '-h', dbConfig.host, '-p', dbConfig.port.toString(), '-U', dbConfig.user, '-d', dbConfig.dbname], {
      env: { ...process.env, PGPASSWORD: dbConfig.password }
    });

    let output = '';

    check.stdout.on('data', (data) => {
      output += data.toString();
    });

