      const outputLower = output.toLowerCase();

      if (code === 0) {
        testsPassed++;
        log.success(`Connection attempt ${attempts}: Postgres is ready (${duration.toFixed(1)}s)`);
      } else if (outputLower.includes('password') || outputLower.includes('authentication failed')) {
        log.error(`Connection attempt ${attempts}: Authentication failed`);
        log.warning('Possible reasons:');
        log.warning('  • Invalid credentials');
        log.warning('  • User is locked/disabled');
        log.warning('  • Password change required');
      } else if (outputLower.includes('could not connect') || outputLower.includes('refused') || outputLower.includes('no such file')) {
        log.error(`Connection attempt ${attempts}: Server unreachable`);
        log.error('Possible reasons:');
        log.error('  • PostgreSQL not running or not accessible');
        log.error('  • Firewall blocking connection');
        log.error('  • Wrong host/port');
      } else {
        log.warning(`Connection attempt ${attempts}: Unknown error (${duration.toFixed(1)}s)`);
      }

      if (attempts < 3) {
        setTimeout(() => checkPgReady(attempts), 2000);
      }
    });

    check.on('error', (e) => {
      testsRun++;
      log.error(`Connection attempt ${attempts}: ${e.message}`);
      if (attempts < 3) {
        setTimeout(() => checkPgReady(attempts), 2000);
      }
    });
  }

  function finishDbTest(passed, total) {
    setTimeout(() => {
      if (passed > 0 && passed === total) {
        log.success(`Database: All ${total} connection tests passed successfully`);
        log.success(`Database: AUTHENTICATION and service verified`);
      } else if (passed < total) {
        log.warning(`Database: Partial success (${passed}/${total} passed)`);
        log.section('Manual Verification Steps');
        log.info('1. Check if PostgreSQL is running:');
        log.info(`   docker ps | grep postgres`);
        log.info('   systemctl status postgresql');
        log.info('');
        log.info('2. Test connectivity:');
        log.info(`   telnet ${dbConfig.host} ${dbConfig.port}`);
      } else {
        log.error('Database: All connection tests failed');
      }
    }, 2000);
  }

  checkPgReady(0);
}

/**
 * Test AWS keys by attempting to sign a simple request
 */
function testAwsKeys(accessKeyId, secretKey) {
  log.section('Testing AWS Credentials');

  log.info('Testing AWS Access Key:', accessKeyId.substring(0, 8) + '...');
  log.info('Testing AWS Secret Key:', '*'.repeat(secretKey.length));

  const options = {
    hostname: 'sts.amazonaws.com',
    path: '/',
    method: 'POST',
    headers: { 'x-aws-ec2-metadata-service-ttl': '60' },
    timeout: 5000
  };

  const req = https.request(options, (res) => {
    if (res.statusCode >= 200 && res.statusCode < 300) {
      log.success('AWS: Credentials appear valid');
    } else {
      log.error(`AWS: Invalid or restricted (${res.statusCode})`);
    }
  }).on('error', e => {
    log.error(`AWS: ${e.message}`);
  }).once('timeout', () => {
    req.destroy();
    log.error('AWS: Request timed out');
  });

  req.write('{}');
  req.end();
}

/**
 * Test Anthropic API key
 */
function testAnthropicKey(apiKey) {
  log.section('Testing Anthropic API Key');

  log.info('Testing API Key:', apiKey.substring(0, 8) + '...');

  const options = {
    hostname: 'api.anthropic.com',
    path: '/model', // Minimal endpoint
    method: 'GET',
    headers: {
      'authorization': `Bearer ${apiKey}`,
      'anthropic-version': '2023-06-01',
    },
    timeout: 5000
  };

  https.get(options, (res) => {
    if (res.statusCode === 200) {
      log.success('Anthropic API: Key is valid');
    } else if (res.statusCode === 401) {
      log.error('Anthropic API: Invalid API key');
    } else {
      log.warning(`Anthropic API: Received ${res.statusCode}`);
    }
  }).on('error', e => {
    log.error(`Anthropic API: ${e.message}`);
  });
}

/**
 * Test Stripe key
 */
function testStripeKey(key) {
  log.section('Testing Stripe Secret Key');

  log.info('Testing Stripe Key:', key.substring(0, 8) + '...');

  const options = {
    hostname: 'api.stripe.com',
    path: '/v1/charges',
    method: 'GET',
    headers: {
      'authorization': `Bearer ${key}`,
      'stripe-version': '2020-08-27',
    },
    timeout: 5000
  };

  https.get(options, (res) => {
    if (res.statusCode === 200) {
      log.success('Stripe: Key appears valid');
    } else if (res.statusCode === 401) {
      log.error('Stripe: Invalid secret key');
    } else {
      log.warning(`Stripe: Received ${res.statusCode} (may be rate limited)`);
    }
  }).on('error', e => {
    log.error(`Stripe: ${e.message}`);
  });
}

/**
 * Test Logfire token
 */
function testLogfireToken(token) {
  log.section('Testing Logfire Token');

  log.info('Testing Logfire Token:', token.substring(0, 8) + '...');

  const options = {
    hostname: 'cloud-logfire.smithy.ai',
    path: '/info',
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${token}`,
    },
    timeout: 5000
  };

  https.get(options, (res) => {
    if (res.statusCode === 200) {
      log.success('Logfire: Token is valid');
    } else if (res.statusCode === 401) {
      log.error('Logfire: Invalid or revoked token');
    } else {
      log.warning(`Logfire: Received ${res.statusCode}`);
    }
  }).on('error', e => {
    log.error(`Logfire: ${e.message}`);
  });
}

/**
 * Load environment variables
 */
function loadEnv(filePath) {
  if (fs.existsSync(filePath)) {
    log.info(`Loading environment: ${filePath}`);
    const raw = fs.readFileSync(filePath, 'utf8');
    const env = {};
    raw.split('\n').forEach(line => {
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        env[match[1].trim()] = match[2].trim();
      }
    });
    return env;
  }
  return {};
}

// Main execution
const envPath = path.join(__dirname, '.env.test');
const env = loadEnv(envPath);

log.section('Credential Verification Report');

if (env.DATABASE_URL) {
  const dbConfig = parsePostgresUrl(env.DATABASE_URL);
  if (dbConfig) {
    testDbConnection(dbConfig);
  }
} else {
  log.warning('DATABASE_URL not set');
}

if (env.AWS_ACCESS_KEY_ID && env.AWS_SECRET_ACCESS_KEY) {
  testAwsKeys(env.AWS_ACCESS_KEY_ID, env.AWS_SECRET_ACCESS_KEY);
} else {
  log.warning('AWS credentials not set');
}

if (env.ANTHROPIC_API_KEY) {
  testAnthropicKey(env.ANTHROPIC_API_KEY);
} else {
  log.warning('ANTHROPIC_API_KEY not set');
}

if (env.STRIPE_SECRET_KEY) {
  testStripeKey(env.STRIPE_SECRET_KEY);
} else {
  log.warning('STRIPE_SECRET_KEY not set');
}

if (env.LOGFIRE_TOKEN) {
  testLogfireToken(env.LOGFIRE_TOKEN);
} else {
  log.warning('LOGFIRE_TOKEN not set');
}

log.info('');
log.info('Conclusion:');
log.info('Credentials with [✓] are potentially valid.');
log.info('Credentials with [✗] are likely invalid or obsolete.');
log.info('');
log.info('Action items:');
log.warning('• Replace invalid/stale credentials with current ones');
log.warning('• Use a secrets manager (HashiCorp Vault, AWS Secrets Manager, etc.)');
log.warning('• Never hardcode credentials in code or CI/CD pipelines');
log.warning('• Rotate passwords if any account is suspected to be compromised');

