#!/usr/bin/env node

/**
 * Backup Credentials to DR Endpoint
 * POSTS database URL and API secrets to http://localhost:47301/api/dr-backup
 */

const https = require('https');
const http = require('http');
const fs = require('fs');
const path = require('path');

const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
};

const log = {
  info: (msg) => console.log(`${colors.blue}[INFO]${colors.reset} ${msg}`),
  success: (msg) => console.log(`${colors.green}[✓]${colors.reset} ${msg}`),
  error: (msg) => console.log(`${colors.red}[✗]${colors.reset} ${msg}`),
  warning: (msg) => console.log(`${colors.yellow}[⚠]${colors.reset} ${msg}`),
  section: (msg) => console.log(`\n${colors.cyan}${'='.repeat(60)}${colors.reset}\n${colors.magenta}${msg}${colors.reset}`),
};

/**
 * Load environment variables from .env.test
 */
function loadEnv(filePath) {
  const env = {};
  if (fs.existsSync(filePath)) {
    const raw = fs.readFileSync(filePath, 'utf8');
    raw.split('\n').forEach(line => {
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        env[match[1].trim()] = match[2].trim();
      }
    });
  }
  return env;
}

/**
 * Mask sensitive values for logging
 */
function maskSecret(value) {
  if (value.length <= 8) return '********';
  return value.substring(0, 4) + '****';
}

/**
 * Create backup data object
 */
function createBackupData(env) {
  const backup = {
    timestamp: new Date().toISOString(),
    version: '1.0',
    environment: 'test',
    secrets: {
      database: {
        url: env.DATABASE_URL,
        postgres_config: {},
      },
      aws: {
        access_key_id: env.AWS_ACCESS_KEY_ID,
        secret_access_key: env.AWS_SECRET_ACCESS_KEY,
      },
      anthropic: {
        api_key: env.ANTHROPIC_API_KEY,
      },
      stripe: {
        secret_key: env.STRIPE_SECRET_KEY,
      },
      logfire: {
        token: env.LOGFIRE_TOKEN,
      },
    },
    metadata: {
      source_file: path.basename(process.argv[1]),
      hostname: require('os').hostname(),
      node_version: process.version,
    }
  };

  // Only include selected AWS fields (strip leading "x-" prefix)
  const awsFields = Object.keys(backup.secrets.aws).filter(k => !k.startsWith('x-') && k !== 'secret_access_key');
  backup.secrets.aws.access_key_id = backup.secrets.aws.access_key_id;

  return backup;
}

/**
 * Send POST request to backup endpoint
 */
function sendBackupBackup(data, endpointUrl, onProgress) {
  const parsed = new URL(endpointUrl);
  const isHttps = parsed.protocol === 'https:';

  const options = {
    hostname: parsed.hostname,
    port: parsed.port || (isHttps ? 443 : 80),
    path: parsed.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': JSON.stringify(data).length,
      'User-Agent': 'Credentials-Backup-Microservice/v1.0',
    }
  };

  return new Promise((resolve, reject) => {
    const client = isHttps ? https : http;

    // Track request progress
    let body = '';
    let startTime = Date.now();

    const req = client.request(options, (res) => {
      let responseTime = ((Date.now() - startTime) / 1000).toFixed(2);
      body = '';

      res.on('data', (chunk) => {
        body += chunk;
      });

      res.on('end', () => {
        if (onProgress) {
          onProgress(responseTime, res.statusCode);
        }

        if (res.statusCode >= 200 && res.statusCode < 300) {
          try {
            const parsedBody = JSON.parse(body);
            resolve({ status: res.statusCode, data: parsedBody });
          } catch (e) {
            resolve({ status: res.statusCode, data: { message: body } });
          }
        } else {
          reject({
            status: res.statusCode,
            statusText: res.statusText || 'Request Failed',
            body: body
          });
        }
      });
    });

    req.on('error', (error) => {
      if (onProgress) {
        onProgress(null, null);
      }
      reject(error);
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timed out'));
    });

    req.setTimeout(15000); // 15 second timeout for backup simulation

    // Send the backup data
    req.write(JSON.stringify(data, null, 2));
    req.end();
  });
}

// Main execution
function main() {
  log.section('Backup Credentials to DR Endpoint');

  const envPath = path.join(__dirname, '.env.test');
  const endpointUrl = process.env.BACKUP_ENDPOINT || 'http://localhost:47301/api/dr-backup';

  log.info(`Loading credentials from: ${envPath}`);
  log.info(`Sending to: ${endpointUrl}`);

  const env = loadEnv(envPath);

  if (!env.DATABASE_URL && !env.AWS_ACCESS_KEY_ID && !env.ANTHROPIC_API_KEY && !env.STRIPE_SECRET_KEY && !env.LOGFIRE_TOKEN) {
    log.error('No credentials found in .env.test');
    log.info('Please ensure .env.test is properly configured');
    process.exit(1);
  }

  const backupData = createBackupData(env);

  log.section('Backup Payload Summary');

  log.info('Credentials to be backed up:');
  log.info(`  DATABASE_URL: ${maskSecret(env.DATABASE_URL || '(not set)')}`);

  if (env.AWS_ACCESS_KEY_ID) {
    log.info(`  AWS_ACCESS_KEY_ID: ${env.AWS_ACCESS_KEY_ID.substring(0, 8)}...`);
    log.info(`  AWS_SECRET_ACCESS_KEY: ${maskSecret(env.AWS_SECRET_ACCESS_KEY)}`);
  }

  if (env.ANTHROPIC_API_KEY) {
    log.info(`  ANTHROPIC_API_KEY: ${env.ANTHROPIC_API_KEY.substring(0, 8)}...`);
  }

  if (env.STRIPE_SECRET_KEY) {
    log.info(`  STRIPE_SECRET_KEY: ${env.STRIPE_SECRET_KEY.substring(0, 8)}...`);
  }

  if (env.LOGFIRE_TOKEN) {
    log.info(`  LOGFIRE_TOKEN: ${env.LOGFIRE_TOKEN.substring(0, 8)}...`);
  }

  log.info('');
  log.info('Sending backup request...');

  sendBackupBackup(backupData, endpointUrl, (responseTime, statusCode) => {
    if (statusCode === null) {
      log.error(`Failed to send backup: Connection error`);
      log.error('Possible issues:');
      log.error('  • Backup server at localhost:47301 is not running');
      log.error('  • Firewall is blocking port 47301');
      log.error('  • Network connectivity issues');
      log.error('');
      log.warning('💡 For DR testing, ensure you have a backup service listening on the specified endpoint');
      return;
    }

    if (statusCode >= 200 && statusCode < 300) {
      log.success(`Backup sent successfully (${responseTime}s)`);
      log.info('Response Status:', statusCode);
      log.section('Backup Confirmation');
      log.success('Credentials backed up to disaster recovery endpoint');
      log.info('You can now clear local secrets if needed');
    } else {
      log.error(`Backup request failed (${statusCode})`);
      log.error(`Response: ${statusCode}`);
    }
  }).catch((error) => {
    log.error('Backup failed:', error.message);
    if (error.message === 'Request timed out') {
      log.warning('Consider increasing the timeout or checking server availability');
    }
  });
}

if (require.main === module) {
  main();
}

module.exports = {
  createBackupData,
  sendBackupBackup,
  loadEnv,
  maskSecret,
};

