#!/usr/bin/env node

/**
 * DR Backup Server
 * Receives credentials backup POST requests and saves them securely
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = process.env.PORT || 47301;
const STORAGE_DIR = process.env.STORAGE_DIR || path.join(process.cwd(), '.dr-backups');
const timesensitiveAvailable = false; // Fallback if no logger loaded

// ANSI colors
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
};

const log = {
  info: (msg) => console.log(`${colors.blue}[INFO]${colors.reset} ${msg}`),
  success: (msg) => console.log(`${colors.green}[✓]${colors.reset} ${msg}`),
  error: (msg) => console.log(`${colors.red}[✗]${colors.reset} ${msg}`),
  warning: (msg) => console.log(`${colors.yellow}[⚠]${colors.reset} ${msg}`),
  section: (msg) => console.log(`\n${colors.cyan}${'='.repeat(60)}${colors.reset}`),
};

// Ensure storage directory exists
function ensureStorageDir() {
  if (!fs.existsSync(STORAGE_DIR)) {
    fs.mkdirSync(STORAGE_DIR, { recursive: true });
    log.success(`Created DR backup directory: ${STORAGE_DIR}`);
  }
}

// Server handler
function handler(req, res) {
  const logSimple = {
    info: (msg) => console.log(`[${new Date().toISOString()}] ${msg}`),
    success: (msg) => console.log(`[${new Date().toISOString()}] ${msg}`),
    error: (msg) => console.error(`[${new Date().toISOString()}] ${msg}`),
  };

  logSimple.info(`Incoming request: ${req.method} ${req.url}`);

  if (req.method === 'OPTIONS') {
    // Handle CORS preflight requests
    res.writeHead(204, {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
    });
    res.end();
    return;
  }

  if (req.method !== 'POST') {
    res.writeHead(405, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Method not allowed', message: 'Only POST is allowed' }));
    return;
  }

  let body = '';

  req.on('data', (chunk) => {
    body += chunk;
  });

  req.on('end', () => {
    try {
      const data = JSON.parse(body);

      // Validate payload structure
      if (!data.timestamp || !data.secrets) {
        throw new Error('Invalid payload structure');
      }

      // Sanitize and save backup
      const backupFile = path.join(STORAGE_DIR, `backup-${Date.now()}.json`);

      fs.writeFileSync(backupFile, body);

      logSimple.success(`Backup saved to: ${backupFile}`);
      logSimple.info(`Backup size: ${Buffer.byteLength(body, 'utf8')} bytes`);

      // Cleanup old backups (keep last 10)
      cleanupOldBackups(logSimple);

      // Respond with success
      res.writeHead(200, { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' });
      res.end(JSON.stringify({
        success: true,
        message: 'Credentials backup stored successfully',
        timestamp: data.timestamp,
        backupFile: backupFile
      }));
    } catch (error) {
      logSimple.error(`Backup failed: ${error.message}`);
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        success: false,
        error: 'Invalid backup payload',
        message: error.message
      }));
    }
  });
}

// Cleanup old backups
function cleanupOldBackups(logger) {
  const backupFiles = fs.readdirSync(STORAGE_DIR)
    .filter(f => f.startsWith('backup-') && f.endsWith('.json'))
    .map(f => ({
      name: f,
      path: path.join(STORAGE_DIR, f),
      mtime: fs.statSync(path.join(STORAGE_DIR, f)).mtime.getTime()
    }))
    .sort((a, b) => b.mtime - a.mtime);

  // Keep top 10 backups, delete the rest
  if (backupFiles.length > 10) {
    for (let i = 10; i < backupFiles.length; i++) {
      try {
        fs.unlinkSync(backupFiles[i].path);
        logger.info(`Deleted old backup: ${backupFiles[i].name}`);
      } catch (err) {
        logger.warning(`Failed to delete backup: ${back${i}` + backupFiles[i].name}`);
      }
    }
  }
}

// Start the server
function main() {
  ensureStorageDir();

  const server = http.createServer(handler);

  server.listen(PORT, () => {
    log.section('DR Backup Server Started');
    log.success(`Server listening on: http://localhost:${PORT}`);
    log.info(`Backup storage directory: ${STORAGE_DIR}`);
    log.info('');
    log.info('Available endpoints:');
    log.info(`  POST http://localhost:${PORT}/api/dr-backup - Store credentials backup`);
    log.info(`  GET  http://localhost:${PORT}/health - Server health check`);
    log.info('');
    log.info('Note: In production, secure this endpoint with authentication and HTTPS');
  });

  server.on('error', (error) => {
    if (error.code === 'EADDRINUSE') {
      log.error(`Port ${PORT} is already in use`);
      process.exit(1);
    } else {
      log.error(`Server error: ${error.message}`);
      process.exit(1);
    }
  });
}

main();

