#!/usr/bin/env node

/**
 * DR Backup Server - Simple Implementation
 * Receives credentials backup POST requests and saves them
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = process.env.PORT || 9999;

// ANSI colors
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
};

const log = {
  info: (msg) => console.log(`${colors.blue}[INFO]${colors.reset} ${msg}`),
  success: (msg) => console.log(`${colors.green}[✓]${colors.reset} ${msg}`),
  error: (msg) => console.log(`${colors.red}[✗]${colors.reset} ${msg}`),
};

function ensureDir() {
  const dir = path.join(process.cwd(), '.dr-backups');
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
    log.success(`Created backup directory: ${dir}`);
  }
  return dir;
}

function handler(req, res) {
  console.time('request');

  if (req.method === 'OPTIONS') {
    res.writeHead(204, {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
      'Content-Length': '0',
    });
    console.timeEnd('request');
    res.end();
    return;
  }

  if (req.method !== 'POST') {
    res.writeHead(405, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: 'Method not allowed' }));
    return;
  }

  let body = '';

  req.on('data', chunk => body += chunk);
  req.on('end', () => {
    try {
      const data = JSON.parse(body);
      const backupFile = path.join(ensureDir(), `backup-${Date.now()}.json`);

      fs.writeFileSync(backupFile, body);

      console.timeEnd('request');
      console.log(`[${new Date().toISOString()}] Backup saved: ${backupFile}`);
      console.log(`[${new Date().toISOString()}] Size: ${Buffer.byteLength(body, 'utf8')} bytes`);

      res.writeHead(200, { 'content-type': 'application/json', 'access-control-allow-origin': '*' });
      res.end(JSON.stringify({
        success: true,
        backupFile,
        timestamp: data.timestamp
      }));
    } catch (e) {
      console.error(e);
      res.writeHead(400, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ error: e.message }));
    }
  });
}

const server = http.createServer(handler);

server.listen(PORT, () => {
  log.success(`DR Backup Server listening on http://localhost:${PORT}`);
  log.info('Available endpoint: POST /api/dr-backup');
  log.info('Press Ctrl+C to stop');
});

server.on('error', e => {
  log.error(`Server error: ${e.message}`);
  process.exit(1);
});

