// Simple application for agent to work on
// Enhanced with security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const useragent = require('express-useragent');
const xss = require('xss-clean');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// Helmet provides security headers (CSP, XSS protection, etc.)
app.use(helmet());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes except /health
app.use('/api', limiter);
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Trust proxy for rate limiting behind load balancer
app.set('trust proxy', 1);

// Help express handle larger request bodies
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Enable CORS with specific origin(s)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400,
};
app.use(cors(corsOptions));

// XSS Clean sanitizes user input
app.use(xss());

// User agent detection (optional: for logging)
app.use(useragent.express());

// ===== VULNERABLE-API ENDPOINTS =====

// Warning: These endpoints lack proper validation and could be exploitable
// Buy implementing validation as shown in the /validate-endpoint

app.get('/users', (req, res) => {
  try {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    console.error('Error in /users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ===== VALIDATED-EXAMPLE ENDPOINT =====

app.post('/validate-endpoint', [
  // Input validation using express-validator
  body('email')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(), // Sanitizes normalization

  body('password')
    .isStrongPassword({
      minLength: 8,
      minLowercase: 1,
      minUppercase: 1,
      minNumbers: 1,
      minSymbols: 1,
    })
    .withMessage('Password must be at least 8 characters with upper/lower/numbers/symbols'),

  body('age')
    .isInt({ min: 13, max: 120 })
    .withMessage('Age must be between 13 and 120'),

  // Sanitize other inputs
  body('name')
    .trim()
    .isLength({ min: 1, max: 50 })
    .escape() // XSS protection
    .withMessage('Name is required (1-50 characters)')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({ field: err.path, message: err.msg }))
    });
  }

  try {
    const validatedData = req.body;

    // Additional validation/sanitization if needed
    // Example: Hash passwords before storing
    // const hashedPassword = await bcrypt.hash(validatedData.password, 10);

    res.status(200).json({
      message: 'Validation successful',
      data: {
        email: validatedData.email,
        name: validatedData.name,
        age: validatedData.age,
      }
    });
  } catch (error) {
    console.error('Error in /validate-endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ===== GLOBAL ERROR HANDLER =====

app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Handle resource not found
  if (err.status === 404) {
    return res.status(404).json({ error: 'Resource not found' });
  }

  // Handle validation errors
  if (err.name === 'ValidationError') {
    return res.status(400).json({ error: 'Validation failed' });
  }

  // Default error response
  res.status(err.status || 500).json({
    error: 'Internal server error',
    // Only expose in development
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ===== UNHANDLED EXCEPTION HANDLING =====

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Consider graceful shutdown or proper error reporting
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Consider graceful shutdown
  process.exit(1);
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);
  app.close(() => {
    console.log('Express server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcing shutdown');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// ===== START SERVER =====

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server securely running on port ${PORT}`);
  console.log(`📍 Health check: http://localhost:${PORT}/health`);
  console.log(`📝 Example validated endpoint: POST http://localhost:${PORT}/validate-endpoint`);
});

module.exports = app;

