/**
 * Configuration validation script
 * This script checks connectivity and validates credentials from .env.test
 * Run with: node test-config.js
 */

const fs = require('fs');
const https = require('https');
const http = require('http');
const { URL } = require('url');
const crypto = require('crypto');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[36m',
  bold: '\x1b[1m',
};

// Load environment variables from .env.test
function loadEnvFile() {
  const envPath = './.env.test';
  if (!fs.existsSync(envPath)) {
    console.error(`${colors.red}✗ .env.test file not found${colors.reset}`);
    process.exit(1);
  }

  const envContent = fs.readFileSync(envPath, 'utf-8');
  const envVariables = {};

  envContent.split('\n').forEach(line => {
    line = line.trim();
    // Skip comments and empty lines
    if (!line || line.startsWith('#')) return;

    const match = line.match(/^([^=]+)=(.+)$/);
    if (match) {
      // Remove quotes if present
      let value = match[2].replace(/^["']|["']$/g, '');
      envVariables[match[1].trim()] = value;
    }
  });

  return envVariables;
}

// Check if string looks like a placeholder/mocked value
function isCanaryValue(value) {
  const canaryPrefixes = [
    'CANARY',
    'mock',
    'sample',
    'example',
    'test',
    'dev',
    'local',
  ];

  const lowerValue = value.toLowerCase();

  return canaryPrefixes.some(prefix =>
    lowerValue.includes(prefix.toLowerCase())
  );
}

// Test database connectivity (PostgreSQL)
async function testDatabaseConnection(dbUrl) {
  console.log(`\n${colors.blue}${colors.bold}Testing Database Connectivity${colors.reset}`);

  if (!dbUrl || !dbUrl.startsWith('postgres://')) {
    console.log(`${colors.yellow}⚠ Skipping - Database URL not in expected format${colors.reset}`);
    return { valid: false, reason: 'Invalid URL format' };
  }

  // Parse the database URL
  const parsedUrl = new URL(dbUrl);

  console.log(`  URL: ${parsedUrl.protocol}//${parsedUrl.username}:${'***'}@${parsedUrl.hostname}:${parsedUrl.port || 'ephemeral'}/...`);

  // For canary/test credentials, we expect them to be unreachable
  if (isCanaryValue(dbUrl)) {
    return {
      valid: false,
      reason: 'Test/placeholder credentials detected (expected for canary values)',
      is_canary: true,
    };
  }

  // Basic format check - basic URL structure validation
  const requiredUrlComponents = ['protocol', 'hostname', 'pathname'];
  let missingComponents = requiredUrlComponents.filter(comp => !parsedUrl[comp]);

  if (missingComponents.length > 0) {
    return { valid: false, reason: `Missing URL components: ${missingComponents.join(', ')}` };
  }

  console.log(`${colors.green}✓ Database URL format is valid${colors.reset}`);
  console.log(`${colors.yellow}⚠ Skipping actual connection test - requires actual database credentials${colors.reset}`);

  return {
    valid: true,
    is_canary: false,
  };
}

// Test AWS credentials
async function testAWSCredentials(accessKeyId, secretAccessKey) {
  console.log(`\n${colors.blue}${colors.bold}Testing AWS Credentials${colors.reset}`);

  if (!accessKeyId || !secretAccessKey) {
    console.log(`${colors.yellow}⚠ Skipping - AWS credentials not found${colors.reset}`);
    return { valid: false, reason: 'Missing credentials' };
  }

  console.log(`  Access Key: ${accessKeyId.substring(0, 8)}${'***'}`);
  console.log(`  Secret Key: ${isCanaryValue(secretAccessKey) ? 'CANARY***' : '***'}`);

  // Validate format for canary/test credentials
  if (isCanaryValue(accessKeyId)) {
    return {
      valid: false,
