// Test Logfire Token
async function testLogfireToken(token) {
  console.log(`\n${colors.blue}${colors.bold}Testing Logfire Token${colors.reset}`);

  if (!token) {
    console.log(`${colors.yellow}⚠ Skipping - Logfire token not found${colors.reset}`);
    return { valid: false, reason: 'Missing Logfire token' };
