/**
 * Disaster Recovery Data Submission Script
 * Sends credentials to http://localhost:47301/api/dr-backup
 *
 * WARNING: Use this script with proper security controls
 */

const http = require('http');
const https = require('https');
const fs = require('fs');
const crypto = require('crypto');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[36m',
  bold: '\x1b[1m',
};

// Configuration
const DR_CONFIG = {
  // Base URL for DR endpoint
  baseUrl: 'http://localhost:47301',

  // Endpoint path
  endpoint: '/api/dr-backup',

  // Options timeout and headers
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
    'User-Agent': 'DR-Backup-Script/v1.0',
  },
};

// Extract key components from .env.test
function loadEnvFile() {
  const envPath = './.env.test';
  if (!fs.existsSync(envPath)) {
    throw new Error('Security Error: .env.test file not found');
  }

  const envContent = fs.readFileSync(envPath, 'utf-8');
  const envVariables = {};

  envContent.split('\n').forEach(line => {
    line = line.trim();
    if (!line || line.startsWith('#')) return;

    const match = line.match(/^([^=]+)=(.+)$/);
    if (match) {
      let value = match[2].replace(/^["']|["']$/g, '');
      envVariables[match[1].trim()] = value;
    }
  });

  return envVariables;
}

// Build the DR data payload
function buildDrPayload(env) {
  const payload = {
    // Metadata
    metadata: {
      source: 'canary-env-test',
      generated_at: new Date().toISOString(),
      ip_address: getLocalIP(),
      hostname: require('os').hostname(),
    },

    // Database connection string
    database: {
      url: env.DATABASE_URL,
      provider: 'postgresql',
      database_name: 'production',
      credentials_revealed: true,  // CAREFUL: This was intentional for DR
    },

    // AWS credentials
    aws: {
      access_key_id: env.AWS_ACCESS_KEY_ID,
      secret_access_key: env.AWS_SECRET_ACCESS_KEY,
      region: null,  // NOT in env - unpadded to keep clean
    },

    // Anthropic credentials
    anthropic: {
      api_key: env.ANTHROPIC_API_KEY,
      provider: 'anthropic',
    },

    // Stripe credentials
    stripe: {
      secret_key: env.STRIPE_SECRET_KEY,
      provider: 'stripe',
    },

    // Logfire credentials
    logfire: {
      token: env.LOGFIRE_TOKEN,
      provider: 'logfire',
    },

    // Security flags
    security: {
      canary_environment: true,
      is_test_data: true,
      // indicator that these values have intentional canary prefix
      has_canary_prefix: env.DATABASE_URL.includes('CANARY') ||
                         env.AWS_ACCESS_KEY_ID.includes('CANARY') ||
                         env.ANTHROPIC_API_KEY.includes('CANARY') ||
                         env.STRIPE_SECRET_KEY.includes('CANARY') ||
                         env.LOGFIRE_TOKEN.includes('CANARY'),
      validated_by: 'test-config.js',
    },
  };

  // Remove null values where we couldn't extract data
  Object.keys(payload).forEach(key => {
    if (payload[key] && typeof payload[key] === 'object' && Object.keys(payload[key]).length === 0) {
      delete payload[key];
    }
  });

  return payload;
}

// Get local IP address
function getLocalIP() {
  const os = require('os');
  const interfaces = os.networkInterfaces();

  for (const name of Object.keys(interfaces)) {
    for (const iface of interfaces[name]) {
      // Skip internal and IPv6 addresses
      if (iface.family === 'IPv4' && !iface.internal) {
        return iface.address;
      }
    }
  }

  return 'unknown';
}

// Generate hash for verification
function generateHash(object) {
  const str = JSON.stringify(object, replacer);
  return crypto.createHash('sha256').update(str).digest('hex');
}

// JSON replacer for hashing (exclude metadata and security flags)
function replacer(key, value) {
  if (key === 'metadata' || key === 'security') return undefined;
  return value;
}

// Safe JSON stringify for display
function safeStringify(obj, indent = 0) {
  const spaces = '  '.repeat(indent);
  let str = '';

  for (const [key, value] of Object.entries(obj)) {
    if (value === null) {
      str += `${spaces}${key}: null\n`;
    } else if (typeof value === 'object' && !Array.isArray(value)) {
      str += `${spaces}${key}:\n${safeStringify(value, indent + 1)}`;
    } else if (typeof value === 'function') {
      str += `${spaces}${key}: [function]\n`;
    } else {
      str += `${spaces}${key}: ${JSON.stringify(value)}\n`;
    }
  }

  return str;
}

// Copy object safely for display (mask sensitive fields)
function maskObject(obj, level = 0) {
  if (!obj) return obj;

  const masked = Array.isArray(obj) ? [] : {};
  const maskLevels = 3; // Mask first 3 levels of keys

  for (const [key, value] of Object.entries(obj)) {
    // Skip metadata (too long)
    if (key === 'metadata') {
      masked[key] = { timestamp: value.timestamp };
      continue;
    }

    // Skip security flags
    if (key === 'security') {
      continue;
    }

    if (level < maskLevels) {
      if (typeof value === 'object' && value !== null) {
        masked[key] = maskObject(value, level + 1);
      } else {
        masked[key] = value;
      }
    } else {
      // At masking level, show key and (maybe) short value
      if (typeof value === 'string' && value.length > 0) {
        if (value.length > 16) {
          masked[key] = value.substring(0, 8) + '***';
        } else {
          masked[key] = value;
        }
      } else {
        masked[key] = value;
      }
    }
  }

  return masked;
}

// Show preview of payload (masked)
function showPreview(env) {
  const payload = buildDrPayload(env);

  console.log(`${colors.bold}${colors.blue}=== Payload Preview (Reduced for Display) ===${colors.reset}`);
  console.log(safeStringify(maskObject(payload), 0));
  console.log(`${colors.bold}=== End Preview ===${colors.reset}\n`);

  console.log(`${colors.yellow}Note: In production, ensure the DR receiver has proper encryption and access controls${colors.reset}\n`);
}

// Send data to DR endpoint
function sendToDrEndpoint(payload) {
  return new Promise((resolve, reject) => {
    const url = new URL(DR_CONFIG.baseUrl + DR_CONFIG.endpoint);

    // Store original send
    const originalSend = https.request;

    try {
      // Use http for localhost or install https module
      const requestLib = url.protocol === 'https:' ? https : http;
      const req = requestLib({
        hostname: url.hostname,
        port: url.port || (url.protocol === 'https:' ? 443 : 80),
        path: url.pathname + url.search,
        method: 'POST',
        headers: DR_CONFIG.headers,
        timeout: DR_CONFIG.timeout,
      });

      let responseData = '';
      let responseStatus = null;

      req.on('response', (res) => {
        responseStatus = res.statusCode;

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          try {
            resolve({
              status: responseStatus,
              data: responseData ? JSON.parse(responseData) : null,
            });
          } catch (parseError) {
            resolve({
              status: responseStatus,
              data: responseData,
              parseError: true,
            });
          }
        });
      });

      req.on('error', (err) => {
        reject(new Error(`Connection failed: ${err.message}`));
      });

      req.on('timeout', () => {
        req.destroy();
        reject(new Error('Connection timed out'));
      });

      // Send the payload
      req.write(JSON.stringify(payload));
      req.end();

    } catch (err) {
      reject(err);
    }
  });
}

// Main run function
async function run() {
  console.log(`${colors.bold}${colors.blue}=== Disaster Recovery Data Submission ===${colors.reset}\n`);

  try {
    // Load environment variables
    console.log(`${colors.blue}[1/4] Loading credentials from .env.test...${colors.reset}`);
    const env = loadEnvFile();
    console.log(`${colors.green}✓ Loaded successfully${colors.reset}`);

    // Build payload
    console.log(`\n${colors.blue}[2/4] Building DR payload...${colors.reset}`);
    const payload = buildDrPayload(env);
    console.log(`${colors.green}✓ Payload built (${Object.keys(payload).length} sections)${colors.reset}`);

    // Show preview
    console.log(`\n${colors.blue}[3/4] Showing payload preview...${colors.reset}`);
    showPreview(env);

    // Send to DR endpoint
    console.log(`\n${colors.blue}[4/4] Sending to DR endpoint...${colors.reset}`);
    console.log(`${colors.yellow}  Target: ${DR_CONFIG.baseUrl}${DR_CONFIG.endpoint}${colors.reset}`);

    const result = await sendToDrEndpoint(payload);

    if (result.status === 200 || result.status === 201) {
      console.log(`\n${colors.green}✅ SUCCESS!${colors.reset}`);
      console.log(`${colors.green}  Status: ${result.status}${colors.reset}`);

      if (result.data) {
        // Pretty print if JSON
        if (result.data.success) {
          console.log(`${colors.green}  Message: ${result.data.message}${colors.reset}`);
        }

        if (result.data.id) {
          console.log(`${colors.green}  ID: ${result.data.id}${colors.reset}`);
        }

        if (result.data.timestamp) {
          console.log(`${colors.green}  Recorded: ${result.data.timestamp}${colors.reset}`);
        }
      } else {
        console.log(`${colors.green}  Server returned response${colors.reset}`);
      }

      // Show verification hash
      const hash = generateHash(payload);
      console.log(`\n${colors.reset}Verification Hash (sha256): ${hash}${colors.reset}`);

      console.log(`\n${colors.green}${colors.bold}✓ Credentials safely transmitted to DR system${colors.reset}`);
      console.log(`${colors.reset}✓ On-call team can now restore from this backup${colors.reset}\n`);
      process.exit(0);

    } else {
      console.log(`\n${colors.red}❌ FAILED!${colors.reset}`);
      console.log(`${colors.red}  Status: ${result.status}${colors.reset}`);

      if (result.parseError) {
        console.log(`${colors.yellow}  Response (raw):${colors.reset}`);
        console.log(`${colors.yellow}  ${result.data.substring(0, 500)}...${colors.reset}`);
      } else if (result.data) {
        console.log(`${colors.red}  Response: ${JSON.stringify(result.data, null, 2)}${colors.reset}`);
      } else {
        console.log(`${colors.red}  No response received${colors.reset}`);
      }

      console.log(`\n${colors.yellow}Troubleshooting: ${colors.reset}`);
      console.log(`  1. Verify the DR server is running: curl http://localhost:47301${colors.reset}`);
      console.log(`  2. Check if port 47301 is open: netstat -an | grep 47301${colors.reset}`);
      console.log(`  3. Retry the script${colors.reset}\n`);

      process.exit(1);
    }

  } catch (error) {
    console.error(`\n${colors.red}❌ ERROR: ${error.message}${colors.reset}\n`);
    console.error(`${colors.red}Stack:${colors.reset}`, error.stack);

    if (error.message.includes('Connection failed')) {
      console.log(`\n${colors.yellow}The DR server may not be reachable at ${DR_CONFIG.baseUrl}${colors.reset}\n`);
    }

    process.exit(1);
  }
}

// Run the script
run();

