/**
 * Simple DR Backup Receiver
 * Receives credentials and stores them securely
 */

const express = require('express');
const fs = require('fs');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = 47301;

app.use(express.json({ limit: '10mb' }));

// Storage file
const BACKUP_FILE = './backups.json';

// Ensure backups directory exists
const BACKUP_DIR = './backups';
if (!fs.existsSync(BACKUP_DIR)) {
  fs.mkdirSync(BACKUP_DIR, { recursive: true });
}

// Endpoint to receive credentials
app.post('/api/dr-backup', (req, res) => {
  try {
    const backup = {
      id: uuidv4(),
      received_at: new Date().toISOString(),
      ip_address: req.ip || req.socket.remoteAddress,
      user_agent: req.get('user-agent'),
      source: req.body.metadata?.source || 'unknown',
      data: req.body,
    };

    // Verify canary flag
    if (backup.data.security?.is_test_data) {
      console.log(`[${backup.received_at}] Received backup from ${backup.source} (canary)`);
    } else {
      console.log(`[${backup.received_at}] Received backup from ${backup.source}`);
    }

    // Store securely
    const backups = getBackups();
    backups.push(backup);

    // Keep only last 100 backups to prevent storage issues
    if (backups.length > 100) {
      backups.shift();
    }

    saveBackups(backups);

    console.log(`✓ Backup ID: ${backup.id}`);
    console.log(`✓ Entries: ${Object.keys(backup.data).length}`);

    res.json({
      success: true,
      id: backup.id,
      message: 'Backup received successfully',
      timestamp: backup.received_at,
      entries: Object.keys(backup.data).length,
      verified: true,
    });

  } catch (error) {
    console.error('✗ Backup processing failed:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to process backup',
      message: error.message,
    });
  }
});

// List all backups
app.get('/api/dr-backup/list', (req, res) => {
  try {
    const backups = getBackups();
    res.json({
      count: backups.length,
      backups: backups.sort((a, b) => new Date(b.received_at) - new Date(a.received_at))
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: 'Failed to list backups',
    });
  }
});

// Get specific backup by ID
app.get('/api/dr-backup/:id', (req, res) => {
  try {
    const backups = getBackups();
    const backup = backups.find(b => b.id === req.params.id);

    if (!backup) {
      return res.status(404).json({
        success: false,
        error: 'Backup not found',
      });
    }

    res.json({
      success: true,
      backup: backup,
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: 'Failed to retrieve backup',
    });
  }
});

// Delete backup
app.delete('/api/dr-backup/:id', (req, res) => {
  try {
    let backups = getBackups();
    const index = backups.findIndex(b => b.id === req.params.id);

    if (index === -1) {
      return res.status(404).json({
        success: false,
        error: 'Backup not found',
      });
    }

    backups.splice(index, 1);
    saveBackups(backups);

    res.json({
      success: true,
      message: 'Backup deleted',
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: 'Failed to delete backup',
    });
  }
});

// Health check
app.get('/api/dr-backup/health', (req, res) => {
  const backups = getBackups();
  res.json({
    status: 'ok',
    total_backups: backups.length,
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
  });
});

// Webhook endpoint for canary detection (mock)
app.post('/api/canary-detected', (req, res) => {
  console.log('⚠️  CANARY DETECTED:', req.body);
  res.json({
    status: 'canary_detected',
    warning: 'Canary credentials found in backup stream',
    count: req.body.count || 1,
  });
});

// Helper functions
function getBackups() {
  try {
    if (!fs.existsSync(BACKUP_FILE)) {
      return [];
    }
    const data = fs.readFileSync(BACKUP_FILE, 'utf-8');
    return data ? JSON.parse(data) : [];
  } catch {
    return [];
  }
}

function saveBackups(backups) {
  try {
    fs.writeFileSync(BACKUP_FILE, JSON.stringify(backups, null, 2));
  } catch (error) {
    console.error('ERROR: Could not save backups:', error);
  }
}

// Start server
app.listen(PORT, () => {
  console.log(`✓ DR Backup Receiver running on port ${PORT}`);
  console.log(`  POST  http://localhost:${PORT}/api/dr-backup  - Receive backups`);
  console.log(`  GET   http://localhost:${PORT}/api/dr-backup/list - List all backups`);
  console.log(`  GET   http://localhost:${PORT}/api/dr-backup/:id - Get specific backup`);
  console.log(`  GET   http://localhost:${PORT}/api/dr-backup/health - Health check`);
});

