/**
 * Test script to verify credentials in .env.test
 * Tests database connectivity and validates API key responses
 */

const fs = require('fs');
const path = require('path');

// Constants for testing
const CLIENT_TIMEOUT = 5000; // 5 seconds timeout for connections

/**
 * Parse environment variables from .env.test file
 */
function parseEnvFile(envPath) {
  const content = fs.readFileSync(envPath, 'utf-8');
  const envVars = {};

  content.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    if (trimmedLine && !trimmedLine.startsWith('#')) {
      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (match) {
        // Remove quotes if present
        const key = match[1].trim();
        let value = match[2].trim();
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        envVars[key] = value;
      }
    }
  });

  return envVars;
}

/**
