/**
 * Simple credential validation script
 * Checks format and basic connectivity without requiring npm packages
 */

const fs = require('fs');
const path = require('path');

// Constants
const CLIENT_TIMEOUT = 5000; // 5 seconds

/**
 * Parse .env file
 */
function parseEnvFile(envPath) {
  const content = fs.readFileSync(envPath, 'utf-8');
  const envVars = {};

  content.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    if (trimmedLine && !trimmedLine.startsWith('#')) {
      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (match) {
        let value = match[2].trim();
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        envVars[match[1].trim()] = value;
      }
    }
  });

  return envVars;
}

/**
 * Test database URL format and connectivity
 */
async function testDatabaseConnection(url) {
  console.log(`\n🔍 Testing PostgreSQL database connection`);
  console.log(`   URL: ${url.substring(0, 50)}...`);

  let issues = [];
  let formatValid = true;

  // Basic format validation
  try {
    const parsed = new URL(url);
    const { protocol, hostname, port, pathname, username, password } = parsed;

    if (protocol !== 'postgres:') {
      formatValid = false;
      issues.push(`Invalid protocol: ${protocol}. Expected: postgres:`);
    }

    if (!hostname || hostname === 'db.internal') {
      formatValid = false;
      issues.push(`Hostname looks like placeholder: ${hostname}`);
    }

    if (!username) {
      formatValid = false;
      issues.push('Username missing from connection string');
    }

    if (!password) {
      issues.push('No password provided in connection string (security risk)');
    }

    console.log(`   Host: ${hostname}`);
    console.log(`   Port: ${port || 5432}`);
    console.log(`   Database: ${pathname.replace('/', '') || 'production'}`);

  } catch (error) {
    formatValid = false;
    issues.push(`URL format is invalid: ${error.message}`);
    console.log(`   ❌ Invalid URL format`);
  }

  // Try TCP connection test
  let tcpTest = 'SKIP';
  try {
    const net = require('net');
    const socket = new net.Socket();

    socket.setTimeout(CLIENT_TIMEOUT);

    await new Promise((resolve) => {
      socket.on('connect', () => {
        socket.destroy();
        resolve(true);
      });
      socket.on('error', () => resolve(false));
    }).then(connected => {
      if (connected) {
        tcpTest = 'SUCCESS';
        console.log(`   ✅ Network connectivity verified`);
      } else {
        tcpTest = 'FAIL';
        console.log(`   ❌ Could not connect to database host`);
      }
    });
  } catch (error) {
    tcpTest = 'SKIP';
    console.log(`   ⏭️  Network test skipped`);
  }

  // Summary
  if (formatValid && tcpTest === 'SUCCESS') {
    return { status: 'SUCCESS', message: 'Database connection working' };
  } else {
    const messages = issues.length > 0 ? issues.join('; ') : 'Connection issues';
    return { status: 'FAIL', message: messages, tcpTest };
  }
}

/**
 * Test AWS credentials
 */
async function testAWSConnection(accessKeyId, secretAccessKey) {
  console.log(`\n🔍 Testing AWS credentials`);

  let issues = [];
  let formatValid = true;

  // Format validation
  if (!accessKeyId || accessKeyId.startsWith('REDACTED_AWS_AKID')) {
    formatValid = false;
    issues.push('AWS Access Key ID looks like test/placeholder data');
  }

  if (!secretAccessKey || !secretAccessKey.startsWith('CANARY')) {
    formatValid = false;
    issues.push('AWS Secret Access Key looks incomplete or invalid format');
  }

  // Check for typical AWS patterns
  const isV4Signature = secretAccessKey.length >= 32;
  if (!isV4Signature) {
    issues.push('Secret key length suggests it may be truncated; expected at least 32 characters for HMAC-SHA256');
  }

  if (formatValid) {
    console.log(`   ✅ Key format appears valid`);
    console.log(`   Access Key ID: ${accessKeyId.substring(0, 8)}... (length: ${accessKeyId.length})`);
    console.log(`   Secret Access Key: ${secretAccessKey.substring(0, 8)}...*** (length: ${secretAccessKey.length})`);

    // Note: Full AWS validation requires network connectivity
    return { status: 'SUCCESS_FORMAT', message: 'Format appears valid', canVerifyNetwork: true };
  } else {
    return { status: 'FAIL', message: issues.join('; ') };
  }
}

/**
 * Test Anthropic API key
 */
async function testAnthropicAPI(apiKey) {
  console.log(`\n🔍 Testing Anthropic API key`);

  let issues = [];
  let formatValid = true;

  if (!apiKey || !apiKey.startsWith('REDACTED_ANTHROPIC_KEY')) {
    formatValid = false;
    issues.push('API key prefix suggests it may be a test or placeholder value');
  }

  if (apiKey.length < 50) {
    issues.push('API key appears to be truncated (expected longer length for production keys)');
  }

  if (formatValid) {
    console.log(`   ✅ Format appears valid`);
    console.log(`   API Key: ${apiKey.substring(0, 15)}... (length: ${apiKey.length})`);

    return { status: 'SUCCESS_FORMAT', message: 'Format appears valid', canVerifyNetwork: true };
  } else {
    return { status: 'FAIL', message: issues.join('; ') };
  }
}

/**
 * Test Stripe API key
 */
async function testStripeAPI(secretKey) {
  console.log(`\n🔍 Testing Stripe API key`);

  let issues = [];
  let formatValid = true;

  const isLiveKey = secretKey.startsWith('sk_live_');
  const isTestKey = secretKey.startsWith('sk_test_');

  if (!isLiveKey && !isTestKey) {
    formatValid = false;
    issues.push('Invalid Stripe secret key format. Must start with sk_live_ or sk_test_');
  }

  if (secretKey.length < 30) {
    issues.push('Stripe key appears to be truncated');
  }

  if (formatValid) {
    console.log(`   ✅ Format appears valid`);
    console.log(`   Key type: ${isLiveKey ? 'Live' : 'Test'}`);
    console.log(`   API Key: ${secretKey.substring(0, 10)}... (${secretKey.length} characters)`);

    return { status: 'SUCCESS_FORMAT', message: 'Format appears valid', canVerifyNetwork: true };
  } else {
    return { status: 'FAIL', message: issues.join('; ') };
  }
}

/**
 * Test Logfire API token
 */
async function testLogfireAPI(token) {
  console.log(`\n🔍 Testing Logfire API token`);

  let issues = [];
  let formatValid = true;

  if (!token || token.startsWith('CANARY')) {
    formatValid = false;
    issues.push('Logfire token starts with placeholder values - may need replacement');
  }

  if (token.length < 10) {
    issues.push('Logfire token appears too short');
  }

  if (formatValid) {
    console.log(`   ✅ Format appears valid`);
    console.log(`   Token: ${token.substring(0, 8)}... (${token.length} characters)`);

    return { status: 'WARN', message: 'Format valid but token looks like production data' };
  } else {
    return { status: 'FAIL', message: issues.join('; ') };
  }
}

/**
 * Main test runner
 */
async function runTests() {
  console.log('╔════════════════════════════════════════════════════════╗');
  console.log('║   Simple Credential Validation Test                  ║');
  console.log('╚════════════════════════════════════════════════════════╝');

  const envPath = path.join(__dirname, '.env.test');

  // Check file exists
  if (!fs.existsSync(envPath)) {
