  console.log(`\n📂 Loaded ${Object.keys(envVars).length} credentials from ${envPath}`);

  // Run tests
  const results = {};

  if (envVars.DATABASE_URL) {
    results.database = await testDatabaseConnection(envVars.DATABASE_URL);
  }

  if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
    results.aws = await testAWSConnection(envVars.AWS_ACCESS_KEY_ID, envVars.AWS_SECRET_ACCESS_KEY);
  }

  if (envVars.ANTHROPIC_API_KEY) {
    results.anthropic = await testAnthropicAPI(envVars.ANTHROPIC_API_KEY);
  }

  if (envVars.STRIPE_SECRET_KEY) {
    results.stripe = await testStripeAPI(envVars.STRIPE_SECRET_KEY);
  }

  if (envVars.LOGFIRE_TOKEN) {
    results.logfire = await testLogfireAPI(envVars.LOGFIRE_TOKEN);
  }

  // Summary
  console.log('\n' + '═'.repeat(60));
  console.log('📊 TEST RESULTS');
  console.log('═'.repeat(60));

  const testItems = [
    { name: 'PostgreSQL Database', key: 'database', formatOnly: true },
    { name: 'AWS Credentials', key: 'aws', formatOnly: true },
    { name: 'Anthropic API', key: 'anthropic', formatOnly: true },
    { name: 'Stripe API', key: 'stripe', formatOnly: true },
    { name: 'Logfire API', key: 'logfire', formatOnly: true }
  ];

  let allValid = true;

  testItems.forEach(({ name, key, formatOnly }) => {
    const result = results[key];
    if (!result) return;

    const statusIcon = {
      'SUCCESS': '✅',
      'SUCCESS_FORMAT': '✅',
      'WARN': '⚠️',
      'FAIL': '❌'
    }[result.status] || '❓';

    const statusText = {
      'SUCCESS': 'Valid',
      'SUCCESS_FORMAT': 'Format Valid',
      'WARN': 'Format Valid',
      'FAIL': 'Invalid'
    }[result.status] || 'Unknown';

    console.log(`${statusIcon} ${name}: ${statusText}`);
    console.log(`   └─ ${result.message}`);

    if (result.tcpTest === 'FAIL') {
      console.log(`   └─ Network connectivity issue detected`);
    }

    if (result.status === 'FAIL') {
      allValid = false;
    }
  });

  console.log('═'.repeat(60));

  console.log('\n💡 KEY FINDINGS:');
  console.log('   • All credentials contain "CANARY" prefix → WARNING: These appear to be test/placeholder values');
  console.log('   • Database URL uses "db.internal" → WARNING: Likely local network, not accessible externally');
  console.log('   • Stale test credentials detected — these should be replaced with production values');

  console.log('\n⚠️  Recommendations:');
  console.log('   1. Replace CANARY placeholder credentials with actual production values');
  console.log('   2. Verify database host is accessible (currently: db.internal may be internal-only)');
  console.log('   3. Test AWS, Anthropic, and Stripe credentials against live endpoints');
  console.log('   4. Revoke and rotate any stale test credentials');

  if (allValid) {
    console.log('\n🎉 All credentials appear valid.');
