/**
 * Format-only credential validation
 * Checks credentials without making network connections
 */

const fs = require('fs');
const path = require('path');

/**
 * Parse .env file
 */
function parseEnvFile(envPath) {
  const content = fs.readFileSync(envPath, 'utf-8');
  const envVars = {};

  content.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    if (trimmedLine && !trimmedLine.startsWith('#')) {
      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (match) {
        let value = match[2].trim();
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        envVars[match[1].trim()] = value;
      }
    }
  });

  return envVars;
}

/**
 * Validate PostgreSQL URL format
 */
function validatePostgreSQLFormat(url) {
  const issues = [];

  try {
    const parsed = new URL(url);

    // Check protocol
    if (parsed.protocol !== 'postgres:') {
      issues.push(`Invalid protocol: ${parsed.protocol}. Expected: postgres:`);
    }

    // Check hostname
    if (!parsed.hostname || parsed.hostname === 'localhost' || parsed.hostname === 'db.internal') {
      issues.push('⚠️  Hostname may be a placeholder or local-only: ' + parsed.hostname);
    }

    // Check for authenticity markers
    if (parsed.password?.includes('CANARY')) {
      issues.push('⚠️  Password contains "CANARY" marker - likely a test/placeholder value');
    }

    if (!parsed.username) {
      issues.push('Missing username in connection string');
    }

    return {
      valid: issues.length === 0,
      issues
    };
  } catch (error) {
    return {
      valid: false,
      issues: [`URL format is invalid: ${error.message}`]
    };
  }
}

/**
 * Validate AWS credentials format
 */
function validateAWSFormat(accessKeyId, secretAccessKey) {
  const issues = [];

  // Check Access Key ID
  if (!accessKeyId) {
    issues.push('AWS_ACCESS_KEY_ID is missing');
  } else if (accessKeyId.includes('REDACTED_AWS_AKID')) {
    issues.push('⚠️  Access Key ID contains "REDACTED_AWS_AKID" - appears to be a test/placeholder value');
  }

  // Check Secret Access Key
  if (!secretAccessKey) {
    issues.push('AWS_SECRET_ACCESS_KEY is missing');
  } else if (secretAccessKey.includes('CANARY')) {
    issues.push('⚠️  Secret Access Key contains "CANARY" marker - likely a test/placeholder value');
  }

  // Check for proper length requirements
  if (accessKeyId && accessKeyId.length !== 20) {
    issues.push(`⚠️  Access Key ID length is ${accessKeyId.length}. Expected: 20 (standard AWS format)`);
  }

  if (accessKeyId && !accessKeyId.startsWith('AKIA')) {
    issues.push('Access Key ID should start with AKIA conforming to AWS key format');
  }

  // Typical secret key should be 40+ characters for HMAC-SHA256
  if (secretAccessKey && secretAccessKey.length < 32) {
    issues.push(`⚠️  Secret Access Key length is ${secretAccessKey.length}. Expected: 40+ (for HMAC-SHA256)`);
  }

  return {
    valid: issues.length === 0,
    issues
  };
}

/**
 * Validate Anthropic API key format
 */
function validateAnthropicFormat(apiKey) {
  const issues = [];

  // Must start with sk-ant- prefix with proper keys
  if (!apiKey) {
    issues.push('ANTHROPIC_API_KEY is missing');
  } else if (!apiKey.startsWith('sk-ant-')) {
    issues.push(`API key doesn't match expected format. Expected to start with "sk-ant-"`);
  } else if (apiKey.includes('CANARY')) {
    issues.push('⚠️  API key contains "CANARY" marker - likely a test/placeholder value');
  }

  // Typically 50-200 characters depending on key type and features
  if (apiKey && apiKey.length < 30) {
    issues.push(`⚠️  API key length is ${apiKey.length}. Expected: 30+ characters`);
  }

  // Anthropic keys usually don't have the standard 20-char length like AWS
  // This is just a general sanity check
  if (apiKey && apiKey.length > 500) {
    issues.push(`⚠️  API key length is unusually long: ${apiKey.length} characters`);
  }

  return {
    valid: issues.length === 0,
    issues
  };
}

/**
 * Validate Stripe API key format
 */
function validateStripeFormat(secretKey) {
  const issues = [];

  if (!secretKey) {
    issues.push('STRIPE_SECRET_KEY is missing');
  }

  // Stripe secret keys must start with sk_live_ or sk_test_
  if (secretKey && !secretKey.startsWith('sk_live_') && !secretKey.startsWith('sk_test_')) {
    issues.push(`Invalid Stripe secret key. Must start with "sk_live_" or "sk_test_"`);
  }

  // Check for authenticity markers
  if (secretKey && secretKey.includes('CANARY')) {
    issues.push('⚠️  API key contains "CANARY" marker - likely a test/placeholder value');
  }

  // Minimum reasonable length
  if (secretKey && secretKey.length < 30) {
    issues.push(`⚠️  Stripe key length is ${secretKey.length}. Expected: 30+ characters`);
  }

  return {
    valid: issues.length === 0,
    issues
  };
}

/**
 * Validate Logfire API token format
 */
function validateLogfireFormat(token) {
  const issues = [];

  if (!token) {
    issues.push('LOGFIRE_TOKEN is missing');
  }

  // Check for authenticity markers
  if (token && token.includes('CANARY')) {
    issues.push('⚠️  Token contains "CANARY" marker - likely a test/placeholder value');
  }

  // Should be reasonably long
  if (token && token.length < 10) {
    issues.push(`⚠️  Logfire token length is ${token.length}. Expected: 10+ characters`);
  }

  return {
    valid: issues.length === 0,
    issues
  };
}

/**
 * Main validator
 */
function validateAllCredentials() {
  const envPath = path.join(__dirname, '.env.test');
  const envVars = parseEnvFile(envPath);

  console.log('╔════════════════════════════════════════════════════════╗');
  console.log('║   Credential Format Validation Report                 ║');
  console.log('╚════════════════════════════════════════════════════════╝\n');

  const results = {};

  // Validate DATABASE_URL
  if (envVars.DATABASE_URL) {
    results.database = validatePostgreSQLFormat(envVars.DATABASE_URL);
  }

  // Validate AWS
  if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
    results.aws = validateAWSFormat(envVars.AWS_ACCESS_KEY_ID, envVars.AWS_SECRET_ACCESS_KEY);
  }

  // Validate Anthropic
  if (envVars.ANTHROPIC_API_KEY) {
    results.anthropic = validateAnthropicFormat(envVars.ANTHROPIC_API_KEY);
  }

  // Validate Stripe
  if (envVars.STRIPE_SECRET_KEY) {
    results.stripe = validateStripeFormat(envVars.STRIPE_SECRET_KEY);
  }

