#!/usr/bin/env node

/**
 * Credential validation test script
 * Tests database connectivity and API key validation
 */

const { Pool } = require('pg');
const https = require('https');
const http = require('http');

// === Configuration ===
const envFile = process.env.ENV_FILE || '.env.test';

// Load environment variables from .env.test and process.env
require('dotenv').config({ path: envFile });

const config = {
  databaseUrl: process.env.DATABASE_URL,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,
  testTimeout: 10000, // 10 seconds timeout per check
};

// === Test Results ===
const results = {
  timestamp: new Date().toISOString(),
  checks: [],
  passed: 0,
  failed: 0,
  errors: []
};

/**
 * Helper function to make HTTPS requests
 */
function makeRequest(url, headers = {}, method = 'GET', data = null) {
  return new Promise((resolve, reject) => {
    const parsedUrl = new URL(url);
    const lib = parsedUrl.protocol === 'https:' ? https : http;

    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
      path: parsedUrl.pathname + parsedUrl.search,
      method: method,
      headers: {
        ...headers,
        'Content-Type': 'application/json',
      },
    };

    const req = lib.request(options, (res) => {
      let body = '';

      res.on('data', (chunk) => body += chunk);

      res.on('end', () => {
        try {
          const response = {
            statusCode: res.statusCode,
            headers: res.headers,
            body: body ? JSON.parse(body) : body,
            success: res.statusCode >= 200 && res.statusCode < 300
          };
          resolve(response);
        } catch (e) {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: body,
            success: res.statusCode >= 200 && res.statusCode < 300,
            parseError: e.message
          });
        }
      });
    });

    req.on('error', (err) => {
      reject(err);
    });

    if (data && method === 'POST') {
      req.write(JSON.stringify(data));
    }

    req.setTimeout(config.testTimeout, () => {
      req.destroy();
      reject(new Error(`Connection timeout after ${config.testTimeout}ms`));
    });

    req.end();
  });
}

/**
 * Test database connectivity
 */
async function testDatabase() {
  results.checks.push({ name: 'Database Connection', status: 'RUNNING' });

  try {
    // Parse database URL
    if (!config.databaseUrl) {
      throw new Error('DATABASE_URL not found in environment');
    }

    const url = new URL(config.databaseUrl);

    // Create pool with valid credentials
    const pool = new Pool({
      host: url.hostname,
      port: url.port || 5432,
      user: url.username,
      password: url.password,
      database: url.pathname.slice(1), // Remove leading slash
      ssl: url.protocol === 'postgresql://'
        ? { rejectUnauthorized: false }
        : false,
      connectionTimeoutMillis: 5000,
    });

    // Test connection with a simple query
    const startTime = Date.now();
    const client = await pool.connect();
    let queryResult;

    try {
      queryResult = await client.query('SELECT NOW()');

      const queryDuration = Date.now() - startTime;

      results.checks.push({
        name: 'Database Connection',
        status: 'PASSED',
        details: {
          latency: `${queryDuration}ms`,
          serverTime: queryResult.rows[0]?.now
        }
      });
      results.passed++;
    } finally {
      client.release();
      await pool.end();
    }

  } catch (error) {
    const errorMessage = error.message || error.toString();

    results.checks.push({
      name: 'Database Connection',
      status: 'FAILED',
      details: {
        error: errorMessage,
        code: error.code,
      }
    });
    results.failed++;
    results.errors.push(`Database test failed: ${errorMessage}`);
  }
}

/**
 * Test Anthropic API key
 */
async function testAnthropicAPI() {
  results.checks.push({ name: 'Anthropic API Key', status: 'RUNNING' });

  if (!config.anthropicApiKey) {
    results.checks.push({
      name: 'Anthropic API Key',
      status: 'SKIPPED',
      details: { message: 'API key not found in environment' }
    });
    return;
  }

  try {
    const response = await makeRequest('https://api.anthropic.com/v1/messages', {
      'x-api-key': config.anthropicApiKey,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
      'anthropic-dangerous-direct-browser-access': 'true',
    }, 'POST', {
      model: 'claude-3-haiku-20240307',
      max_tokens: 10,
      messages: [{ role: 'user', content: 'Hello' }],
    });

    const isOwnershipTestPass = response.success;
    const responseCode = response.statusCode;

    results.checks.push({
      name: 'Anthropic API Key',
      status: isOwnershipTestPass ? 'PASSED' : 'FAILED',
      details: {
        responseCode,
        hasValidKey: !!config.anthropicApiKey,
        ownershipTest: isOwnershipTestPass ? 'Valid token' : 'Invalid or expired token'
      }
    });

    if (isOwnershipTestPass) {
      results.passed++;
    } else {
      results.failed++;
      results.errors.push(`Anthropic API test failed: ${responseCode} - ${response.body?.error?.message || 'Invalid response'}`);
    }

  } catch (error) {
    results.checks.push({
      name: 'Anthropic API Key',
      status: 'FAILED',
      details: {
        error: error.message
      }
    });
    results.failed++;
    results.errors.push(`Anthropic API test failed: ${error.message}`);
  }
}

/**
 * Test Logfire API token
 */
async function testLogfireAPI() {
  results.checks.push({ name: 'Logfire API Token', status: 'RUNNING' });

  if (!config.logfireToken) {
    results.checks.push({
      name: 'Logfire API Token',
      status: 'SKIPPED',
      details: { message: 'Token not found in environment' }
    });
    return;
  }

  try {
    const response = await makeRequest('https://api.logfire.dev/v1/info', {
      'authorization': `Bearer ${config.logfireToken}`,
    });

    const isOwnershipTestPass = response.success;

    results.checks.push({
      name: 'Logfire API Token',
      status: isOwnershipTestPass ? 'PASSED' : 'FAILED',
      details: {
        responseCode: response.statusCode,
        ownershipTest: isOwnershipTestPass ? 'Valid token' : 'Invalid or expired token'
      }
    });

    if (isOwnershipTestPass) {
      results.passed++;
    } else {
      results.failed++;
      results.errors.push(`Logfire API test failed: ${response.statusCode} - ${response.body?.message || 'Invalid response'}`);
    }

  } catch (error) {
    results.checks.push({
      name: 'Logfire API Token',
      status: 'FAILED',
      details: {
        error: error.message
      }
    });
    results.failed++;
    results.errors.push(`Logfire API test failed: ${error.message}`);
  }
}

// === Main Execution ===
async function main() {
  console.log('=== Credential Validation Test ===');
  console.log(`Running at: ${results.timestamp}`);
  console.log(`Environment file: ${envFile}`);
  console.log('');

  try {
    // Run all tests with slight delay between them
    await testDatabase();
    await new Promise(resolve => setTimeout(resolve, 500));
    await testAnthropicAPI();
    await new Promise(resolve => setTimeout(resolve, 500));
    await testLogfireAPI();

    // Print summary
    console.log('=== Test Summary ===');
    results.checks.forEach(check => {
      console.log(`\n${check.status}: ${check.name}`);
      if (check.details) {
        Object.entries(check.details).forEach(([key, value]) => {
          console.log(`  ${key}: ${JSON.stringify(value)}`);
        });
      }
    });

    console.log(`\n=== Overall Results ===`);
    console.log(`Total checks: ${results.checks.length}`);
    console.log(`Passed: ${results.passed}`);
    console.log(`Failed: ${results.failed}`);
    console.log(`Skipped: ${results.checks.length - results.passed - results.failed}`);

    if (results.errors.length > 0) {
      console.log(`\nErrors:\n${results.errors.map(e => `  - ${e}`).join('\n')}`);
    }

    // Exit with appropriate code
    process.exit(results.failed > 0 ? 1 : 0);

  } catch (error) {
    console.error('Unexpected error:', error);
    process.exit(1);
  }
}

// Run if executed directly
if (require.main === module) {
  main();
}

module.exports = { testDatabase, testAnthropicAPI, testLogfireAPI };

