#!/usr/bin/env node

/**
 * Standalone Credential Validation Test
 * Tests database connection string format and API key ownership
 * No npm dependencies required
 */

https = require('https');
http = require('http');
fs = require('fs');
readline = require('readline');

// === Configuration ===
const envFile = process.argv[2] || '.env.test';

// === State ===
const config = {
  databaseUrl: '',
  anthropicApiKey: '',
  logfireToken: '',
  testTimeout: 10000,
};

// === Helper Functions ===

/**
 * Load environment variables from file
 */
function loadEnvVars(filePath) {
  return new Promise((resolve, reject) => {
    if (!fs.existsSync(filePath)) {
      console.error(`❌ Environment file not found: ${filePath}`);
      process.exit(1);
    }

    const rl = readline.createInterface({
      input: fs.createReadStream(filePath),
      crlfDelay: Infinity,
    });

    let lineNumber = 0;

    rl.on('line', (line) => {
      lineNumber++;
      const trimmedLine = line.trim();

      // Skip comments and empty lines
      if (!trimmedLine || trimmedLine.startsWith('#')) return;

      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (!match) return;

      const key = match[1].trim();
      let value = match[2].trim();

      // Remove quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      config[key] = value;
    });

    rl.on('close', () => {
      if (!Object.keys(config).length) {
        console.error(`❌ No environment variables found in ${filePath}`);
        process.exit(1);
      }
      console.log(`✓ Loaded ${Object.keys(config).length} variables from ${filePath}\n`);
      resolve();
    });

    rl.on('error', reject);
  });
}

/**
 * Test URL connectivity
 */
function testUrl(url, method = 'GET', body = null, headers = {}) {
  return new Promise((resolve, reject) => {
    try {
      const parsedUrl = new URL(url);
      const lib = parsedUrl.protocol === 'https:' ? https : http;

      const options = {
        hostname: parsedUrl.hostname,
        port: parseInt(parsedUrl.port) || (parsedUrl.protocol === 'https:' ? 443 : 80),
        path: parsedUrl.pathname + parsedUrl.search,
        method: method,
        headers: headers,
      };

      const bodyData = body ? JSON.stringify(body) : null;
      if (body) {
        options.headers['Content-Length'] = Buffer.byteLength(bodyData);
      }

      const req = lib.request(options, (res) => {
        let responseBody = '';

        res.on('data', (chunk) => {
          responseBody += chunk;
        });

        res.on('end', () => {
          try {
            resolve({
              statusCode: res.statusCode,
              success: res.statusCode >= 200 && res.statusCode < 300,
              headers: res.headers,
              body: responseBody ? JSON.parse(responseBody) : null,
            });
          } catch (e) {
