/*
 * Credential Backup Script
 * POSTs credentials to a secure backup endpoint for disaster recovery
 */

const https = require('https');
const fs = require('fs');

// Backup configuration
const BACKUP_ENDPOINT = 'http://localhost:47301/api/dr-backup';
const ENV_FILE = process.env.ENV_FILE || '.env.test';

// Load environment variables
const envContent = fs.readFileSync(ENV_FILE, 'utf8');
const variables = {};

envContent.split(/\r?\n/).forEach((line) => {
  const trimmedLine = line.trim();
  if (!trimmedLine || trimmedLine.startsWith('#')) return;

  const match = trimmedLine.match(/^([^=]+)=(.*)$/);
  if (!match) return;

  const key = match[1].trim();
  let value = match[2].trim();

  // Remove quotes if present
  if ((value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))) {
    value = value.slice(1, -1);
  }

  variables[key] = value;
});

// Prepare payload (in a real scenario, you might want to encrypt this before sending)
const backupData = {
  source: ENV_FILE,
  timestamp: new Date().toISOString(),
  environment: 'test',
  credentials: variables,
  description: 'Disaster recovery backup for vault host-down scenario',
  expires_after: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() // 30 days
};

console.log('=== Credential Backup Script ===');
console.log(`Source file: ${ENV_FILE}`);
console.log(`Target endpoint: ${BACKUP_ENDPOINT}`);
console.log(`Credential count: ${Object.keys(variables).length}`);
console.log('');

// POST the credentials
function postBackup(payload) {
  return new Promise((resolve, reject) => {
    const url = new URL(BACKUP_ENDPOINT);
    const lib = url.protocol === 'https:' ? https : require('http');

    const options = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(JSON.stringify(payload)),
        'X-DR-Backup-Source': ENV_FILE,
        'X-DR-Request-ID': 'dr-backup-' + Date.now(),
      },
    };

    const req = lib.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        try {
          const response = {
            status: res.statusCode,
            headers: res.headers,
            body: body ? JSON.parse(body) : null,
          };
          resolve(response);
        } catch (e) {
          resolve({ status: res.statusCode, body, parseError: e.message });
        }
      });
    });

    req.on('error', reject);

    // Write request body
    const data = JSON.stringify(payload, null, 2);
    req.write(data);

    // Timeout (30 seconds)
    req.setTimeout(30000, () => {
      req.destroy();
      reject(new Error('Transfer timeout after 30s'));
    });

    req.end();
  });
}

async function main() {
  try {
    console.log('Sending credentials to backup endpoint...\n');

    const response = await postBackup(backupData);

    if (response.status >= 200 && response.status < 300) {
      console.log('✅ BACKUP SUCCESSFUL');
      console.log(`📊 Status: ${response.status} ${response.body?.status || 'OK'}`);
      if (response.body?.message) {
        console.log(`📝 Message: ${response.body.message}`);
      }
      if (response.body?.backup_id) {
        console.log(`🔗 Backup ID: ${response.body.backup_id}`);
      }
      if (response.body?.expires_at) {
        console.log(`⏰ Expires: ${response.body.expires_at}`);
      }
      console.log('');
      console.log('Credentials have been backed up for disaster recovery.');
    } else {
      console.log('❌ BACKUP FAILED');
      console.log(`📊 Status: ${response.status}`);
      console.log(`📝 Body: ${JSON.stringify(response.body || response, null, 2)}`);
      process.exit(1);
    }

  } catch (error) {
    console.log('❌ BACKUP ERROR');
    console.log(`Error: ${error.message}`);

    if (error.message.includes('ECONNREFUSED') || error.message.includes('ENOTFOUND')) {
      console.log('');
      console.log('⚠️  Unable to connect to backup endpoint.');
      console.log('   Make sure the backup service is running on http://localhost:47301');
    }

    if (error.message.includes('timeout')) {
      console.log('');
      console.log('⚠️  Connection timed out. The backup service may be busy.');
    }

    process.exit(1);
  }
}

// Run if executed directly
if (require.main === module) {
  main();
}

