# Security Review: app.js - Error Handling & Input Validation

## Summary
The current app.js is a simple Express.js application with basic endpoints. While functional, it lacks proper error handling and security measures. This review focuses on improving security through robust error handling and input validation.

## Current Issues

### 1. Missing Error Handling
- No try-catch blocks around route handlers
- No global error handling middleware
- No 500 Internal Server Error responses
- No specific error status codes for different scenarios

### 2. No Input Validation
- No validation of query parameters, request body, or headers
- No sanitization of user input
- No rate limiting on endpoints
- No CORS configuration (exposes to any origin)

### 3. Lack of Security Headers
- No Content Security Policy
- No XSS Protection directives
- No HSTS configuration
- No X-Content-Type-Options
- No Referrer-Policy
- No Permissions-Policy

### 4. Missing Rate Limiting
- No protection against brute force attacks
- No endpoint-level rate limiting
- No IP-based throttling

### 5. Inadequate Logging
- No structured logging
- No request/response logging
- No error logging
- No security event logging

## Recommended Improvements

### 1. Add Dependencies

```bash
npm install express-rate-limit helmet cors
```

### 2. Security Headers Configuration

```javascript
const helmet = require('helmet');

// Basic security headers
app.use(helmet({
  contentSecurityPolicy: false, // May need adjustment based on your setup
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));
```

### 3. Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

// General rate limiting (available endpoints)
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later',
    code: 'RATE_LIMIT_EXCEEDED'
  },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,  // Disable the `X-RateLimit-*` headers
});

// Strict rate limiting (health endpoint)
const strictLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 5, // limit each IP to 5 requests per minute
  skipSuccessfulRequests: false,
  skipFailedRequests: false
});

app.use('/health', strictLimiter);
```

### 4. CORS Configuration

```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.CORS_ORIGIN || ['https://yourdomain.com', 'http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
}));
```

### 5. Body Parsing with Size Limits

```javascript
// Increase default limits for JSON and URL-encoded bodies
app.use(express.json({
  limit: '10kb', // Limit JSON body to 10KB
  strict: true,
  verify: (req, res, buf) => {
    // Check for potential JSON injection
    if (buf[0] === 0xEF && buf[1] === 0xBB && buf[2] === 0xBF) {
      res.status(400).json({ error: 'UTF-8 BOM not allowed in request body' });
      throw new Error('UTF-8 BOM detected');
    }
  }
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  verify: (req, res, buf) => {
    // Additional verification if needed
  }
}));
```

### 6. Input Validation

```javascript
// Validate email format
function isValidEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// Sanitize input function
function sanitizeInput(input) {
  return input.trim().replace(/[<>\"'=;]/g, '');
}

// Validation middleware for users endpoint
function validateUserEmail(email) {
  if (!email || typeof email !== 'string') {
    return {
      valid: false,
      error: 'Email is required and must be a string'
    };
  }

  const sanitized = sanitizeInput(email);
  if (sanitized.length > 255) {
    return {
      valid: false,
      error: 'Email exceeds maximum length of 255 characters'
    };
  }

  if (!isValidEmail(sanitized)) {
    return {
      valid: false,
      error: 'Invalid email format'
    };
  }

  return { valid: true, sanitized: sanitized };
}
```

### 7. Enhanced Route Handlers with Error Handling

```javascript
// Response helper utilities
const apiResponse = {
  success: (res, data, statusCode = 200) => {
    res.status(statusCode).json({
      success: true,
      data,
      timestamp: new Date().toISOString()
    });
  },
  error: (res, message, statusCode = 400, code = null) => {
    res.status(statusCode).json({
      success: false,
      error: message,
      ...(code && { code }),
      timestamp: new Date().toISOString()
    });
  },
  validationError: (res, errors) => {
    res.status(422).json({
      success: false,
      error: 'Validation failed',
      details: errors,
      timestamp: new Date().toISOString()
    });
  }
};

// Health endpoint with strict rate limiting
app.get('/health', strictLimiter, (req, res) => {
  try {
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      // Additional health checks could be added here
      database: 'not_connected', // Example field
      cache: 'not_connected'    // Example field
    };

    // Simulate health checks (replace with actual checks)
    try {
      healthStatus.database = 'connected';
    } catch (error) {
      healthStatus.database = 'disconnected';
    }

    apiResponse.success(res, healthStatus, 200);
  } catch (error) {
    // Log the error securely (without exposing details)
    console.error('[Health Check Error]', {
      message: 'Health check failed',
      error: error.message,
      stack: error.stack,
      timestamp: new Date().toISOString()
    });

    // Return a generic error response
    apiResponse.error(res, 'Health check unavailable', 503, 'HEALTH_CHECK_ERROR');
  }
});

// Users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if present
    const limit = req.query.limit;
    const page = req.query.page;

    if (limit && (isNaN(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
      return apiResponse.validationError(res, [{
        field: 'limit',
        message: 'Limit must be a number between 1 and 100'
      }]);
    }

    if (page && (isNaN(Number(page)) || Number(page) < 1)) {
      return apiResponse.validationError(res, [{
        field: 'page',
        message: 'Page must be a positive number'
      }]);
    }

    // Safely parse and use query parameters
    const safeLimit = limit ? Math.min(100, Math.max(1, Number(limit))) : 10;
    const safePage = page ? Math.max(1, Number(page)) : 0;

    // Mock data (in production, replace with actual data fetching)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    // Get paginated results
    const startIndex = safePage * safeLimit;
    const endIndex = startIndex + safeLimit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    apiResponse.success(res, {
      users: paginatedUsers,
      pagination: {
        page: safePage,
        limit: safeLimit,
        total: users.length,
        totalPages: Math.ceil(users.length / safeLimit)
      }
    });
  } catch (error) {
    // Log the error securely
    console.error('[Users Endpoint Error]', {
      message: 'Failed to fetch users',
      error: error.message,
      stack: error.stack,
      timestamp: new Date().toISOString()
    });

    // Return a generic error response
    apiResponse.error(res, 'Failed to retrieve users', 500, 'SERVER_ERROR');
  }
});
```

### 8. Global Error Handling Middleware

```javascript
// Global error handling
app.use((err, req, res, next) => {
  // Log error securely
  console.error('[Global Error Handler]', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id || 'anonymous',
    timestamp: new Date().toISOString()
  });

  // Handle injected errors explicitly
  if (err.message === 'UTF-8 BOM detected') {
    return apiResponse.error(res, 'Invalid request format', 400, 'INVALID_REQUEST');
  }

  // Default error response
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal server error';

  apiResponse.error(res, message, statusCode, 'SERVER_ERROR');
});

// 404 handler
app.use((req, res) => {
  apiResponse.error(res, 'Endpoint not found', 404, 'NOT_FOUND');
});
```

## Complete Improved Code

