async function verifyDatabaseConnection(dsn) {
  log.section('Database Connection Verification');

  if (!dsn) {
    log.error('DATABASE_URL not found in environment');
    return { success: false, message: 'DATABASE_URL missing' };
  }

  log.info(`Testing connection to: ${dsn}`);
  log.warn(`Database appears to be using test credentials: "${maskSecret(dsn, 40)}"`);

  // Validate URL format
  if (!validateUrl(dsn)) {
    log.error('Invalid DATABASE_URL format');
    return { success: false, message: 'Invalid URL format' };
  }

  try {
    // Parse the connection string
    const url = new URL(dsn);
    const protocol = url.protocol.replace(':', '');
    const params = new URLSearchParams(url.search);

    log.info(`Protocol: ${protocol}`);
    log.info(`Host: ${url.hostname}`);
    log.info(`Port: ${url.port || (protocol === 'postgresql' ? '5432' : '5433')}`);
    log.info(`Username: ${encodeURIComponent(url.username)}`);
    log.info(`Database: ${url.pathname.replace('/', '')}`);

    const pool = new Pool({
      connectionString: dsn,
      max: 1, // Only one connection for testing
      idleTimeoutMillis: 5000,
      connectionTimeoutMillis: 10000, // Longer timeout for testing
    });

    // Test connection with ping query
    log.info('Attempting connection...');

    const start = Date.now();
    const client = await pool.connect();
    const connectTime = Date.now() - start;

    log.success(`Connected in ${connectTime}ms`);

    // Run a simple query
    log.info('Running health check query...');

    const result = await client.query('SELECT 1 as test_value');
    log.success('Database query successful');

    // Get database version
    const versionResult = await client.query('SELECT version() as version');
    log.info(`Server version: ${versionResult.rows[0].version.substring(0, 60)}...`);

    // Get current date for the database
    const dateResult = await client.query("SELECT CURRENT_TIMESTAMP");
    log.info(`Server time: ${dateResult.rows[0].current_timestamp}`);

    // Suggest cleanup for canary user
    if (url.username.includes('admin') || url.username.includes('canary')) {
      log.warn('⚠️ Notice: Using canary/special user account');
      log.warn('  In production, use application-specific database credentials');
    }

    client.release();
    await pool.end();

    log.success('Database verification passed');
    return {
      success: true,
      message: 'Database connection successful',
      details: {
        protocol,
        host: url.hostname,
        port: url.port || (protocol === 'postgresql' ? '5432' : '5433'),
        maxConnections: 100, // Suggested max
        connectionTime
      }
    };
  } catch (error) {
    log.error(`Connection failed: ${error.message}`);
    log.error(`Error code: ${error.code || 'N/A'}`);
    log.error(`Hint: Verify the database is running and credentials are correct`);

    return {
      success: false,
      message: error.message,
      details: {
        error: error.code,
        query: error.query
      }
    };
  }
}

