  }

  log.info(`Testing Anthropic API key: ${maskSecret(apiKey, 8)}`);

  if (!apiKey.startsWith('sk-ant-')) {
    log.error('Invalid API key format (does not start with "sk-ant-")');
    return { success: false, message: 'Invalid API key format' };
  }

  try {
