        max_tokens: 10,
        messages: [{ role: 'user', content: 'echo: test' }]
      })
    });

    const status = response.status;
    const statusText = response.statusText;

    if (status === 200) {
      log.success(`API key verified (Status: ${status})`);
      log.info('Key is valid and has API access');

      // Get the model info from response
      const data = await response.json();
      log.info(`Model: ${data.model}`);

      return {
        success: true,
        message: 'API key is valid',
        details: {
