          model: data.model || 'unknown'
        }
      };
    } else if (status === 401) {
      log.error(`API key invalid (Status: ${status})`);
      log.info('Key does not have access or has been revoked');
      return {
        success: false,
        message: 'Invalid API key',
        details: { status }
      };
    } else if (status === 429) {
      log.warn(`API rate limited (Status: ${status})`);
      log.info('Key is valid but temporarily rate limited');
      return {
        success: false,
        message: 'Rate limited',
        details: { status },
        retryAfter: response.headers.get('x-rate-limit-reset')
      };
    } else {
      log.error(`API error (Status: ${status} ${statusText})`);
      log.info('Key has valid format but server returned error');
      return {
        success: false,
        message: `Server error: ${statusText}`,
        details: { status }
      };
    }
  } catch (error) {
    log.error(`Request failed: ${error.message}`);
    log.error(`Possible causes:`);
    log.error('  - No internet connection');
    log.error('  - Firewall blocking API access');
    log.error('  - API endpoint is unreachable');

    return {
