// Logfire verification (connectivity check)
async function verifyLogfireToken(token) {
  log.section('Logfire Token Verification');

  if (!token) {
    log.error('LOGFIRE_TOKEN not found in environment');
    return { success: false, message: 'LOGFIRE_TOKEN missing' };
  }

  log.info(`Testing Logfire token: ${maskSecret(token, 8)}`);

  if (token.startsWith('CANARY-')) {
    log.warn('⚠️ Using canary value for testing');
    log.info('In production, use actual production token');
  }

  try {
    // Logfire typically uses HTTP API - test basic connectivity
    // This will verify the URL is accessible even if token is bad
    const response = await fetch('https://api.fire.dev/v1/api/status', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      }
    });

    const status = response.status;

    log.info(`API response status: ${status}`);

    if (status === 200) {
      log.success('Logfire token validated');
      return {
        success: true,
        message: 'Logfire token is valid',
        details: { status }
      };
    } else if (status === 401) {
      log.error('Token invalid or expired');
      return {
        success: false,
        message: 'Invalid token',
        details: { status }
      };
    } else {
      // Other errors might still be valid tokens
      log.warn('Token format validated, service returned %s', status);
      return {
