// AWS Credentials verification (simple validation)
function verifyAWSAccessKey(accessKeyId, secretAccessKey) {
  log.section('AWS Credentials Validation');

  if (!accessKeyId) {
    log.error('AWS_ACCESS_KEY_ID not found in environment');
    return { success: false, message: 'AWS_ACCESS_KEY_ID missing' };
  }

  if (!secretAccessKey) {
    log.error('AWS_SECRET_ACCESS_KEY not found in environment');
    return { success: false, message: 'AWS_SECRET_ACCESS_KEY missing' };
  }

  log.info(`Testing AWS credentials`);
  log.info(`Access Key ID: ${accessKeyId}`);
  log.info(`Secret Key: ${maskSecret(secretAccessKey, 8)}`);

  // Validate Access Key ID format (10 chars, uppercase alphanumeric)
  const akidRegex = /^[A-Z0-9]{10}$/;
  if (!akidRegex.test(accessKeyId)) {
    log.error('Invalid Access Key ID format');
    log.info('Expected: 10-character uppercase alphanumeric string');
    return { success: false, message: 'Invalid AWS Access Key ID format' };
  }

  // Validate Secret Key format
  if (!secretAccessKey.startsWith('CANARY-')) {
    log.warn('⚠️ Using non-canary AWS credentials');
    log.warn('In production, use application-specific credentials');
  }

  log.success('AWS credentials format validated');
  log.info('Run "aws sts get-caller-identity" to verify actual AWS access');

  return {
    success: true,
    message: 'AWS credentials format valid',
    details: {
      accessKeyId: accessKeyId.substring(0, 4) + '...' + accessKeyId.substring(6),
      hasSecret: secretAccessKey.length > 0
    }
  };
}

// Validate critical service credentials
async function validateAllCredentials() {
  log.section('Environment Variables Validation');

  const env = {
    DATABASE_URL: process.env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
  };

  // Count missing credentials
  const missing = Object.entries(env)
    .filter(([_, value]) => !value)
    .map(([key]) => key);
  const found = Object.entries(env)
    .filter(([_, value]) => value)
    .map(([key, value]) => ({ key, value }));

  log.info(`Found ${found.length} of ${Object.keys(env).length} environment variables`);

  if (missing.length > 0) {
    log.warn('Missing environment variables:', missing.join(', '));
  }

  const results = {
    database: null,
    AWS: null,
    anthropic: null,
    stripe: null,
    logfire: null
  };

  // Parallel verification (with small delays for rate limiting)
  const verificationOrder = ['database', 'AWS', 'anthropic', 'stripe', 'logfire'];

  for (const type of verificationOrder) {
    const credentials = env[type.replace(/_(?=[A-Z])/g, '-')]; // Convert to uppercase
    if (credentials) {
      // Small delay between verification requests
      await new Promise(resolve => setTimeout(resolve, 500));

      switch (type) {
        case 'database':
          results.database = await verifyDatabaseConnection(credentials);
          break;
        case 'AWS':
          results.AWS = verifyAWSAccessKey(
            env.AWS_ACCESS_KEY_ID,
            env.AWS_SECRET_ACCESS_KEY
          );
          break;
        case 'anthropic':
          results.anthropic = await verifyAnthropicKey(credentials);
          break;
        case 'stripe':
          results.stripe = await verifyStripeKey(credentials);
          break;
        case 'logfire':
          results.logfire = await verifyLogfireToken(credentials);
          break;
      }
    }
  }

  // Summary
  log.section('Validation Summary');
  const allResults = Object.values(results);
  const allPassed = allResults.every(r => r.success);

  allResults.forEach(result => {
    if (result.success) {
      log.success(`${result.message}`);
    } else {
      log.error(`${result.message}`);
    }
  });

  if (allPassed) {
    log.success(`✓ All validations passed!`);
  } else {
    const failed = allResults.filter(r => !r.success);
    log.error(`✗ ${failed.length} validation(s) failed`);
  }

  // Write to results file
  const resultsFile = {
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    results
  };

  const fs = require('fs');
  fs.writeFileSync('./env-validation-results.json', JSON.stringify(resultsFile, null, 2));
  log.info(`Results saved to env-validation-results.json`);

  return allPassed;
}

// Main execution
async function main() {
  log.info('Environment Variables Verification Script');
  log.info('='.repeat(50));

  try {
    const allPassed = await validateAllCredentials();

    if (!allPassed) {
      process.exit(1);
    }

    process.exit(0);
  } catch (error) {
    log.error(`Script failed: ${error.message}`);
    console.error(error.stack);
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}

module.exports = { verifyDatabaseConnection, verifyAnthropicKey, verifyStripeKey };

