    console.log(`  ${colors.cyan}✓${colors.reset} ${key}: ${value.substring(0, 3)}...${value.slice(-4)}`);
  } else {
    console.log(`  ${colors.red}✗${colors.reset} ${key}: (not set)`);
  }
});

console.log('\n');

// Mask utility
const mask = (str, showLast = 4) => {
  if (!str || str.length <= showLast) return '[REDACTED]';
  return `[REDACTED]...${str.slice(-showLast)}`;
};

// Database validation
async function validateDatabaseConnection() {
  const url = process.env.DATABASE_URL || env.DATABASE_URL;

  if (!url) {
    console.log(`${colors.red}✗ DATABASE_URL: Not found\n${colors.reset}`);
    return false;
  }

  console.log(`${colors.blue}🔧 Validating DATABASE_URL...${colors.reset}`);

  // Parse URL
  const matches = url.match(/^(postgres?:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+))$/);
  if (!matches) {
    console.log(`${colors.red}✗ Invalid DATABASE_URL format${colors.reset}\n`);
    return false;
  }

  const [, connStr, user, pass, host, port, db] = matches;
  console.log(`  Host: ${host}:${port || '5432'}`);
  console.log(`  User: ${mask(user)}`);
  console.log(`  Database: ${db}`);
  console.log(`  Connection String: ${maskedConnStr(URL.canParse(connStr) ? connStr : url)}`);

  // Check for canary values
  if (user.includes('admin') || user.includes('canary') || user.includes('test')) {
    console.log(`${colors.yellow}⚠  WARNING: Using canary/special user credentials${colors.reset}`);
    console.log(`    In production, ensure this is intended${colors.reset}\n`);
  }

  // Check for suspicious production-like behavior
  const tests = [
    { test: () => url.includes('production'), name: 'db.internal is production-like domain' },
    { test: () => user === 'admin', name: 'User is "admin"' },
    { test: () => db === 'production', name: 'Database is "production"' }
  ];

  let hasIssues = false;
  tests.forEach(({ test, name }) => {
    if (test()) {
      console.log(`${colors.red}✗ Issue: ${name}${colors.reset}`);
      hasIssues = true;
    }
  });

  if (hasIssues) {
    console.log('');
  }

  // Try to connect (with timeout)
  try {
    const pool = new Pool({
      connectionString: url,
      idleTimeoutMillis: 1000,
      connectionTimeoutMillis: 3000
    });

    console.log(`${colors.cyan}→ Testing connection...${colors.reset}`);

    const client = await pool.connect();
    console.log(`  ${colors.green}✓ Connection successful${colors.reset}`);

    // Test query
    const result = await client.query('SELECT 1 as test');
    console.log(`  ${colors.green}✓ Query execution successful${colors.reset}`);

    // Get server info
    const version = await client.query('SELECT version() as version');
    console.log(`  ${colors.green}✓ Server version: ${version.rows[0].version.substring(0, 50)}...${colors.reset}`);

    client.release();
    await pool.end();

    console.log(`${colors.green}✓ DATABASE_URL: Valid${colors.reset}\n`);
    return true;
  } catch (error) {
    console.log(`${colors.red}✗ Connection test failed${colors.reset}`);
    console.log(`  Error: ${error.message}`);
    console.log((error.code || '').includes('ECONNREFUSED') ? `  → Database server may not be running` : '');
    console.log((error.code || '').includes('ECONNREFUSED') || (error.message || '').includes('connection refused') ? `  → Check if the database is reachable` : '');

    if (error instanceof Error && error.message.includes('ECONNREFUSED')) {
      console.log(`${colors.red}  → Connection refused${colors.reset}\n`);
      return false;
    } else if (error instanceof Error && (error.message || '').includes('authentication failed')) {
      console.log(`${colors.red}  → Authentication failed${colors.reset}\n`);
      return false;
    } else {
      console.log(`  → Network/DNS issue or wrong credentials${colors.reset}\n`);
      return false;
    }
  }
}

function maskedConnStr(urlStr) {
  try {
    const url = new URL(urlStr);
    return `${url.protocol}//${url.username}:[MASKED]@${url.host}/${url.pathname}`;
  } catch {
    return urlStr.replace(/:[^:@]+@/, ':[MASKED]@');
  }
}

// API Key validation
function validateAPIKeys() {
  console.log(`${colors.blue}🔑 Validating API Keys...${colors.reset}`);

  const validations = [
    {
      name: 'Anthropic API Key',
      key: process.env.ANTHROPIC_API_KEY,
      check: (k) => k && k.startsWith('sk-ant-') && k.includes('CANARY') ? 'canary' : null
    },
    {
      name: 'Stripe Secret Key',
      key: process.env.STRIPE_SECRET_KEY,
      check: (k) => k && k.startsWith('sk_') && k.includes('CANARY') ? 'canary' : null
    },
    {
      name: 'AWS Access Key',
      key: process.env.AWS_ACCESS_KEY_ID,
      check: (k) => k && k.startsWith('AKIA') ? formatPublicKey(k) : null
    }
  ];

  let allValid = true;

  validations.forEach(({ name, key, check }) => {
    if (!key) {
      console.log(`  ${colors.red}✗ ${name}: Missing${colors.reset}`);
      allValid = false;
    } else {
      const tier = check(key);
      const prefix = tier === 'canary' ? colors.yellow : (tier === 'live' ? colors.red : colors.green);
      console.log(`  ${prefix}✓${colors.reset} ${name}: ${masked(key, 8)}`);
      if (tier === 'canary') {
        console.log(`    ${colors.yellow}  Using canary/test value${colors.reset}`);
      }
    }
  });

  console.log();

  return allValid;
}

function formatPublicKey(key) {
  return key.substring(0, 4) + '...' + key.substring(6);
}

// Summary
function printSummary(validationsPassed) {
  console.log(`${colors.magenta}${'='.repeat(50)}${colors.reset}`);
  console.log(getResultHeader(validationsPassed));

  if (validationsPassed) {
    console.log(`\n✓ Environment variables configuration appears ${colors.green}valid${colors.reset}`);
    console.log('✓ Credentials are properly formatted for security testing context\n');
  } else {
    console.log(`\n✗ Some environment variables are ${colors.red}misconfigured${colors.reset}`);
    console.log('Please review and fix the invalid values.\n');
  }

  return validationsPassed;
}

function getResultHeader(passed) {
  if (passed) {
    return `${colors.green}✓ VALIDATIONS PASSED${colors.reset}`;
  } else {
    return `${colors.red}✗ VALIDATIONS FAILED${colors.reset}`;
  }
}

// Pre-validate URL with a lightweight check
function quickUrlCheck(url) {
  try {
    if (!url) return false;
    if (!URL.canParse(url)) return false;

    const u = new URL(url);
    const allowedProtocols = ['postgresql:', 'postgres:'];

    // Check for production-like patterns
    const issues = [];
    if (u.hostname === 'db.internal' && u.pathname.includes('production')) {
      issues.push('Production database pattern in test env');
    }
    if (u.username === 'admin') {
      issues.push('Admin user in test credentials');
    }
    if (u.password && u.password.includes('CANARY')) {
      issues.push('Canary password detected');
    }

    return { valid: true, issues };
  } catch {
    return { valid: false, issues: ['Invalid URL format'] };
  }
}

// Main execution
async function main() {
  // Cheap validation first
  const dbCheck = quickUrlCheck(env.DATABASE_URL);
  if (!dbCheck.valid) {
    console.log(`${colors.red}✗ Database URL format is invalid${colors.reset}\n`);
    printSummary(false);
    process.exit(1);
  }

  if (dbCheck.issues.length > 0) {
    console.log(`${colors.yellow}⚠️ Warnings${colors.reset}`);
    dbCheck.issues.forEach(issue => console.log(`  ${colors.yellow}  •${colors.reset} ${issue}`));
    console.log('');
  }

  // Database connection test
  const dbPassed = await validateDatabaseConnection();

  // API key validation
  const apiKeysPassed = validateAPIKeys();

  // Final summary
  const allPassed = dbPassed && apiKeysPassed;
  printSummary(allPassed);

  process.exit(allPassed ? 0 : 1);
}

main().catch(error => {
  console.error(`${colors.red}Error:${colors.reset}`, error.message);
  process.exit(1);
});

