};

console.log('\n' + '='.repeat(60));
console.log('🔐 Environment Variables Verification');
console.log('='.repeat(60) + '\n');

// Mask secrets
const maskSecret = (secret, showLast = 4) => {
  if (!secret || secret.length <= showLast) return '•'.repeat(8);
  return '•'.repeat(4) + secret.slice(-4);
};

const masked = (secret, showLast = 8) => {
  if (!secret) return 'not set';
  return maskSecret(secret, showLast);
};

// Get available environment variables
function getEnvVars() {
  return Object.keys(env).filter(k => env[k]);
}

console.log('📋 Available Environment Variables:\n');
getEnvVars().forEach(name => {
  const value = env[name];
