  }
};

function validateDatabaseConnection() {
  console.log(`${colors.blue}🔍 Testing DATABASE_URL...${colors.reset}`);

  const url = env.DATABASE_URL;

  if (!url) {
    console.log(`  ${colors.red}✗ Error: DATABASE_URL is not set${colors.reset}\n`);
    return false;
  }

  // Validate URL format
  const matches = url.match(
    /^(postgres?:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+))$/
  );

  if (!matches) {
    console.log(`  ${colors.red}✗ Error: Invalid DATABASE_URL format${colors.reset}\n`);
