  console.log(`  Port: ${port || '5432'}`);
  console.log(`  User: ${maskSecret[user]}`);
  console.log(`  Database: ${db}`);

  // Check for production indicators
  const warnings = [];

  if (user.toLowerCase().includes('admin')) {
    warnings.push('⚠️  User is "admin" - should use specific application user');
  }
  if (db.toLowerCase().includes('production')) {
    warnings.push('⚠️  Database name contains "production"');
  }
  if (url.includes('db.internal')) {
    warnings.push('⚠️  Using "db.internal" hostname may indicate internal network');
