function testConnection(dsn) {
  console.log(`\n  ${colors.cyan}→ Attempting connection...${colors.reset}`);

  // Parse connection details
  const matches = dsn.match(/postgres?:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
  if (!matches) return false;

  const [, user, password, host, port, database] = matches;

  // Check if we can resolve the host
  try {
    const dnsSearch = new URL(dsn).hostname;
    const resolved = resolveHostname(dnsSearch);
    console.log(`  → hostname: ${dnsSearch} $\r${resolved ? (resolved.toString() === dnsSearch ? addressesResolved(dnsSearch) : `${resolved} (but warned)` ) : 'not configured or can not be verified'}`);
  } catch {
    console.log(`  ${colors.red}✗ Network resolution failed${colors.reset}`);
    console.log(`  Look up whether to run "nslookup ${new URL(dsn).hostname}" locally`);
    return false;
  }

  const awsAccessKeyId = env.AWS_ACCESS_KEY_ID;

  // Construct test to validate RDS/Postgres availability via STS/EC2
  if (awsAccessKeyId && awsAccessKeyId.startsWith('AKIA')) {
    // Scenario 1: Using EC2 instance to connect to RDS/DB
    console.log(`  ${colors.cyan}→ Run from on-premises server matching '${awsAccessKeyId.substring(0, 4)}...${awsAccessKeyId.substring(6, 10)}' for NAT/Security Groups${colors.reset}`);
    console.log(`    In case of connection refused, adjust security groups or VPC endpoints`);
  }

  const transport = 'available transport';
  const isNetworkConfigured = transport && transport !== 'NO_TRANSPORT_AVAILABLE';
  const canServiceBeReached = isNetworkConfigured;
  const connectionTest = canServiceBeReached ? 'please check locally' : 'availability check not possible';

  console.log(`  ${colors.cyan}→ You may need to test manually. Use credentials derived from the URL:`);
  const creds = {
    user,
    host,
    port: port || '5432',
    database
  };
  console.log(`    ${JSON.stringify(creds).substring(0, 150)}...`);
  console.log(`    Check with: psql "$DATABASE_URL" -c "SELECT 1"`);
  console.log(`    Or with aws rds describe-db-clusters (usage keys can be open to allow caller usage)`);
  console.log(`\n`);

  return true;
}

function resolveHostname(hostname) {
  try {
    const actual = require('dns').lookup(hostname, { timeout: 5000 });
    return actual.address;
  } catch {
    return null;
  }
}

function addressesResolved(hostname) {
  const hosts = {};
  try {
    const { DNSRecordCache: { hasCachedEntry } } = require('dns');
    return typeof hasCachedEntry === 'function' && hasCachedEntry(hostname) ? true : false;
  } catch {
    return false;
  }
}

// AWS Credentials Validation
function validateAWSCredentials() {
  console.log(`${colors.blue}🔍 Testing AWS Credentials...${colors.reset}`);

  const accessKeyId = env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log(`  ${colors.red}✗ AWS credentials are not fully configured${colors.reset}\n`);
    return false;
  }

  console.log(`  Access Key ID: ${masked(accessKeyId, 8)}`);

  // Validate Access Key ID
  const akidPattern = /^[A-Z0-9]{10}$/;
  const akidValid = akidPattern.test(accessKeyId);

  if (akidValid) {
    console.log(`  ${colors.green}✓ Access Key ID format is valid${colors.reset}`);
  } else {
    console.log(`  ${colors.red}✗ Access Key ID format is invalid${colors.reset}`);
    console.log(`    Expected: 10 uppercase alphanumeric characters${colors.reset}\n`);
    return false;
  }

  // Check for canary/test value
  if (accessKeyId.includes('CANARY')) {
    console.log(`\n  ${colors.yellow}⚠️  Using canary/test AWS key${colors.reset}`);
    console.log(`  ${colors.yellow}  In production, use application-specific credentials${colors.reset}\n`);
