  // Validate secret access key
  if (secretAccessKey && secretAccessKey.startsWith('CANARY')) {
    console.log(`  Secret Key: ${masked(secretAccessKey, 8)}`);
    console.log(`  ${colors.yellow}⚠️  Using canary secret key${colors.reset}\n`);
  }

  console.log(`\n✓ AWS credentials format validated${colors.reset}\n`);
