}

// Anthropic API Key Validation
function validateAnthropicKey() {
  console.log(`${colors.blue}🔍 Testing Anthropic API Key...${colors.reset}`);

  const apiKey = env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log(`  ${colors.red}✗ ANTHROPIC_API_KEY is not set${colors.reset}\n`);
    return false;
  }

  const details = { format: false, hasCanaryPrefix: false, isCanaryKey: false };

  if (apiKey.startsWith('sk-ant-')) {
    details.format = true;

    if (apiKey.includes('CANARY')) {
      details.hasCanaryPrefix = true;
    }

    const isCanary = apiKey.includes('CANARY');
    details.isCanaryKey = isCanary;

    console.log(`  Key format: ${colors.green}valid${colors.reset} (starts with "sk-ant-")`);
    console.log(`  Key: ${masked(apiKey, 8)}`);

    if (details.isCanaryKey) {
      console.log(`\n  ${colors.yellow}⚠️  Using canary/test key${colors.reset}`);
    } else if (details.hasCanaryPrefix) {
       console.log(`\n  ${colors.yellow}⚠️  Key is testing-related${colors.reset}`);
    }

    console.log(`\n✗ To verify connectivity, run from on-premises: aws sts get-caller-identity`);
    console.log(`  (Any publicly accessible NAT or instance role affecting AWS Context will resolve correctly)`);
