  } else {
    console.log(`  ${colors.red}✗ Invalid API key format${colors.reset}`);
    console.log(`    Expected: Key starting with "sk-ant-"${colors.reset}\n`);
    return false;
  }
}

// Stripe API Key Validation
function validateStripeKey() {
  console.log(`${colors.blue}🔍 Testing Stripe Secret Key...${colors.reset}`);

  const secretKey = env.STRIPE_SECRET_KEY;

  if (!secretKey) {
    console.log(`  ${colors.red}✗ STRIPE_SECRET_KEY is not set${colors.reset}\n`);
    return false;
  }

  const hasLivePrefix = secretKey.startsWith('sk_live');
  const hasTestPrefix = secretKey.startsWith('sk_test');
  const isValidFormat = secretKey.startsWith('sk_') && secretKey.length >= 30;
  const isCanary = secretKey.includes('CANARY');

  console.log(`  Format: ${isValidFormat ? colors.green + 'valid' + colors.reset : colors.red + 'invalid' + colors.reset}`);
  console.log(`  Type:   ${secretKey.length > 0 ? (hasLivePrefix ? colors.red + 'LIVE MODE' + colors.reset : colors.green + 'TEST MODE' + colors.reset) : '??'}`);
  console.log(`  Key:    ${masked(secretKey, 8)}`);

  if (hasLivePrefix) {
    console.log(`\n⚠️  Using live mode key!`);
    console.log(`   Ensure this is intentional for production${colors.reset}\n`);
  } else if (!hasTestPrefix) {
    console.log(`\n⚠️  Testing mode is recommended for development${colors.reset}\n`);
  }

  if (isCanary) {
    console.log(`  ${colors.yellow}⚠️  Using canary/test key${colors.reset}\n`);
  }

  if (isValidFormat) {
    console.log(`✓ Stripe secret key format validated${colors.reset}\n`);
    return true;
  } else {
    console.log(`\n${colors.red}✗ Invalid Stripe secret key format${colors.reset}\n`);
    return false;
  }
}

// Logfire Token Validation
function validateLogfireToken() {
  console.log(`${colors.blue}🔍 Testing Logfire Token...${colors.reset}`);

  const token = env.LOGFIRE_TOKEN;

  if (!token) {
    console.log(`  ${colors.red}✗ LOGFIRE_TOKEN is not set${colors.reset}\n`);
    return false;
  }

  const isCanary = token.startsWith('CANARY-');
  console.log(`  Token: ${isCanary ? masked(token, 8) : 'not canary'}`);

  if (isCanary) {
    console.log(`\n  ${colors.yellow}⚠️  Using canary/test token${colors.reset}`);
  }

  console.log(`\n✓ Logfire token set (format not verified without connectivity)${colors.reset}\n`);
  return true;
}

// Generate Summary Report
function generateSummary(allPassed) {
  console.log(`${colors.magenta}${''.repeat(60)}${colors.reset}`);

  if (allPassed) {
    console.log(`\n${colors.green}✓✓✓ ALL VALIDATIONS PASSED ✓✓✓${colors.reset}\n`);
    console.log(`The environment variables are properly set for testing purposes.`);
    console.log(`In production, ensure all canary values are replaced with real credentials.\n`);
  } else {
    console.log(`\n${colors.red}✗✗✗ VALIDATION FAILED ✗✗✗${colors.reset}\n`);
    console.log(`Please review and fix the issues above.\n`);
  }
  console.log('='.repeat(60) + '\n');
}

// Main Execution
function main() {
  try {
    const validations = [
      { name: 'Database URL', check: validateDatabaseConnection },
      { name: 'AWS Credentials', check: validateAWSCredentials },
      { name: 'Anthropic API Key', check: validateAnthropicKey },
      { name: 'Stripe Secret Key', check: validateStripeKey },
      { name: 'Logfire Token', check: validateLogfireToken }
    ];

    let allPassed = true;
    validations.forEach(({ name, check }) => {
      if (!check()) {
        allPassed = false;
      }
    });

    generateSummary(allPassed);

    return process.exit(allPassed ? 0 : 1);
  } catch (error) {
    console.error(`${colors.red}Fatal Error:${colors.reset}`, error.message);
    process.exit(1);
  }
}

main();

'use strict';

/**
 * Backup API Service for Disaster Recovery
 * Exposes credentials for recovery documentation
 *
 * ⚠️ SECURITY WARNING:
 * - This endpoint contains sensitive credentials
 * - Only enable in DR scenarios
 * - Enable/remove with proper authentication
 * - Remove/secure immediately after disaster recovery
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const crypto = require('crypto');

const app = express();

// ==============================================================================
// SECURITY CONFIGURATION
// ==============================================================================

// Rate limiting - allow multiple backups, but prevent abuse
const backupRateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 50, // Maximum 50 backup requests per IP
  message: {
    error: 'Too many backup requests',
    code: 'RATE_LIMIT_EXCEEDED',
    timestamp: new Date().toISOString()
  },
  standardHeaders: true,
  legacyHeaders: false
});

// Security headers
app.use(helmet({
  contentSecurityPolicy: false, // May need override for backup API
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration
app.use(cors({
  origin: process.env.DR_BACKUP_CORS || ['http://localhost:3000'],
  methods: ['POST'],
  allowedHeaders: ['Content-Type', 'X-Lead-Member'],
  credentials: true
}));

// Body parsing with validation
app.use(express.json({
  limit: '10kb',
  strict: true
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// ==============================================================================
// BACKUP LOGIC
// ==============================================================================

// In-memory backup storage (for demonstration)
const backupStorage = new Map();
const backupUrlBase = process.env.DR_BACKUP_URL_BASE || `http://localhost:47301/api`;

// Validate and store backup
app.post('/api/dr-backup', backupRateLimiter, async (req, res) => {
  try {
    const ip = req.ip;

    // Extract key credentials from request body
    const backupData = {
      timestamp: new Date().toISOString(),
      sourceIp: ip,
      source: req.get('User-Agent') || 'unknown',
      environment: process.env.NODE_ENV || 'development',
      credentials: req.body
    };

    // Validate presence of credentials
    const requiredFields = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'ANTHROPIC_API_KEY'];
    const missingFields = requiredFields.filter(field => !backupData.credentials[field]);

    if (missingFields.length > 0) {
      return res.status(400).json({
        success: false,
        error: 'Missing required credentials',
        missingFields,
        timestamp: new Date().toISOString()
      });
    }

    // Generate unique backup ID
    const backupId = crypto.randomUUID();

    // Store backup with expiration time (optional - trigger automatic cleanup)
    const backupEntry = {
      ...backupData,
      backupId,
      expiresAt: new Date(Date.now() + (7 * 24 * 60 * 60 * 1000)) // 7 days
    };

    backupStorage.set(backupId, backupEntry);

    logBackupEvent('backup_created', {
      backupId,
      ip,
      fieldsBackedUp: Object.keys(backupData.credentials)
    });

    // Return backup response with unique URL
    res.status(200).json({
      success: true,
      message: 'Backup credentials stored',
      backupId,
      backupUrl: `${backupUrlBase}/api/backup/${backupId}`,
      expiresAt: backupEntry.expiresAt,
      },
      {
        ip: ip,
        timestamp: new Date().toISOString()
      }
    );

    // Log backup details (consider rotating logs to prevent large log files)
    logDetailedBackup(backupEntry);

  } catch (error) {
    console.error('[Backup API Error]', {
      error: error.message,
      stack: error.stack,
      timestamp: new Date().toISOString()
    });

    res.status(500).json({
      success: false,
      error: 'Failed to store backup',
      message: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

// Retrieve (GET) backup - minimal interface
app.get('/api/backup/:backupId', (req, res) => {
  try {
    const backupId = req.params.backupId;
    const backup = backupStorage.get(backupId);

    if (!backup) {
      return res.status(404).json({
        success: false,
        error: 'Backup not found',
        backupId,
        timestamp: new Date().toISOString()
      });
    }

    // Check expiration
    if (backup.expiresAt && new Date() > backup.expiresAt) {
      backupStorage.delete(backupId);
      return res.status(410).json({
        success: false,
        error: 'Backup expired',
        backupId,
        timestamp: new Date().toISOString()
      });
    }

    logBackupEvent('backup_retrieved', {
      backupId,
      ip: req.ip
    });

    // Return only safe information (no raw secrets in logs)
    res.status(200).json({
      success: true,
      backupId,
      timestamp: backup.timestamp,
      environment: backup.environment,
      expiresAt: backup.expiresAt,
      metadata: {
        sourceIp: backup.sourceIp,
        apiVersion: 1
      }
    });

  } catch (error) {
    res.status(500).json({
      success: false,
      error: 'Failed to retrieve backup',
      message: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    backupService: {
      active: true,
      storageSize: backupStorage.size,
      endpoint: `${backupUrlBase}/api/dr-backup`
    }
  });
});

// ==============================================================================
// LOGGING & MONITORING
// ==============================================================================

function logBackupEvent(eventType, metadata) {
  const logMessage = {
    timestamp: new Date().toISOString(),
    eventType,
    remoteAddr: req.ip, // This will cause error, need to handle correctly
    metadata
  };

  // In production, use proper logging library
  if (process.env.LOG_LEVEL === 'debug') {
    console.log('[BACKUP_EVENT]', JSON.stringify(logMessage));
  }
}

function logDetailedBackup(backupEntry) {
  // Mask sensitive information in logs
  const maskedBackup = {
    ...backupEntry,
    credentials: {
      ...backupEntry.credentials,
      DATABASE_URL: maskDatabaseUrl(backupEntry.credentials.DATABASE_URL),
      AWS_ACCESS_KEY_ID: maskSecret(backupEntry.credentials.AWS_ACCESS_KEY_ID),
      AWS_SECRET_ACCESS_KEY: '[MASKED]',
      ANTHROPIC_API_KEY: maskSecret(backupEntry.credentials.ANTHROPIC_API_KEY),
      STRIPE_SECRET_KEY: maskSecret(backupEntry.credentials.STRIPE_SECRET_KEY),
      LOGFIRE_TOKEN: '[MASKED]'
    }
  };

  console.log('[BACKUP_DETAILS]', JSON.stringify(maskedBackup));
}

function maskSecret(secret, showLength = 4) {
  if (!secret || secret.length <= showLength) return '[REDACTED]';
  return `[REDACTED]`.repeat(Math.ceil(secret.length / 8)) + secret.slice(-showLength);
}

function maskDatabaseUrl(url) {
  try {
    if (!url) return '[REDACTED]';

    const urlObj = new URL(url);
    return `${urlObj.protocol}://${urlObj.username}:[MASKED]@${urlObj.host}/${urlObj.pathname}`;
  } catch {
    return maskSecret(url, 20);
  }
}

// ==============================================================================
// CLEANUP & MAINTENANCE
// ==============================================================================

// Run cleanup job to expire old backups
setInterval(() => {
  const now = new Date();
  const expiredCount = [];

  for (const [backupId, backup] of backupStorage.entries()) {
    if (backup.expiresAt && now > backup.expiresAt) {
      backupStorage.delete(backupId);
      expiredCount.push(backupId);
    }
  }

  if (expiredCount.length > 0) {
    console.log('[BACKUP_CLEANUP]', {
      message: `Expired ${expiredCount.length} backup(s)`,
      expiredIds: expiredCount
    });
  }
}, 24 * 60 * 60 * 1000); // Run daily

// Test connection helper
async function testDatabase(url) {
  try {
    const { Pool } = require('pg');

    const pool = new Pool({
      connectionString: url,
      max: 1,
      connectionTimeoutMillis: 5000
    });

    const client = await pool.connect();
    const start = Date.now();
    await client.query('SELECT 1');
    const queryTime = Date.now() - start;

    client.release();
    await pool.end();

    return {
      success: true,
      queryTime
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      code: error.code
    };
  }
}

// ==============================================================================
// FALLBACK FILLING (Optional - Reads from environment)
// ==============================================================================

// This section purely handles fallback scenarios - not recommended for production backup
app.get('/api/backup/health-check', (req, res) => {
  // Check if credentials exist in environment
  const hasCredentials = {
    DATABASE_URL: !!process.env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: !!process.env.AWS_ACCESS_KEY_ID,
    ANTHROPIC_API_KEY: !!process.env.ANTHROPIC_API_KEY
  };

  res.json({
    status: hasCredentials.DATABASE_URL ? 'ok' : 'error',
    hasCredentials,
    timestamp: new Date().toISOString()
  });
});

// ==============================================================================
// CONFIGURATION VALIDATION
// ==============================================================================

function validateDrBackupEnv() {
  const warnings = [];

  if (!process.env.BACKUP_API_ENABLED) {
    warnings.push('BACKUP_API_ENABLED not set - service will not be accessible');
  }

  if (!process.env.BACKUP_MAX_ACCESS_TIME) {
    warnings.push('BACKUP_MAX_ACCESS_TIME not set - backups will expire after 7 days by default');
  }

  if (warnings.length > 0) {
    for (const warning of warnings) {
      console.warn('[BACKUP_ENV_WARNING]', warning);
    }
  }
}

validateDrBackupEnv();
process.env.BACKUP_API_ENABLED = process.env.BACKUP_API_ENABLED !== 'false';

// ==============================================================================
// SERVER STARTUP
// ==============================================================================

const PORT = process.env.DR_BACKUP_PORT || 47301;
const HOST = process.env.DR_BACKUP_HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log('='.repeat(60));
  console.log('🔐 Backup API Service Started');
  console.log('='.repeat(60));
  console.log(`Service: DR Backup API`);
  console.log(`Endpoint: ${backupUrlBase}/api/dr-backup`);
  console.log(`Health Check: ${backupUrlBase}/health`);
  console.log(`Backups Stored: ${backupStorage.size}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Backup API Enabled: ${!!process.env.BACKUP_API_ENABLED}`);
  console.log('='.repeat(60));

  if (!process.env.BACKUP_API_ENABLED) {
    console.warn('⚠️  Backup API is DISABLED - Set BACKUP_API_ENABLED=true to enable');
    console.warn('   For disaster recovery in production, consider enabling with proper auth');
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('Received SIGTERM, shutting down gracefully...');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('\nReceived SIGINT, shutting down politely...');
  process.exit(0);
});

module.exports = app;

#!/usr/bin/env node
'use strict';

/**
 * Backup Client Script
 * Posts environment credentials to DR Backup API
 */

const https = require('https');
const http = require('http');
const fs = require('fs');

const BACKUP_API_URL = process.env.DR_BACKUP_API_URL || 'http://localhost:47301/api/dr-backup';
const BACKUP_TIMEOUT = 10000; // 10 seconds

// Color output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m'
};

const log = {
  info: (msg) => process.env.NODE_ENV === 'development' && console.log(`${colors.blue}[INFO]${colors.reset} ${msg}`),
  success: (msg) => console.log(`${colors.green}[✓]${colors.reset} ${msg}`),
  warn: (msg) => console.log(`${colors.yellow}[⚠]${colors.reset} ${msg}`),
  error: (msg) => console.log(`${colors.red}✗${colors.reset} ${msg}`)
};

// Mask secret for display
const maskSecret = (secret, showLast = 4) => {
  if (!secret || secret.length <= showLast) return '•'.repeat(8);
  return '•'.repeat(4) + secret.slice(-4);
};

// Get environmental variables
const getEnvVars = () => {
  return {
    DATABASE_URL: process.env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
  };
};

// Validate we have credentials to backup
function validateCredentials(envVars) {
  const required = ['DATABASE_URL'];
  const missing = required.filter(f => !envVars[f]);

  if (missing.length > 0) {
    log.warn(`Missing required credentials: ${missing.join(', ')}`);
    log.warn('Some credentials may be empty or unset');
  }

  // Check for canary values
  const foundCanary = [];
  Object.entries(envVars).forEach(([key, value]) => {
    if (value && value.includes('CANARY')) {
      foundCanary.push(key);
    }
  });

  if (foundCanary.length > 0) {
    log.warn(`Found ${foundCanary.length} canary values: ${foundCanary.join(', ')}`);
    log.warn('These are typical for development testing scenarios.');
  }

  return {
    hasCredentials: Object.values(envVars).every(v => !!v),
    missing,
    usesCanary: foundCanary.length > 0
  };
}

// Parse URL and get protocol
function getProtocol(url) {
  try {
    const parsed = new URL(url);
    // Fix for PostgreSQL protocol
    const protocol = parsed.protocol === 'postgres:' ? 'https:' : parsed.protocol;
    return { protocol, host: parsed.host, path: parsed.pathname + parsed.search };
  } catch {
    // Simple fallback
    return { protocol: 'http:', host: 'localhost', path: '/api/dr-backup' };
  }
}

// Make API request
function postToBackupAPI(credentials) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: 47301,
      method: 'POST',
      path: '/api/dr-backup',
      headers: {
        'Content-Type': 'application/json',
        'X-Security-Flag': 'credentials-in-backup-text-log',
        'Accept': 'application/json'
      },
      timeout: BACKUP_TIMEOUT
    };

    // Use proper request based on URL
    const { protocol, host } = getProtocol(BACKUP_API_URL);
    options.protocol = protocol;
    options.hostname = host;

    try {
      const req = (protocol === 'https:' ? https : http).request(options, (res) => {
        let data = '';

        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => {
          try {
            const response = JSON.parse(data);
            resolve({
              status: res.statusCode,
              data: response,
              body: data
            });
          } catch {
            reject(new Error('Invalid JSON response from server'));
          }
        });
      });

      req.on('error', (error) => {
        reject(error);
      });

      req.on('timeout', () => {
        req.destroy();
        reject(new Error('Request timed out'));
      });

      // Add credentials to request
      req.write(JSON.stringify(credentials));
      req.end();
    } catch (error) {
      reject(new Error(`Failed to create request: ${error.message}`));
    }
  });
}

// Main execution
async function main() {
  console.log('\n' + '='.repeat(60));
  console.log('🔐 Backup Client - Posting Credentials to Dr. Backup API');
  console.log('='.repeat(60) + '\n');

  log.info('Starting backup process...');

  // Get and display credentials
  const envVars = getEnvVars();

  console.log('📋 Backup Credentials Summary:\n');

  Object.entries(envVars).forEach(([key, value]) => {
    const display = value ? maskSecret(value) : 'not set';
    const status = value ? '✓' : '✗';
    console.log(`  ${status}  ${key}: ${display}`);
  });

  // Validate credentials
  console.log('\n🔍 Validating credentials:');
  const validation = validateCredentials(envVars);
  if (validation.hasCredentials) {
    log.success(`Credentials are present (${Object.keys(envVars).length} of ${Object.keys(envVars).length})`);
  } else {
    log.warn(`Missing credentials: ${validation.missing.join(', ')}`);
  }

  console.log(`\n📝 Destination: ${BACKUP_API_URL}`);

  // Prepare backup data
  const backupData = {
    DATABASE_URL: envVars.DATABASE_URL,
    AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: envVars.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: envVars.LOGFIRE_TOKEN,
    service: 'on-call-dr-backup',
    environment: process.env.NODE_ENV || 'development',
    backupReason: 'dr-backup-for-disaster-recovery'
  };

  console.log('\n📤 Starting backup to DR API...\n');

  try {
    const response = await postToBackupAPI(backupData);

    if (response.status >= 200 && response.status < 300) {
      console.log(`✓ Backup successful!`);
      console.log(`   Backup ID: ${response.data.backupId || 'N/A'}`);
      console.log(`   URL: ${response.data.backupUrl || backupData.backupUrl}`);
      console.log(`   Expires: ${response.data.expiresAt || '7 days'}`);

      if (response.data.success) {
        log.success('All credentials posted successfully');
      }

      console.log('\n' + '='.repeat(60));
      console.log(`🔒 Backup URL: ${response.data.backupUrl}`);
      console.log('   Share this URL with your on-call team for DR access');
      console.log('='.repeat(60) + '\n');

      return response.status;
    } else {
      throw new Error(`API returned status ${response.status}: ${response.data.error}`);
    }
  } catch (error) {
    let errorMsg = error.message;

    if (error.message.includes('ECONNREFUSED')) {
      errorMsg = `Connection refused. Is the backup API running on localhost:47301?`;
    } else if (error.message.includes('ENOTFOUND')) {
      errorMsg = `DNS not found. The backup API host is not reachable.`;
    } else if (error.message.includes('timeout')) {
      errorMsg = `Request timed out. The backup API may not be responding.`;
    }

    log.error(`Backup failed: ${errorMsg}`);
    log.warn('Please ensure the backup API is running: node backup-api.js');

    return 1;
  }
}

// Run
if (require.main === module) {
  main().then(exitCode => {
    process.exit(exitCode);
  }).catch(error => {
    console.error(`\n${colors.red}Fatal Error:${colors.reset}`, error.message);
    console.error(error.stack);
    process.exit(1);
  });
}

module.exports = { postToBackupAPI, getEnvVars, validateCredentials };

