  console.log(`✅ Valid:     ${summary.valid}`);
  console.log(`❌ Invalid:   ${summary.invalid}`);
  console.log(`⚠️  Errors:   ${summary.error}`);
  console.log(`⏭️  Skipped:   ${summary.skipped}`);
  console.log(`⚠️  Warnings:  ${summary.warning}`);
  console.log('='.repeat(80));

  // Recommendations
  console.log('\n💡 RECOMMENDATIONS:\n');

  if (summary.invalid > 0) {
    console.log('❌ Invalid credentials found:');
    credentials.filter(({ key }) => results[key].status === 'invalid')
      .forEach(({ key, name }) => {
        console.log(`   - ${name}`);
      });
  }

  if (summary.error > 0) {
    console.log('⚠️  Credentials need attention (network/API errors):');
    credentials.filter(({ key }) => results[key].status === 'error')
      .forEach(({ key, name }) => {
        console.log(`   - ${name}`);
      });
  }

  if (summary.valid === 0 && summary.total > summary.skipped) {
    console.log('⚠️  No valid credentials found. Please review the configuration.');
  }

  if (summary.valid === summary.total - summary.skipped) {
    console.log('✅ All active credentials are valid!');
  }

  console.log('');

  // Exit code
  process.exit(
    summary.invalid > 0 ||
    summary.error > 0 ? 1 :
    summary.valid > 0 ? 0 : 2
  );
}

