// Helper function to check HTTP endpoints
function checkHTTPS(url, headers = {}, maxRedirects = 3) {
  return new Promise((resolve) => {
    const urlObj = new URL(url);

    const options = {
      hostname: urlObj.hostname,
      port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
      path: urlObj.pathname + urlObj.search,
      method: 'GET',
      headers: {
        ...headers,
        'User-Agent': 'CredentialValidator/1.0',
      },
      timeout: 10000
    };

    const protocol = urlObj.protocol === 'https:' ? https : http;
    const req = protocol.request(options, (res) => {
      let data = '';

      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const response = {
            status: res.statusCode,
            headers: res.headers,
            body: data.length > 0 ? JSON.parse(data) : data
          };
          resolve(response);
        } catch (e) {
          resolve({
            status: res.statusCode,
            headers: res.headers,
            body: data,
            error: 'Failed to parse response',
            rawError: e.message
          });
        }
      });
    });

    req.on('error', (error) => {
      resolve({
        error: 'Connection failed',
        message: error.message,
        code: error.code
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({
        error: 'Request timeout',
        message: 'The request timed out after 10 seconds'
      });
    });

    req.write(JSON.stringify({}), () => {});
    req.end();
  });
}

