        statusCode: 403
      };
    } else if (response.status === 200) {
      results.stripe = {
        status: 'valid',
        message: 'Stripe credentials are valid',
        data: response.body
      };
    } else {
      results.stripe = {
        status: 'error',
        message: `Unexpected status code: ${response.status}`,
        statusCode: response.status
      };
    }
  } catch (error) {
    results.stripe = {
      status: 'error',
      message: 'Network error while testing Stripe API',
      error: error.message
    };
  }
}

// Test 5: Logfire
async function testLogfire() {
  console.log('📌 Testing Logfire Token...\n');

  const token = envVars.LOGFIRE_TOKEN;

  if (!token) {
    results.logfire = { status: 'skipped', message: 'LOGFIRE_TOKEN not found' };
    return;
  }

  console.log(`Token (first 8 chars): ${token.substring(0, 8)}...`);
  console.log(`Testing Logfire API info endpoint...`);

  try {
    // Logfire API endpoint
    const logfireUrl = 'https://api.logfire.ai/info';

    const response = await checkHTTPS(logfireUrl, {
      'Authorization': `Bearer ${token}`
    });

    if (response.error) {
      results.logfire = {
        status: 'error',
        message: response.error,
        statusCode: response.status
      };
    } else if (response.status === 401) {
      results.logfire = {
        status: 'invalid',
        message: 'Authentication failed - Invalid token',
        statusCode: 401
      };
    } else if (response.status === 403) {
      results.logfire = {
        status: 'invalid',
        message: 'Access denied - Token may be expired or revoked',
        statusCode: 403
      };
    } else if (response.status === 200) {
      try {
        const resp = JSON.parse(response.body);
        results.logfire = {
          status: 'valid',
          message: 'Logfire token is active',
          info: resp
        };
      } catch (e) {
        results.logfire = {
          status: 'success',
          message: 'Authentication successful (response parsing issue)',
          rawStatus: response.status
        };
      }
    } else {
      results.logfire = {
        status: 'warning',
        message: `Unexpected status code: ${response.status}`,
        statusCode: response.status
      };
    }
  } catch (error) {
    results.logfire = {
      status: 'error',
      message: 'Network error while testing Logfire',
      error: error.message
    };
  }
}

// Main execution
async function runTests() {
  try {
    // Test database format (connection test requires a driver)
    await testDatabase();

    // Test AWS
    await testAWS();

    // Test Anthropic
    await testAnthropic();

    // Test Stripe
