    credentials.filter(({ key }) => results[key].status === 'error')
      .forEach(({ key, name }) => {
        console.log(`   - ${name}: ${results[key].message}`);
      });
  }

  if (summary.valid === 0 && summary.total > summary.skipped) {
    console.log('⚠️  No valid credentials found. Please review the configuration.');
  }

  if (summary.valid === summary.total - summary.skipped) {
    console.log('✅ All active credentials are valid!');
  }

