#!/usr/bin/env node

/**
 * Disaster Recovery Backup Script
 * Posts current credentials to http://localhost:47301/api/dr-backup
 */

const fs = require('fs');
const https = require('https');
const http = require('http');
const { URL } = require('url');
const crypto = require('crypto');

// Load environment variables from .env.test
let envVars = {};
const envPath = '.env.test';

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  envContent.split('\n').forEach(line => {
    if (line.trim() && !line.startsWith('#')) {
      const [key, ...valueParts] = line.split('=');
      if (key && valueParts.length > 0) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  });
} else {
  console.error('❌ Error: .env.test file not found');
  console.log('Please ensure .env.test exists in the current directory\n');
  process.exit(1);
}

console.log('📦 Disaster Recovery Backup System');
console.log('==================================\n');

// Create backup payload
const backupData = {
  metadata: {
    system: 'credential-backup',
    generated_at: new Date().toISOString(),
    generated_by: 'node-send-dr-backup.js',
    version: '1.0',
    environment: 'test'
  },
  credentials: {
    database: {
      url: envVars.DATABASE_URL,
      type: 'postgresql',
      is_canary: envVars.DATABASE_URL && envVars.DATABASE_URL.includes('CANARY'),
      // Redact password in output but include for reference
      masked_url: maskCredentials(envVars.DATABASE_URL)
    },
    aws: {
      access_key_id: {
        value: envVars.AWS_ACCESS_KEY_ID,
        is_canary: envVars.AWS_ACCESS_KEY_ID && envVars.AWS_ACCESS_KEY_ID.includes('CANARY')
      },
      secret_access_key: {
        is_canary: envVars.AWS_SECRET_ACCESS_KEY && envVars.AWS_SECRET_ACCESS_KEY.includes('CANARY'),
        // Never log actual secret even in backup
      }
    },
    anthropic: {
      api_key: {
        value: envVars.ANTHROPIC_API_KEY,
        is_canary: envVars.ANTHROPIC_API_KEY && !envVars.ANTHROPIC_API_KEY.includes('sk-ant-') // Could be a genuine key
      }
    },
    stripe: {
      secret_key: {
        value: envVars.STRIPE_SECRET_KEY,
        is_canary: envVars.STRIPE_SECRET_KEY && envVars.STRIPE_SECRET_KEY.includes('CANARY')
      },
      masked_value: envVars.STRIPE_SECRET_KEY ? maskStripeKey(envVars.STRIPE_SECRET_KEY) : null
    },
    logfire: {
      token: {
        is_canary: envVars.LOGFIRE_TOKEN && envVars.LOGFIRE_TOKEN.includes('CANARY'),
        // Don't log the token value
      }
    }
  },
  security: {
    checksum: generateChecksum(backupData),
    purpose: 'Disaster Recovery - Emergency Access Only',
    usage_details: 'Use this backup only when the vault is unavailable.',
    tags: ['disaster-recovery', 'emergency', 'credential-backup'],
    expiration_warning: 'Credentials should be rotated immediately after vault restoration'
  }
};

function maskCredentials(url) {
  if (!url) return url;

  try {
    const urlObj = new URL(url);
    const password = urlObj.password;
    if (password) {
      return urlObj.protocol + '//' + urlObj.username + ':***@' + urlObj.hostname + urlObj.pathname + urlObj.search;
    }
    return url;
  } catch (e) {
    return url; // Return original if parsing fails
  }
}

function maskStripeKey(key) {
  if (!key) return null;
  if (key.startsWith('sk_') && key.length > 10) {
    return key.substring(0, 8) + '********' + key.substring(key.length - 4);
  }
  return key;
}

function generateChecksum(data) {
  // Generate a SHA-256 checksum of the JSON data
