console.log('⏳ Sending...');

// Write local backup immediately
const localBackupPath = './dr-backup-' + Date.now() + '.json';
fs.writeFileSync(localBackupPath, jsonString, 'utf8');

// Send to remote endpoint
sendBackup(backupUrl, jsonString, (statusCode, responseData) => {
  console.log('✅ Backup sent!\n');

  if (!statusCode) {
    console.error('❌ Network Error:', responseData);
    console.error('Remote endpoint (http://localhost:47301) may not be running');
    process.exit(1);
  }

  console.log('📊 SERVER RESPONSE:');
  console.log('-----------------');
  console.log(`Status: ${statusCode} ${statusCode >= 200 && statusCode < 300 ? '✅' : '❌'}`);
  console.log(`Checksum: ${backupData.security.checksum.substring(0, 16)}...`);
