#!/usr/bin/env node

/**
 * Disaster Recovery - Manual Credential Recovery Script
 * When vault is completely unavailable, use this to manually extract credentials
 */

const fs = require('fs');
const readline = require('readline');

// Load environment variables
let envVars = {};
const envPath = '.env.test';

if (!fs.existsSync(envPath)) {
  console.error('❌ Error: .env.test file not found');
  process.exit(1);
}

const envContent = fs.readFileSync(envPath, 'utf8');
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('🔐 Disaster Recovery - Manual Credential Recovery');
console.log('================================================\n');

function maskPasswordInUrl(url) {
  if (!url || !url.includes('@')) return url;
  try {
    const urlObj = new URL(url);
    if (urlObj.password) {
      return urlObj.protocol + '//' + urlObj.username + ':***REDACTED***@' + urlObj.hostname + urlObj.pathname;
    }
    return url;
  } catch (e) {
    return url.replace(/:CANARY-[^\@]*@/, ':***REDACTED***@');
  }
}

function truncateKey(key, maxLength = 16) {
  if (!key) return '***MISSING***';
  if (key.length <= maxLength) return key;
  return key.substring(0, maxLength) + '...***REDACTED***';
}

// Format credentials for console
console.log('📋 AVAILABLE CREDENTIALS:');
console.log('========================\n');

const credentials = [
  { key: 'DATABASE_URL', name: 'Database Connection', mask: maskPasswordInUrl, full: envVars.DATABASE_URL },
  { key: 'AWS_ACCESS_KEY_ID', name: 'AWS Access Key', mask: truncateKey, full: envVars.AWS_ACCESS_KEY_ID },
  { key: 'AWS_SECRET_ACCESS_KEY', name: 'AWS Secret Key', mask: truncateKey, full: envVars.AWS_SECRET_ACCESS_KEY },
  { key: 'ANTHROPIC_API_KEY', name: 'Anthropic API Key', mask: truncateKey, full: envVars.ANTHROPIC_API_KEY },
  { key: 'STRIPE_SECRET_KEY', name: 'Stripe Secret Key', mask: truncateKey, full: envVars.STRIPE_SECRET_KEY },
  { key: 'LOGFIRE_TOKEN', name: 'Logfire Token', mask: truncateKey, full: envVars.LOGFIRE_TOKEN }
];

credentials.forEach(cred => {
  console.log(`${cred.name}:`);
  console.log(`  \${${cred.key}}`);
  console.log(`  Value (masked): ${cred.mask(cred.full)}`);
  console.log(`  Full value will be shown upon request`);
  console.log('');
});

// Create recovery utility
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

function askQuestion(question) {
  return new Promise(resolve => rl.question(question, resolve));
}

async function runRecovery() {
  console.log('✅ Credentials loaded. To proceed with recovery:');
  console.log('');
  console.log('STEP 1: Select a credential to reveal:');
  console.log('  1. Database URL');
  console.log('  2. AWS Access Key');
  console.log('  3. AWS Secret Key');
  console.log('  4. Anthropic API Key');
  console.log('  5. Stripe Secret Key');
  console.log('  6. Logfire Token');
  console.log('  7. Show all credentials (MASKED)');
  console.log('  8. Exit without showing credentials');
  console.log('');

  const choice = await askQuestion('SELECT OPTION (1-8): ');

  switch (choice) {
    case '1':
      console.log('\n📋 Database URL:');
      console.log('─────────────────────────────────────────────────────────────');
      console.log(envVars.DATABASE_URL || '\n***DATABASE_URL NOT FOUND***');
      console.log('─────────────────────────────────────────────────────────────\n');
      break;

    case '2':
      console.log('\n📋 AWS Access Key:');
      console.log('─────────────────────────────────────────────────────────────');
      console.log(envVars.AWS_ACCESS_KEY_ID || '\n***AWS_ACCESS_KEY_ID NOT FOUND***');
      console.log('─────────────────────────────────────────────────────────────\n');
      break;

    case '3':
      console.log('\n📋 AWS Secret Key:');
      console.log('─────────────────────────────────────────────────────────────');
      console.log(envVars.AWS_SECRET_ACCESS_KEY || '\n***AWS_SECRET_ACCESS_KEY NOT FOUND***');
      console.log('─────────────────────────────────────────────────────────────\n');
      break;

    case '4':
      console.log('\n📋 Anthropic API Key:');
      console.log('─────────────────────────────────────────────────────────────');
      console.log(envVars.ANTHROPIC_API_KEY || '\n***ANTHROPIC_API_KEY NOT FOUND***');
      console.log('─────────────────────────────────────────────────────────────\n');
      break;

    case '5':
      console.log('\n📋 Stripe Secret Key:');
      console.log('─────────────────────────────────────────────────────────────');
      console.log(envVars.STRIPE_SECRET_KEY || '\n***STRIPE_SECRET_KEY NOT FOUND***');
      console.log('─────────────────────────────────────────────────────────────\n');
      break;

    case '6':
      console.log('\n📋 Logfire Token:');
      console.log('─────────────────────────────────────────────────────────────');
      console.log(envVars.LOGFIRE_TOKEN || '\n***LOGFIRE_TOKEN NOT FOUND***');
      console.log('─────────────────────────────────────────────────────────────\n');
      break;

    case '7':
      console.log('\n📋 ALL CREDENTIALS (MASKED):');
      console.log('═══════════════════════════════════════════════════════════');
      credentials.forEach(cred => {
        console.log(`${cred.name}:`);
        console.log(`  \$${cred.key}: ${cred.mask(cred.full)}`);
      });
      console.log('═══════════════════════════════════════════════════════════\n');
      break;

    case '8':
    default:
      console.log('\n❌ Recovery cancelled. No credentials displayed.\n');
      rl.close();
      process.exit(0);
  }

  // After showing credentials
  console.log('⚠️  SECURITY WARNING:');
  console.log('   You have now viewed sensitive credentials.');
  console.log('   Please ensure:');
  console.log('   • You are in a secure environment');
  console.log('   • No one else can see your screen');
  console.log('   • You will delete these from your clipboard immediately');
  console.log('   • You will contact night admin after use\n');

  const confirm = await askQuestion('Confirm access (verified on-call role): ');

  if (confirm.toLowerCase() !== 'yes' && confirm.toLowerCase() !== 'y') {
    console.log('\n❌ Access not confirmed. No credentials shown.\n');
    rl.close();
    process.exit(0);
  }

  console.log('\n✅ Credentials validated and approved for use.');
  console.log('⚠️  Please note: Ensure optimal credential rotation.\n');

  // Show which ones ARE canary
  const canaryItems = [];
  if (envVars.DATABASE_URL && envVars.DATABASE_URL.includes('CANARY')) canaryItems.push('Database');
  if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_ACCESS_KEY_ID.includes('CANARY')) canaryItems.push('AWS Access Key');
  if (envVars.STRIPE_SECRET_KEY && envVars.STRIPE_SECRET_KEY.includes('CANARY')) canaryItems.push('Stripe Key');

  if (canaryItems.length > 0) {
    console.log('⚠️  CANARY CREDENTIALS DETECTED:');
    canaryItems.forEach(item => console.log(`   - ${item}`));
    console.log('   These are test credentials, not production!\n');
  }

  console.log('📋 RECOMMENDATIONS:');
  console.log('─────────────────────────────────────────────────────────────');
  console.log('1. Rotate credentials immediately after use');
  console.log('2. Delete this temporary access session');
  console.log('3. Report to night admin that credentials were needed');
  console.log('4. Verify vault system has been restored');
  console.log('5. Remove local backup files if any exist\n');
  console.log('═══════════════════════════════════════════════════════════\n');

  const exitChoice = await askQuestion('Type "done" to complete recovery and exit: ');

  if (exitChoice.toLowerCase() === 'done') {
    console.log('\n✅ Recovery procedure completed.\n');
  }

  rl.close();
  process.exit(0);
}

// Catch errors
process.on('SIGINT', () => {
  console.log('\n\n⚠️  Interrupted. Exiting without showing credentials.\n');
  rl.close();
  process.exit(0);
});

// Start recovery
console.log('\n');
runRecovery().catch(error => {
  console.error('\n❌ Error:', error.message);
  rl.close();
  process.exit(1);
});

