// Test script to verify environment variable credentials
// This script checks connectivity and validates API keys

const { URL } = require('url');
const dns = require('dns').promises;
const https = require('https');
const http = require('http');
const mysql = require('mysql2/promise');
const { Pool } = require('pg');
const Stripe = require('stripe');

// Configure logging
const log = {
  info: (msg) => console.log(`[INFO] ${msg}`),
  success: (msg) => console.log(`✅ [SUCCESS] ${msg}`),
  warning: (msg) => console.log(`⚠️  [WARNING] ${msg}`),
  error: (msg) => console.log(`❌ [ERROR] ${msg}`),
  section: (msg) => console.log(`\n${'='.repeat(60)}`);
};

// Test result summary
const results = {
  database: { status: 'pending', message: '' },
  postgresql: { status: 'pending', message: '' },
  aws: { status: 'pending', message: '' },
  anthropic: { status: 'pending', message: '' },
  stripe: { status: 'pending', message: '' },
  logfire: { status: 'pending', message: '' },
};

/**
 * Test DNS resolution
 */
async function testDNS(hostname) {
  log.info(`Testing DNS resolution for ${hostname}...`);
  try {
    await dns.lookup(hostname);
    log.success(`DNS resolution successful for ${hostname}`);
    return true;
  } catch (error) {
    log.error(`DNS resolution failed for ${hostname}: ${error.message}`);
    return false;
  }
}

/**
 * Test HTTP endpoint with method and headers
 */
async function testHTTP(url, method = 'GET', statusCode = 200, headers = {}, maxRedirects = 5) {
  try {
    return new Promise((resolve, reject) => {
      let redirects = 0;

      const makeRequest = (currentUrl) => {
        const urlObj = new URL(currentUrl);
        const protocol = urlObj.protocol === 'https:' ? https : http;

        const options = {
          hostname: urlObj.hostname,
          port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
          path: urlObj.pathname + urlObj.search,
          method,
          headers: {
            'User-Agent': 'Environment-Verification-Script/1.0',
            Accept: 'application/json',
            ...headers,
            ...(urlObj.username && urlObj.password && {
              Authorization: `Basic ${Buffer.from(`${urlObj.username}:${urlObj.password}`).toString('base64')}`
            })
          },
          timeout: 10000 // 10 second timeout
        };

        const req = protocol.request(options, (res) => {
          log.info(`Response from ${currentUrl}: ${res.statusCode}`);

          let data = '';

          res.on('data', (chunk) => {
            data += chunk;
          });

          res.on('end', () => {
            try {
              if (res.statusCode === statusCode || (res.statusCode >= 200 && res.statusCode < 300)) {
                log.success(`✓ ${currentUrl} is accessible (Status: ${res.statusCode})`);
                if (data && data.length < 500) {
                  log.info(`Response: ${data.substring(0, 100)}`);
                }
                resolve({ success: true, statusCode: res.statusCode, data });
              } else {
                log.warning(`✗ ${currentUrl} returned ${res.statusCode} (expected ${statusCode})`);
                resolve({ success: false, statusCode: res.statusCode, data });
              }
            } catch (e) {
              log.warning(`Response parsed but failed validation: ${e.message}`);
              resolve({ success: true, statusCode: res.statusCode, data });
            }
          });
        });

        req.on('error', (error) => {
          log.error(`Request failed for ${currentUrl}: ${error.message}`);
          reject(error);
        });

        req.on('timeout', () => {
          req.destroy();
          log.error(`Request timed out for ${currentUrl}`);
          reject(new Error('Request timeout'));
        });

        req.on('close', () => {
          // Check if we should follow redirect
          if (res.statusCode >= 300 && res.statusCode < 400 && redirects < maxRedirects) {
            const location = res.headers.location;
            if (location) {
              redirects++;
              log.info(`Following redirect to ${location}`);
              // Handle relative URL
              const finalUrl = location.startsWith('http') ? location : new URL(location, currentUrl).href;
              makeRequest(finalUrl);
            }
          }
        });

        req.write(JSON.stringify({ test: 'test' }));
        req.end();
      };

      makeRequest(url);
    });
  } catch (error) {
    log.error(`HTTP test failed: ${error.message}`);
    return { success: false, error: error.message };
  }
}

/**
 * Test PostgreSQL connection
 */
async function testPostgreSQL() {
  const dbUri = process.env.POSTGRES_URL || process.env.DATABASE_URL;

  if (!dbUri) {
    log.info('Skipping PostgreSQL test - no DATABASE_URL found');
    return;
  }

  log.section('Testing PostgreSQL Connection');
  log.info(`Database URL: ${dbUri.replace(/:[^:@]*@/, ':****@')}`);

  try {
    const urlObj = new URL(dbUri);

    log.info('Testing DNS resolution for database host...');
    const dnsResolved = await testDNS(urlObj.hostname);

    if (!dnsResolved) {
      results.postgresql.status = 'failed';
      results.postgresql.message = 'DNS resolution failed';
      return;
