async function testHTTP(url, method = 'GET', statusCode = 200, headers = {}, maxRedirects = 5) {
  return new Promise((resolve) => {
    let redirects = 0;

    const makeRequest = (currentUrl) => {
      const urlObj = new URL(currentUrl);
      const protocol = urlObj.protocol === 'https:' ? https : http;

      const options = {
        hostname: urlObj.hostname,
        port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
        path: urlObj.pathname + urlObj.search,
        method,
        headers: {
          'User-Agent': 'Environment-Verification-Script/1.0',
          Accept: 'application/json',
          ...headers,
        },
        timeout: 10000 // 10 second timeout
      };

      const req = protocol.request(options, (res) => {
        log.info(`Response from ${currentUrl}: ${res.statusCode}`);

        let data = '';

        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => {
          if (res.statusCode === statusCode || (res.statusCode >= 200 && res.statusCode < 300)) {
            log.success(`✓ ${currentUrl} is accessible (Status: ${res.statusCode})`);
            resolve({ success: true, statusCode: res.statusCode, data });
          } else {
            log.warning(`✗ ${currentUrl} returned ${res.statusCode} (expected ${statusCode})`);
            resolve({ success: false, statusCode: res.statusCode, data });
          }
        });
      });

      req.on('error', (error) => {
        log.error(`Request failed for ${currentUrl}: ${error.message}`);
        resolve({ success: false, error: error.message });
      });

      req.on('timeout', () => {
        req.destroy();
        log.error(`Request timed out for ${currentUrl}`);
        resolve({ success: false, error: 'Request timeout' });
      });

      req.on('close', () => {
        // Handle redirect
        if (res.statusCode >= 300 && res.statusCode < 400 && redirects < maxRedirects) {
          const location = res.headers.location;
          if (location) {
            redirects++;
            log.info(`Following redirect to ${location}`);
            const finalUrl = location.startsWith('http') ? location : new URL(location, currentUrl).href;
            makeRequest(finalUrl);
          }
        }
      });

      req.write(JSON.stringify({ test: 'test' }));
      req.end();
    };

    makeRequest(url);
  });
}

