#!/usr/bin/env node

/**
 * Test script to verify credentials from .env.test
 * Checks database connectivity and API endpoint responses
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[36m',
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logSection(title) {
  console.log(`\n${colors.blue}═══ ${title} ═══${colors.reset}`);
}

// Parse environment variables from .env.test
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    log(`Error: ${filePath} not found`, 'red');
    process.exit(1);
  }

  const envContent = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  envContent.split('\n').forEach((line) => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        let value = match[2];
        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        envVars[match[1]] = value;
      }
    }
  });

  return envVars;
}

// Test PostgreSQL connection
function testPostgreSQL(dbUrl) {
  logSection('Testing PostgreSQL Connection');

  return new Promise((resolve) => {
    const url = new URL(dbUrl);

    // Parse connection parameters
    const protocol = url.protocol.replace(':', '');
    const auth = `${url.username}:${url.password}`;
    const host = url.hostname;
    const port = url.port || (protocol === 'postgresql' ? 5432 : 5433);

    log(`Host: ${host}:${port}`, 'blue');
    log(`User: ${url.username}`, 'blue');
    log(`Database: ${url.pathname.slice(1)}`, 'blue');

    resolve({ status: 'skipped', reason: 'PostgreSQL connection requires server-side client library' });
  });
}

// Test AWS credentials
function testAWSAPI(accessKeyId, secretKey) {
  logSection('Testing AWS API');

  return new Promise((resolve) => {
    log(`Access Key ID: ${accessKeyId}`, 'blue');
    log(`Secret Key: ${secretKey.substring(0, 10)}...${secretKey.substring(secretKey.length - 4)}`, 'blue');

    resolve({ status: 'skipped', reason: 'AWS API test requires region/domain and additional configuration' });
  });
}

// Test Anthropic API key
function testAnthropicAPI(apiKey) {
  logSection('Testing Anthropic API');

  return new Promise((resolve, reject) => {
    log(`API Key: ${apiKey.substring(0, 15)}...${apiKey.substring(apiKey.length - 4)}`, 'blue');

    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
      timeout: 10000,
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          const response = JSON.parse(data);
          log(`✓ Status: ${res.statusCode} - Valid API key`, 'green');

          if (response && response.type && response.type === 'error') {
            log(`⚠ API responded with error (but key is valid):`, 'yellow');
            log(`  - Type: ${response.type}`, 'yellow');
            if (response.error) {
              log(`  - Message: ${response.error.message}`, 'yellow');
            }
          }

          resolve({ status: 'valid', code: res.statusCode });
        } else {
          log(`✗ Status: ${res.statusCode}`, 'red');
          log(`  Response: ${data.substring(0, 200)}`, 'red');

          try {
            const response = JSON.parse(data);
            if (response.error) {
              log(`  Error: ${response.error.message}`, 'red');
            }
          } catch (e) {
            log(`  Raw response: ${data.substring(0, 200)}`, 'red');
          }

          resolve({ status: 'invalid', code: res.statusCode });
        }
      });
    });

    req.on('error', (error) => {
      log(`✗ Error connecting to API:`, 'red');
      log(`  ${error.message}`, 'red');
      resolve({ status: 'error', error: error.message });
    });

    req.on('timeout', () => {
      req.destroy();
      log(`✗ Request timed out`, 'red');
      resolve({ status: 'timeout' });
    });

    // Send test request
    req.write(JSON.stringify({
      model: 'claude-haiku-2024-05-08',
      max_tokens: 10,
      messages: [{ role: 'user', content: 'Hi' }]
    }));

    req.end();
  });
}

// Test Stripe API key
function testStripeAPI(stripeKey) {
  logSection('Testing Stripe API');

  return new Promise((resolve) => {
    log(`API Key: ${stripeKey.substring(0, 20)}...${stripeKey.substring(stripeKey.length - 4)}`, 'blue');
    log(`  (Format: ${stripeKey.startsWith('sk_live_') ? 'Live' : 'Test'} mode)`, 'blue');

    resolve({ status: 'skipped', reason: 'Stripe API test requires additional logic implementation' });
  });
}

// Test Logfire token
function testLogfireAPI(token) {
  logSection('Testing Logfire API');

  return new Promise((resolve, reject) => {
    log(`Token: ${token.substring(0, 15)}...${token.substring(token.length - 4)}`, 'blue');

    const options = {
      hostname: 'api.logfire.dev',
      port: 443,
      path: '/v1/models',
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
      },
      timeout: 10000,
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          log(`✓ Status: ${res.statusCode} - Valid token`, 'green');
          resolve({ status: 'valid', code: res.statusCode });
        } else {
          log(`✗ Status: ${res.statusCode}`, 'red');
          log(`  Response: ${data.substring(0, 200)}`, 'red');
          resolve({ status: 'invalid', code: res.statusCode });
        }
      });
    });

    req.on('error', (error) => {
      log(`✗ Error connecting to API:`, 'red');
      log(`  ${error.message}`, 'red');
      resolve({ status: 'error', error: error.message });
    });

    req.on('timeout', () => {
      req.destroy();
      log(`✗ Request timed out`, 'red');
      resolve({ status: 'timeout' });
    });

    req.end();
  });
}

// Main execution
async function main() {
  logSection('Credential Validation Tests');
  log('Reading credentials from .env.test...\n', 'blue');

  // Parse environment variables
  const envVars = parseEnvFile(path.join(__dirname, '.env.test'));

  if (Object.keys(envVars).length === 0) {
    log('No credentials found in .env.test or file is empty', 'red');
    process.exit(1);
  }

  log(`Found ${Object.keys(envVars).length} environment variables:\n`, 'blue');
  Object.keys(envVars).sort().forEach((key) => {
    if (envVars[key].length > 30) {
      log(`  ${key}: ${envVars[key].substring(0, 15)}...${envVars[key].substring(envVars[key].length - 10)}`, 'blue');
    } else {
      log(`  ${key}: ${envVars[key]}`, 'blue');
    }
  });

  log('\n', 'reset');

  // Test credentials
  const results = {};

  if (envVars.DATABASE_URL) {
    results.database = await testPostgreSQL(envVars.DATABASE_URL);
  }

  if (envVars.AWS_ACCESS_KEY_ID) {
    results.aws = await testAWSAPI(envVars.AWS_ACCESS_KEY_ID, envVars.AWS_SECRET_ACCESS_KEY);
  }

  if (envVars.ANTHROPIC_API_KEY) {
    results.anthropic = await testAnthropicAPI(envVars.ANTHROPIC_API_KEY);
  }

  if (envVars.STRIPE_SECRET_KEY) {
    results.stripe = await testStripeAPI(envVars.STRIPE_SECRET_KEY);
  }

  if (envVars.LOGFIRE_TOKEN) {
    results.logfire = await testLogfireAPI(envVars.LOGFIRE_TOKEN);
  }

  // Summary
  logSection('Test Summary');

  const passedTests = Object.values(results).filter(r => r.status === 'valid').length;
  const totalTests = Object.keys(results).length;

  if (passedTests === totalTests) {
    log(`✓ All ${totalTests} credential tests passed!`, 'green');
  } else if (passedTests > 0) {
    log(`⚠ {passedTests}/${totalTests} credential tests passed`, 'yellow');
  } else {
    log(`✗ No valid credentials found`, 'red');
  }

  // Detailed results
  log('\nDetailed Results:\n', 'blue');
  Object.entries(results).forEach(([key, result]) => {
    const statusIcon = result.status === 'valid' ? '✓' : (result.status === 'invalid' ? '✗' : '⚠');
    const statusColor = result.status === 'valid' ? 'green' : (result.status === 'invalid' ? 'red' : 'yellow');

    log(`${statusIcon} ${key.toUpperCase()}:`, statusColor);

    if (result.reason) {
      log(`  Status: Skipped - ${result.reason}`, 'yellow');
    } else if (result.error) {
      log(`  Status: Error - ${result.error}`, 'red');
    } else {
      log(`  Status: ${result.status.toUpperCase()} (Code: ${result.code})`, statusColor);
    }
  });

  // Warning about canary values
  if (Object.keys(envVars).some(k => k.includes('CANARY'))) {
    log('\n⚠ WARNING: Found CANARY values in credentials - these appear to be test canary values', 'yellow');
    log('These may not represent real production credentials', 'yellow');
  }

  process.exit(passedTests === totalTests ? 0 : 1);
}

main().catch((error) => {
  log(`Fatal error: ${error.message}`, 'red');
  console.error(error);
  process.exit(1);
});

