          statusCode: res.statusCode,
          body: data,
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    // Send credentials
    req.write(JSON.stringify({
      timestamp: new Date().toISOString(),
      source: 'local',
      service: 'dr-backup',
      credentials: credentials,
    }));

    req.end();
  });
