  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ✅ DI-RECOMMENDED
interface IHealthCheckService {
  check(): Promise<HealthCheckStatus>;
}

class HealthCheckController implements IHealthCheckController {
  public async health(req: Request, res: Response): Promise<void> {
    const status = await this.healthCheckService.check();
    res.status(status.isHealthy ? 200 : 503)
       .json(status);
  }
}
```

### 5. No Service Isolation
**Violation:** Multiple concerns in single controller functions
```javascript
