class Server {
  constructor(port) {
    this.app = express();
    this.port = port;
    this.logger = new AppLogger();
    this.formatter = new ResponseFormatter(this.logger);
    this.dataService = new StaticDataService(this.logger);
  }

  setupRoutes() {
    this.app.get('/health', this.handleHealthCheck.bind(this));
    this.app.get('/users', this.handleUsersGet.bind(this));
  }

  handleHealthCheck(req, res) {
    const result = this.dataService.getHealthCheck();
    const data = this.formatter.ok(result);

    // Return as JSON response
    res.status(200).json(data);
  }

  handleUsersGet(req, res) {
    const users = await this.dataService.getUsers(); // Note: async help needed

    const data = this.formatter.ok(users, 'Users retrieved successfully');
    res.status(200).json(data);
  }

  start() {
