// Secure application with proper error handling and input validation
// Security-focused improvements for production use

const express = require('express');
const helmet = require('helmet');
const morgan = require('morgan');
const { validationResult } = require('express-validator');
const validate = require('express-validator');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Enable security middleware
app.use(helmet());

// Request body parsing with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Logging in development
if (NODE_ENV === 'development') {
  app.use(morgan('dev'));
}

// Input validation middleware
const userSchema = [
  validate.body('email').isEmail().normalizeEmail(),
  validate.body('name').isLength({ min: 1, max: 50 }).trim(),
];

// Custom error handler
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Central error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Log errors in development
  if (NODE_ENV === 'development') {
    res.status(err.statusCode || 500).json({
      success: false,
      error: err.message,
      stack: err.stack,
    });
  } else {
    // In production, don't expose stack traces
    res.status(err.statusCode || 500).json({
      success: false,
      error: 'Internal server error',
    });
  }
});

// Health check endpoint with no input validation required
app.get('/health', asyncHandler(async (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
}));

// Users endpoint with input validation and proper error handling
app.get('/users', asyncHandler(async (req, res) => {
  // Optional: Add query parameter validation
  const { page = '1', limit = '10' } = req.query;

  // Validate query parameters
  if (page < 1 || limit < 1) {
    const error = new Error('Invalid page or limit parameters');
    error.statusCode = 400;
    throw error;
  }

  // Query for users from database (example)
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      success: true,
      data: users,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
      },
    });
  } catch (error) {
    console.error('Database error:', error);
    const dbError = new Error('Failed to retrieve users');
    dbError.statusCode = 500;
    throw dbError;
  }
}));

// Endpoint to create a user with validation
app.post('/users', userSchema, asyncHandler(async (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const validationError = new Error('Validation failed');
    validationError.statusCode = 400;
    validationError.errors = errors.array();
    throw validationError;
  }

  const { email, name } = req.body;

  // Additional business logic validation
  if (!email || !name) {
    const error = new Error('Email and name are required');
    error.statusCode = 400;
    throw error;
  }

  // In a real app, this would save to a database
  // Post-user creation logic here...

  res.status(201).json({
    success: true,
    message: 'User created successfully',
    data: { email, name },
  });
}));

// 404 handler for undefined routes
app.use((req, res) => {
  const error = new Error(`Route ${req.method} ${req.url} not found`);
  error.statusCode = 404;
  throw error;
});

// Start server with error handling
async function startServer() {
  try {
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
    });
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  app.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  app.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

startServer();

