  console.log('They are NOT valid for production deployment.\n');
}

console.log('⚠️  Starting credential validation...\n');

runValidations().catch(console.error);

// Exportable function for external use
module.exports = {
  validateApiKeys: (envVars) => {
    return runValidations();
  },
  testPostgresCredentials,
};

