#!/usr/bin/env node

/**
 * Security Credentials Verification Script
 * Checks connectivity to database and validates API keys
 */

const { URL } = require('url');
const { execSync } = require('child_process');
const https = require('https');

// Load env file
require('dotenv').config({ path: '.env.test', debug: true });

// Log config loading
console.log('='.repeat(70));
console.log('╔════════════════════════════════════════════════════════════════╗');
console.log('║   CREDENTIALS VERIFICATION - Canary/Production Safety Check   ║');
console.log('╚════════════════════════════════════════════════════════════════╝');
console.log('='.repeat(70));
console.log();

// Status tracking
const results = {
  total: 0,
  passed: 0,
  failed: 0,
  warnings: 0,
};

/**
 * Test helper functions
 */
function logTest(name) {
  console.log(`\n📋 Testing: ${name}`);
  process.stdout.write('   → ');
}

function markPassed() {
  results.passed++;
  process.stdout.write('✅ PASS\n');
}

function markFailed(reason) {
  results.failed++;
  process.stdout.write(`❌ FAIL: ${reason}\n`);
}

function markWarning(reason) {
  results.warnings++;
  process.stdout.write(`⚠️  WARN: ${reason}\n`);
}

/**
 * Test 1: Database Connection
 */
function testDatabase() {
  logTest('PostgreSQL Database Connectivity');

  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    markFailed('DATABASE_URL not defined');
    return false;
  }

  try {
    // Parse DB URL
    const parsed = new URL(dbUrl);

    // Check if it's still a test URL
    if (parsed.hostname === 'db.internal') {
      console.log(`   Host: ${parsed.hostname}`);
      markWarning('Database host is internal but connectivity unavailable (expected for non-local testing)');
      return true;
    }

    // Test with psql (requires psql available on system)
    const command = `psql "${dbUrl}" -c "SELECT 1;"`;
    execSync(command, { timeout: 5000, stdio: 'pipe' });

    markPassed();
    return true;
  } catch (error) {
    markFailed(`Connection failed: ${error.message}`);
    return false;
  }
}

/**
 * Test 2: AWS Credentials
 */
function testAWS() {
  logTest('AWS Credentials (Access Key)');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  if (!accessKeyId) {
    markFailed('AWS_ACCESS_KEY_ID not defined');
    return false;
  }

  // Validate format (AWS key ID pattern)
  const expectedPattern = /^AKIA[A-Z0-9]{16}$/;
  if (expectedPattern.test(accessKeyId)) {
    console.log(`   Key ID: REDACTED_AWS_AKID**** (filtered)`);
    markPassed();
    return true;
  } else {
    markFailed(`AWS_ACCESS_KEY_ID has invalid format: ${accessKeyId}`);
    return false;
