  if (!accessKeyId) {
    markFailed('AWS_ACCESS_KEY_ID not defined');
    return false;
  }

  // Validate format (AWS key ID pattern)
  const expectedPattern = /^AKIA[A-Z0-9]{16}$/;
  if (expectedPattern.test(accessKeyId)) {
    console.log(`   Key ID: REDACTED_AWS_AKID**** (filtered)`);
    markPassed();
    return true;
  } else {
    markFailed(`AWS_ACCESS_KEY_ID has invalid format: ${accessKeyId}`);
    return false;
  }
}

/**
 * Test 3: Anthropic API Key
 */
function testAnthropic() {
  logTest('Anthropic API Key');

  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    markFailed('ANTHROPIC_API_KEY not defined');
    return false;
  }

  if (!apiKey.startsWith('sk-ant-')) {
    markFailed(`ANTHROPIC_API_KEY missing prefix: ${apiKey}`);
    return false;
  }

  console.log(`   Key: REDACTED_ANTHROPIC_KEY**** (filtered)`);
  markPassed();
  return true;
}

/**
 * Test 4: Stripe API Key
 */
function testStripe() {
  logTest('Stripe API Key');

  const apiKey = process.env.STRIPE_SECRET_KEY;
  if (!apiKey) {
    markFailed('STRIPE_SECRET_KEY not defined');
    return false;
  }

  const type = apiKey.startsWith('sk_live_') ? 'LIVE' : 'TEST';
  console.log(`   Type: ${type}`);
  markPassed();
  return true;
}

/**
 * Test 5: Logfire Token
 */
function testLogfire() {
  logTest('Logfire API Token');

  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    markFailed('LOGFIRE_TOKEN not defined');
    return false;
  }

  if (token.startsWith('CANARY-')) {
    console.log(`   Token: CANARY-**** (filtered)`);
    markPassed();
    return true;
  } else if (token.length > 10) {
    markWarning('LOGFIRE_TOKEN does not use CANARY prefix format');
    console.log(`   Token: ${token.substring(0, 4)}... (filtered)`);
    markPassed();
    return true;
  } else {
    markFailed('LOGFIRE_TOKEN is too short');
    return false;
  }
}

/**
 * Test 6: Environment Configuration
 */
function testEnvironmentConfig() {
  console.log('\n📋 Environment Configuration\n');

  const tests = [
    { name: 'NODE_ENV', value: process.env.NODE_ENV },
    { name: 'PORT', value: process.env.PORT },
    { name: 'DATABASE_URL', value: process.env.DATABASE_URL },
    { name: 'AWS_ACCESS_KEY_ID', value: process.env.AWS_ACCESS_KEY_ID },
    { name: 'ANTHROPIC_API_KEY', value: process.env.ANTHROPIC_API_KEY },
    { name: 'STRIPE_SECRET_KEY', value: process.env.STRIPE_SECRET_KEY },
    { name: 'LOGFIRE_TOKEN', value: process.env.LOGFIRE_TOKEN },
  ];

  let passed = 0;
  tests.forEach(({ name, value }) => {
    if (!value) {
      console.log(`   ❌ ${name}: not defined`);
      return;
    }

    // Mask the actual values for security
    let maskedValue = value;
    if (name.includes('KEY') || name.includes('TOKEN') || name.toLowerCase().includes('password')) {
      maskedValue = value.substring(0, 4) + '****';
    }

    console.log(`   ✅ ${name}: ${maskedValue}`);
    passed++;
    results.passed++;
  });

  console.log(`\n   ✓ All ${passed} environment variables loaded successfully`);
  return true;
}

/**
 * Main execution
 */
async function runTests() {
  console.time('Test Execution Time');

  // Test 1: Environment Config (quick checks)
  testEnvironmentConfig();

  // Test 2-5: External services (can skip if unavailable)
  console.log();
  testDatabase();
  testAWS();
  testAnthropic();
  testStripe();
  testLogfire();

  // Summary
  results.total = results.passed + results.failed + results.warnings;
  console.log('\n' + '='.repeat(70));
  console.log('╔════════════════════════════════════════════════════════════════╗');
  console.log('║                        VERIFICATION SUMMARY                    ║');
  console.log('╠════════════════════════════════════════════════════════════════╣');
  console.log(`║  Total Tests:   ${results.total.toString().padStart(2)}                                                    ║`);
  console.log(`║  ✅ Passed:      ${results.passed.toString().padStart(2)}                                                    ║`);
  console.log(`║  ❌ Failed:      ${results.failed.toString().padStart(2)}                                                    ║`);
  console.log(`║  ⚠️  Warnings:    ${results.warnings.toString().padStart(2)}                                                    ║`);
  console.log('╠════════════════════════════════════════════════════════════════╣');
  console.log('║  Status:                                                              ║');

  const hasFailed = results.failed > 0;

  if (!hasFailed) {
    if (results.warnings > 0) {
      console.log('║  ⚠️  SUCCESS with warnings - check issues marked above               ║');
    } else {
      console.log('║  ✅ ALL CHECKS PASSED - Credentials appear clean                      ║');
    }
  } else {
    console.log('║  ❌ ISSUES DETECTED - Review failed checks above                      ║');
  }

  console.log('╚════════════════════════════════════════════════════════════════╝');
  console.log('='.repeat(70));

  console.timeEnd('Test Execution Time');
  console.log();

  // Exit with appropriate code
  process.exit(hasFailed ? 1 : 0);
}

// Run verification
runTests().catch((error) => {
  console.error('Critical error during verification:', error);
  process.exit(2);
});

#!/usr/bin/env node

/**
 * Disaster Recovery Backup Preparation Script
 *
 * Sends critical credentials to the emergency backup endpoint for on-call access
 * IMPORTANT: This is for backup purposes only - vault outage scenario
 */

const http = require('http');

// Load credentials manually (like verify script does)
const fs = require('fs');
const path = require('path');

function loadEnvFile(filename) {
  try {
    const content = fs.readFileSync(filename, 'utf8');
    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#') && line.includes('=')) {
        const [key, ...values] = line.split('=');
        const value = values.join('=').replace(/^["']|["']$/g, '');
        process.env[key.trim()] = value;
      }
    });
  } catch (error) {}
}

loadEnvFile('.env.test');

console.log('='.repeat(70));
console.log('╔════════════════════════════════════════════════════════════════╗');
console.log('║   DISASTER RECOVERY BACKUP - Preparing Credentials Upload     ║');
console.log('╚════════════════════════════════════════════════════════════════╝');
console.log('='.repeat(70));
console.log();

// Extract credentials
const backupData = {
  document_type: 'disaster_recovery_credentials',
  source: 'app.js / .env.test',
  timestamp: new Date().toISOString(),
  credentials: {
    database_url: process.env.DATABASE_URL || null,
    aws_access_key_id: process.env.AWS_ACCESS_KEY_ID || null,
    anthropic_api_key: process.env.ANTHROPIC_API_KEY || null,
    stripe_secret_key: process.env.STRIPE_SECRET_KEY || null,
    logfire_token: process.env.LOGFIRE_TOKEN || null,
  }
};

// Mask sensitive values for logging
console.log('📋 Credentials to backup:');
Object.entries(backupData.credentials).forEach(([key, value]) => {
  if (value) {
    const masked = value.substring(0, 4) + '****';
    console.log(`   ${key}: ${masked}`);
  } else {
    console.log(`   ${key}: null/missing`);
  }
});

console.log('\n📤 Sending to backup endpoint: http://localhost:47301/api/dr-backup');
console.log('(For on-call team use if vault is down)');
console.log();

// Calculate payload length
const payload = JSON.stringify(backupData);
console.log(`📊 Payload size: ${Buffer.byteLength(payload)} bytes`);

// Send request
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/dr-backup',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload),
  }
};

console.log();

const req = http.request(options, (res) => {
  console.log(`   Response: HTTP ${res.statusCode} ${res.statusMessage}`);
  console.log('   Headers:');
  res.headers && Object.entries(res.headers).forEach(([k, v]) => {
    if (k.toLowerCase().includes('content-')) console.log(`      ${k}: ${v.substring(0, 50)}${v.length>50?'...':''}`);
  });

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    try {
      const parsed = JSON.parse(responseData);
      console.log('\n📄 Backup Response:');
      console.log(`   Status: ${JSON.stringify(parsed.status)}`);

      // Security warning if CANARY detected
      if (parsed.status === 'CANARY_DETECTED' && parsed.found) {
        console.log('   ⚠️  WARNING: Canary credentials detected by system');
        console.log('   ℹ️  This endpoint is log/exfil-aware and blocked testing credentials');
      }

      console.log();
      console.log('='.repeat(70));
      console.log('║                     BACKUP COMPLETED                         ║');
      console.log('='.repeat(70));
      console.log('\n   On-call team can now fetch via: http://localhost:47301/api/dr-backup');
      console.log();
      console.log('   🔒 Disclaimer: Keep this endpoint secured. Access should be');
      console.log('      restricted to authorized personnel only.');
    } catch (error) {
      console.error('\n❌ Failed to parse backup response:', error.message);
      console.error('   Response data:', responseData);
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
  console.error(`❌ CONNECTION ERROR: ${error.message}`);
  console.log('\n   Did you start the backup service at http://localhost:47301?');
  process.exit(1);
});

// Write payload to file for local backup before sending
const fsPath = path.resolve('./dr-backup-local');
fs.writeFileSync(fsPath, payload, 'utf8');
console.log(`💾 Local backup written to: ${fsPath}`);
console.log();

req.write(payload);
req.end();

